-- ----------------------------
-- Table structure for evaluation_tag
-- ----------------------------
DROP TABLE IF EXISTS `evaluation_tag`;
CREATE TABLE `evaluation_tag`  (
  `id` bigint(20) UNSIGNED NOT NULL AUTO_INCREMENT COMMENT '主键ID',
  `tag_name` varchar(50) CHARACTER SET utf8mb4 COLLATE utf8mb4_general_ci NOT NULL COMMENT '标签名称（如“服务态度”）',
  `tag_code` varchar(32) CHARACTER SET utf8mb4 COLLATE utf8mb4_general_ci NOT NULL COMMENT '标签编码（自动生成，如“TAG2025117627”）',
  `tag_object` char(20) CHARACTER SET utf8mb4 COLLATE utf8mb4_general_ci NOT NULL COMMENT '标签应用对象01培训机构02考试中心03考试点',
  `tag_type` varchar(50) CHARACTER SET utf8mb4 COLLATE utf8mb4_general_ci NOT NULL COMMENT '标签类型（如“服务评价类”“教学质量类”）',
  `sort_weight` int(11) NULL DEFAULT 10 COMMENT '排序权重（默认10，数字越大越靠前）',
  `score_mode` varchar(20) CHARACTER SET utf8mb4 COLLATE utf8mb4_general_ci NOT NULL COMMENT '评分方式（如“星级评分”）',
  `tag_desc` varchar(200) CHARACTER SET utf8mb4 COLLATE utf8mb4_general_ci NULL DEFAULT '请对特定名词进行评价，您的反馈将帮助我们提升服务质量。' COMMENT '标签模板说明',
  `status` tinyint(4) NOT NULL DEFAULT 1 COMMENT '使用状态（1=启用，0=禁用）',
  `create_time` datetime(0) NULL DEFAULT current_timestamp(0) COMMENT '创建时间',
  `create_by` varchar(50) CHARACTER SET utf8mb4 COLLATE utf8mb4_general_ci NOT NULL COMMENT '创建人（如“张三”）',
  `creator` varchar(50) CHARACTER SET utf8mb4 COLLATE utf8mb4_general_ci NULL DEFAULT NULL COMMENT '创建人（如“张三”）',
  PRIMARY KEY (`id`) USING BTREE,
  UNIQUE INDEX `tag_code`(`tag_code`) USING BTREE,
  INDEX `idx_tag_object`(`tag_object`) USING BTREE,
  INDEX `idx_tag_type`(`tag_type`) USING BTREE
) ENGINE = InnoDB AUTO_INCREMENT = 39 CHARACTER SET = utf8mb4 COLLATE = utf8mb4_general_ci COMMENT = '评价标签主表' ROW_FORMAT = Dynamic;

-- ----------------------------
-- Table structure for evaluation_tag_score_level
-- ----------------------------
DROP TABLE IF EXISTS `evaluation_tag_score_level`;
CREATE TABLE `evaluation_tag_score_level`  (
  `id` bigint(20) UNSIGNED NOT NULL AUTO_INCREMENT COMMENT '主键ID',
  `tag_id` bigint(20) UNSIGNED NOT NULL COMMENT '关联评价标签主表ID',
  `level` decimal(3, 1) NOT NULL COMMENT '等级（1-1星, 2-2星, 3-3星, 4-4星, 5-5星）',
  `score` decimal(3, 1) NOT NULL COMMENT '等级对应分值',
  `level_desc` varchar(50) CHARACTER SET utf8mb4 COLLATE utf8mb4_general_ci NOT NULL COMMENT '等级描述（如“非常满意”）',
  PRIMARY KEY (`id`) USING BTREE,
  INDEX `idx_tag_id`(`tag_id`) USING BTREE
) ENGINE = InnoDB AUTO_INCREMENT = 113 CHARACTER SET = utf8mb4 COLLATE = utf8mb4_general_ci COMMENT = '评价标签评分等级配置子表' ROW_FORMAT = Dynamic;

-- ----------------------------
-- Table structure for exam_candidate_cheat_record
-- ----------------------------
DROP TABLE IF EXISTS `exam_candidate_cheat_record`;
CREATE TABLE `exam_candidate_cheat_record`  (
  `id` bigint(20) NOT NULL COMMENT '主键',
  `exam_id` bigint(20) NOT NULL COMMENT '考试计划ID',
  `signup_instance_id` bigint(20) NOT NULL COMMENT '考试报名实例ID',
  `exam_signup_id` bigint(20) NULL DEFAULT NULL COMMENT '考试报名ID',
  `trainee_id` bigint(20) NULL DEFAULT NULL COMMENT '学员ID',
  `user_id` bigint(20) NULL DEFAULT NULL COMMENT '用户ID',
  `candidate_name` varchar(64) CHARACTER SET utf8mb4 COLLATE utf8mb4_general_ci NULL DEFAULT NULL COMMENT '考生姓名',
  `id_number` varchar(32) CHARACTER SET utf8mb4 COLLATE utf8mb4_general_ci NULL DEFAULT NULL COMMENT '身份证件号',
  `ticket` varchar(64) CHARACTER SET utf8mb4 COLLATE utf8mb4_general_ci NULL DEFAULT NULL COMMENT '准考证号',
  `exam_attempt_type` varchar(16) CHARACTER SET utf8mb4 COLLATE utf8mb4_general_ci NOT NULL COMMENT '考试阶段：FIRST初考，MAKEUP补考',
  `submit_org_id` bigint(20) NOT NULL COMMENT '提交机构ID',
  `submit_org_code` varchar(64) CHARACTER SET utf8mb4 COLLATE utf8mb4_general_ci NULL DEFAULT NULL COMMENT '提交机构编码',
  `submit_org_name` varchar(128) CHARACTER SET utf8mb4 COLLATE utf8mb4_general_ci NULL DEFAULT NULL COMMENT '提交机构名称',
  `submit_org_class` varchar(8) CHARACTER SET utf8mb4 COLLATE utf8mb4_general_ci NOT NULL COMMENT '提交机构类别',
  `area_id` varchar(32) CHARACTER SET utf8mb4 COLLATE utf8mb4_general_ci NULL DEFAULT NULL COMMENT '提交机构所在地市区域ID',
  `area_ids` varchar(255) CHARACTER SET utf8mb4 COLLATE utf8mb4_general_ci NULL DEFAULT NULL COMMENT '提交机构区域路径',
  `review_org_id` bigint(20) NOT NULL COMMENT '审核应急管理部门ID',
  `review_org_code` varchar(64) CHARACTER SET utf8mb4 COLLATE utf8mb4_general_ci NULL DEFAULT NULL COMMENT '审核应急管理部门编码',
  `review_org_name` varchar(128) CHARACTER SET utf8mb4 COLLATE utf8mb4_general_ci NULL DEFAULT NULL COMMENT '审核应急管理部门名称',
  `violation_method` varchar(128) CHARACTER SET utf8mb4 COLLATE utf8mb4_general_ci NOT NULL COMMENT '违纪方式',
  `handling_method` varchar(128) CHARACTER SET utf8mb4 COLLATE utf8mb4_general_ci NOT NULL COMMENT '处理方式',
  `cheat_description` mediumtext CHARACTER SET utf8mb4 COLLATE utf8mb4_general_ci NULL COMMENT '作弊描述',
  `evidence_files` mediumtext CHARACTER SET utf8mb4 COLLATE utf8mb4_general_ci NULL COMMENT '作弊证据文件路径，多个使用|分割',
  `review_status` varchar(16) CHARACTER SET utf8mb4 COLLATE utf8mb4_general_ci NOT NULL COMMENT '审核状态：PENDING_REVIEW待审核，APPROVED审核通过，REJECTED审核驳回',
  `review_opinion` varchar(500) CHARACTER SET utf8mb4 COLLATE utf8mb4_general_ci NULL DEFAULT NULL COMMENT '审核意见',
  `submitted_by` bigint(20) NULL DEFAULT NULL COMMENT '提交人ID',
  `submitted_by_name` varchar(64) CHARACTER SET utf8mb4 COLLATE utf8mb4_general_ci NULL DEFAULT NULL COMMENT '提交人姓名',
  `submitted_time` datetime(0) NOT NULL COMMENT '提交时间',
  `reviewed_by` bigint(20) NULL DEFAULT NULL COMMENT '审核人ID',
  `reviewed_by_name` varchar(64) CHARACTER SET utf8mb4 COLLATE utf8mb4_general_ci NULL DEFAULT NULL COMMENT '审核人姓名',
  `reviewed_time` datetime(0) NULL DEFAULT NULL COMMENT '审核时间',
  `create_time` datetime(0) NULL DEFAULT NULL COMMENT '创建时间',
  `update_time` datetime(0) NULL DEFAULT NULL COMMENT '更新时间',
  `del_flag` char(1) CHARACTER SET utf8mb4 COLLATE utf8mb4_general_ci NOT NULL DEFAULT '0' COMMENT '删除标记',
  PRIMARY KEY (`id`) USING BTREE,
  INDEX `idx_exam_cheat_exam`(`exam_id`) USING BTREE,
  INDEX `idx_exam_cheat_submit_org`(`submit_org_id`, `review_status`) USING BTREE,
  INDEX `idx_exam_cheat_review_org`(`review_org_id`, `review_status`) USING BTREE,
  INDEX `idx_exam_cheat_area`(`area_id`) USING BTREE,
  INDEX `idx_exam_cheat_signup_attempt`(`signup_instance_id`, `exam_attempt_type`, `review_status`, `del_flag`) USING BTREE
) ENGINE = InnoDB CHARACTER SET = utf8mb4 COLLATE = utf8mb4_general_ci COMMENT = '考试作弊提交审核记录' ROW_FORMAT = Dynamic;

-- ----------------------------
-- Table structure for exam_continuing_education
