-- ----------------------------
-- Table structure for exam_evaluate_record
-- ----------------------------
DROP TABLE IF EXISTS `exam_evaluate_record`;
CREATE TABLE `exam_evaluate_record`  (
  `id` bigint(20) UNSIGNED NOT NULL AUTO_INCREMENT COMMENT '主键ID',
  `staff_id` tinyint(4) NOT NULL COMMENT '人员编号',
  `evaluator_name` varchar(50) CHARACTER SET utf8mb4 COLLATE utf8mb4_general_ci NULL DEFAULT NULL COMMENT '考评员姓名',
  `exam_id` bigint(20) NOT NULL COMMENT '考试id',
  `exam_name` varchar(50) CHARACTER SET utf8mb4 COLLATE utf8mb4_general_ci NULL DEFAULT NULL COMMENT '考试名称',
  `exam_point_id` bigint(20) NOT NULL COMMENT '考试点id',
  `exam_point_name` varchar(100) CHARACTER SET utf8mb4 COLLATE utf8mb4_general_ci NOT NULL COMMENT '考试点名称',
  `exam_room_id` bigint(20) NULL DEFAULT NULL COMMENT '考场id',
  `exam_room_name` varchar(100) CHARACTER SET utf8mb4 COLLATE utf8mb4_general_ci NULL DEFAULT NULL COMMENT '考场名称',
  `exam_start_time` datetime(0) NULL DEFAULT NULL COMMENT '考试开始时间',
  `exam_end_time` datetime(0) NULL DEFAULT NULL COMMENT '考试结束时间',
  `exam_project_name` varchar(100) CHARACTER SET utf8mb4 COLLATE utf8mb4_general_ci NULL DEFAULT NULL COMMENT '考试项目名称',
  `qualification_type` char(20) CHARACTER SET utf8mb4 COLLATE utf8mb4_general_ci NULL DEFAULT NULL COMMENT '资格类型',
  `sign_in_time` datetime(0) NULL DEFAULT NULL COMMENT '签到时间',
  `sign_out_time` datetime(0) NULL DEFAULT NULL COMMENT '签退时间',
  `sign_in_way` varchar(50) CHARACTER SET utf8mb4 COLLATE utf8mb4_general_ci NULL DEFAULT NULL COMMENT '签到方式',
  `create_time` datetime(0) NULL DEFAULT current_timestamp(0) COMMENT '创建时间',
  `update_time` datetime(0) NULL DEFAULT current_timestamp(0) ON UPDATE CURRENT_TIMESTAMP(0) COMMENT '修改时间',
  PRIMARY KEY (`id`) USING BTREE
) ENGINE = InnoDB AUTO_INCREMENT = 1 CHARACTER SET = utf8mb4 COLLATE = utf8mb4_general_ci COMMENT = '考评记录表' ROW_FORMAT = Dynamic;

-- ----------------------------
-- Table structure for exam_inspect_record
-- ----------------------------
DROP TABLE IF EXISTS `exam_inspect_record`;
CREATE TABLE `exam_inspect_record`  (
  `id` bigint(20) UNSIGNED NOT NULL AUTO_INCREMENT COMMENT '主键ID',
  `staff_id` tinyint(4) NOT NULL COMMENT '人员编号',
  `inspect_name` varchar(50) CHARACTER SET utf8mb4 COLLATE utf8mb4_general_ci NULL DEFAULT NULL COMMENT '巡考员姓名',
  `exam_id` bigint(20) NOT NULL COMMENT '考试id',
  `exam_name` varchar(50) CHARACTER SET utf8mb4 COLLATE utf8mb4_general_ci NULL DEFAULT NULL COMMENT '考试名称',
  `exam_project_name` varchar(50) CHARACTER SET utf8mb4 COLLATE utf8mb4_general_ci NULL DEFAULT NULL COMMENT '考试项目名称',
  `exam_address` varchar(100) CHARACTER SET utf8mb4 COLLATE utf8mb4_general_ci NULL DEFAULT NULL COMMENT '考试地址',
  `exam_start_time` datetime(0) NULL DEFAULT NULL COMMENT '考试开始时间',
  `exam_end_time` datetime(0) NULL DEFAULT NULL COMMENT '考试结束时间',
  `qualification_level` char(20) CHARACTER SET utf8mb4 COLLATE utf8mb4_general_ci NULL DEFAULT NULL COMMENT '巡考资格',
  `qualification_type` char(20) CHARACTER SET utf8mb4 COLLATE utf8mb4_general_ci NULL DEFAULT NULL COMMENT '资格类型',
  `sign_record` varchar(50) CHARACTER SET utf8mb4 COLLATE utf8mb4_general_ci NULL DEFAULT NULL COMMENT '签到记录',
  `create_time` datetime(0) NULL DEFAULT current_timestamp(0) COMMENT '创建时间',
  `update_time` datetime(0) NULL DEFAULT current_timestamp(0) ON UPDATE CURRENT_TIMESTAMP(0) COMMENT '修改时间',
  PRIMARY KEY (`id`) USING BTREE
) ENGINE = InnoDB AUTO_INCREMENT = 1 CHARACTER SET = utf8mb4 COLLATE = utf8mb4_general_ci COMMENT = '巡考记录表' ROW_FORMAT = Dynamic;

-- ----------------------------
-- Table structure for exam_invigilate_record
-- ----------------------------
DROP TABLE IF EXISTS `exam_invigilate_record`;
CREATE TABLE `exam_invigilate_record`  (
  `id` bigint(20) UNSIGNED NOT NULL AUTO_INCREMENT COMMENT '主键ID',
  `staff_id` tinyint(4) NOT NULL COMMENT '人员编号',
