  `exam_id` bigint(20) NOT NULL COMMENT '考试id',
  `exam_name` varchar(50) CHARACTER SET utf8mb4 COLLATE utf8mb4_general_ci NULL DEFAULT NULL COMMENT '考试名称',
  `exam_project_name` varchar(50) CHARACTER SET utf8mb4 COLLATE utf8mb4_general_ci NULL DEFAULT NULL COMMENT '考试项目名称',
  `exam_address` varchar(100) CHARACTER SET utf8mb4 COLLATE utf8mb4_general_ci NULL DEFAULT NULL COMMENT '考试地址',
  `exam_start_time` datetime(0) NULL DEFAULT NULL COMMENT '考试开始时间',
  `exam_end_time` datetime(0) NULL DEFAULT NULL COMMENT '考试结束时间',
  `qualification_level` char(20) CHARACTER SET utf8mb4 COLLATE utf8mb4_general_ci NULL DEFAULT NULL COMMENT '监考资格',
  `qualification_type` char(20) CHARACTER SET utf8mb4 COLLATE utf8mb4_general_ci NULL DEFAULT NULL COMMENT '资格类型',
  `sign_record` varchar(50) CHARACTER SET utf8mb4 COLLATE utf8mb4_general_ci NULL DEFAULT NULL COMMENT '签到记录',
  `create_time` datetime(0) NULL DEFAULT current_timestamp(0) COMMENT '创建时间',
  `update_time` datetime(0) NULL DEFAULT current_timestamp(0) ON UPDATE CURRENT_TIMESTAMP(0) COMMENT '修改时间',
  PRIMARY KEY (`id`) USING BTREE
) ENGINE = InnoDB AUTO_INCREMENT = 1 CHARACTER SET = utf8mb4 COLLATE = utf8mb4_general_ci COMMENT = '监考记录表' ROW_FORMAT = Dynamic;

-- ----------------------------
-- Table structure for exam_perform_analysis
-- ----------------------------
DROP TABLE IF EXISTS `exam_perform_analysis`;
CREATE TABLE `exam_perform_analysis`  (
  `id` bigint(20) UNSIGNED NOT NULL AUTO_INCREMENT COMMENT '主键ID',
  `staff_id` bigint(20) NOT NULL COMMENT '考务人员编号',
  `staff_type` char(10) CHARACTER SET utf8mb4 COLLATE utf8mb4_general_ci NOT NULL COMMENT '考务人员类型（01-监考员，02-考评员，03-巡考员）',
  `name` varchar(50) CHARACTER SET utf8mb4 COLLATE utf8mb4_general_ci NOT NULL COMMENT '考务人员姓名',
  `exam_point_id` bigint(20) NOT NULL COMMENT '考试点id',
  `exam_point_name` varchar(100) CHARACTER SET utf8mb4 COLLATE utf8mb4_general_ci NOT NULL COMMENT '考试点名称',
  `area_ids` varchar(100) CHARACTER SET utf8mb4 COLLATE utf8mb4_general_ci NOT NULL COMMENT '行政区域路径',
  `area_id` varchar(50) CHARACTER SET utf8mb4 COLLATE utf8mb4_general_ci NOT NULL COMMENT '所属地市',
  `evaluation_type` varchar(50) CHARACTER SET utf8mb4 COLLATE utf8mb4_general_ci NOT NULL COMMENT '评定类型',
  `work_score` int(11) NOT NULL COMMENT '主观之工作态度评分',
  `attendance_score` int(11) NOT NULL COMMENT '主观之考勤质量评分',
  `discipline_score` int(11) NOT NULL COMMENT '主观之纪律遵守评分',
  `response_score` int(11) NOT NULL COMMENT '主观之任务响应评分',
  `service_score` int(11) NOT NULL COMMENT '主观之服务态度评分',
  `evaluation_good_score` int(11) NULL DEFAULT 0 COMMENT '客观之用户评价好评分',
  `evaluation_good_record` int(11) NULL DEFAULT 0 COMMENT '客观之用户评价好记录数',
  `evaluation_normal_score` int(11) NULL DEFAULT 0 COMMENT '客观之用户评价中评分',
  `evaluation_normal_record` int(11) NULL DEFAULT 0 COMMENT '客观之用户评价中记录数',
  `evaluation_bad_score` int(11) NULL DEFAULT 0 COMMENT '客观之用户评价差评分',
  `evaluation_bad_record` int(11) NULL DEFAULT 0 COMMENT '客观之用户评价差记录数',
  `complaint_score` int(11) NULL DEFAULT 0 COMMENT '客观之用户投诉评分',
  `complaint_record` int(11) NULL DEFAULT 0 COMMENT '客观之用户投诉记录数',
  `education_score` int(11) NULL DEFAULT 0 COMMENT '客观之继续教育评分',
  `education_record` int(11) NULL DEFAULT 0 COMMENT '客观之继续教育记录数',
  `subjective_score` int(11) NOT NULL COMMENT '主观评分',
  `objective_score` int(11) NOT NULL DEFAULT 0 COMMENT '客观评分',
  `total_score` int(11) NOT NULL COMMENT '总评分',
  `evaluation_level` varchar(50) CHARACTER SET utf8mb4 COLLATE utf8mb4_general_ci NOT NULL COMMENT '评定等级',
  `evaluation_comment` varchar(500) CHARACTER SET utf8mb4 COLLATE utf8mb4_general_ci NULL DEFAULT NULL COMMENT '评语',
  `evaluation_date` date NULL DEFAULT NULL COMMENT '评定日期',
  `evaluator` varchar(50) CHARACTER SET utf8mb4 COLLATE utf8mb4_general_ci NOT NULL COMMENT '评定人',
  `create_time` datetime(0) NULL DEFAULT current_timestamp(0) COMMENT '创建时间',
  `update_time` datetime(0) NULL DEFAULT current_timestamp(0) ON UPDATE CURRENT_TIMESTAMP(0) COMMENT '修改时间',
  PRIMARY KEY (`id`) USING BTREE,
  UNIQUE INDEX `uk_perform_analysis_staff_type`(`staff_id`, `evaluation_type`) USING BTREE
) ENGINE = InnoDB AUTO_INCREMENT = 10 CHARACTER SET = utf8mb4 COLLATE = utf8mb4_general_ci COMMENT = '履职分析表' ROW_FORMAT = Dynamic;

-- ----------------------------
-- Table structure for exam_staff
-- ----------------------------
DROP TABLE IF EXISTS `exam_staff`;
CREATE TABLE `exam_staff`  (
  `id` bigint(20) UNSIGNED NOT NULL AUTO_INCREMENT COMMENT '主键ID',
  `staff_type` tinyint(4) NOT NULL COMMENT '人员类型（01-监考员，02-考评员，03-巡考员）',
  `name` varchar(50) CHARACTER SET utf8mb4 COLLATE utf8mb4_general_ci NOT NULL COMMENT '姓名',
  `sex` char(1) CHARACTER SET utf8mb4 COLLATE utf8mb4_general_ci NOT NULL COMMENT '性别',
  `id_card_type` varchar(20) CHARACTER SET utf8mb4 COLLATE utf8mb4_general_ci NULL DEFAULT NULL COMMENT '证件类型：01身份证，02军官证，03护照，99其他',
  `area_id` varchar(20) CHARACTER SET utf8mb4 COLLATE utf8mb4_general_ci NOT NULL COMMENT '所属地市',
  `nation` varchar(20) CHARACTER SET utf8mb4 COLLATE utf8mb4_general_ci NULL DEFAULT NULL COMMENT '民族',
  `political_status` varchar(20) CHARACTER SET utf8mb4 COLLATE utf8mb4_general_ci NULL DEFAULT NULL COMMENT '政治面貌字典编码',
  `education_level` varchar(50) CHARACTER SET utf8mb4 COLLATE utf8mb4_general_ci NULL DEFAULT NULL COMMENT '文化程度',
  `phone` varchar(14) CHARACTER SET utf8mb4 COLLATE utf8mb4_general_ci NOT NULL COMMENT '电话',
  `work_schedule_type` varchar(2) CHARACTER SET utf8mb4 COLLATE utf8mb4_general_ci NULL DEFAULT NULL COMMENT '工作类型：1兼职，2全职',
  `birth` date NULL DEFAULT NULL COMMENT '出生日期',
  `position` varchar(50) CHARACTER SET utf8mb4 COLLATE utf8mb4_general_ci NULL DEFAULT NULL COMMENT '职务',
  `work_unit` varchar(100) CHARACTER SET utf8mb4 COLLATE utf8mb4_general_ci NULL DEFAULT NULL COMMENT '工作单位',
  `filing_authority_id` bigint(20) NULL DEFAULT NULL COMMENT '备案机关ID（发证机关/应急管理局）',
  `filing_authority_name` varchar(200) CHARACTER SET utf8mb4 COLLATE utf8mb4_general_ci NULL DEFAULT NULL COMMENT '备案机关名称（发证机关/应急管理局）',
  `recent_photo` varchar(500) CHARACTER SET utf8mb4 COLLATE utf8mb4_general_ci NULL DEFAULT NULL COMMENT '考评员近期照片路径',
  `status` char(10) CHARACTER SET utf8mb4 COLLATE utf8mb4_general_ci NOT NULL DEFAULT '0' COMMENT '状态 0-启用 1-禁用',
  `exam_point_id` bigint(20) NOT NULL COMMENT '所属考试点id',
  `exam_point_name` varchar(100) CHARACTER SET utf8mb4 COLLATE utf8mb4_general_ci NOT NULL COMMENT '所属考试点名称',
  `exam_center_id` bigint(20) NULL DEFAULT NULL COMMENT '所属考试中心id',
  `exam_center_name` varchar(100) CHARACTER SET utf8mb4 COLLATE utf8mb4_general_ci NULL DEFAULT NULL COMMENT '所属考试中心名称',
  `qualification_type` char(20) CHARACTER SET utf8mb4 COLLATE utf8mb4_general_ci NULL DEFAULT NULL COMMENT '资格类型，01主考员、02副考员、03监考员',
  `qualification_level` char(20) CHARACTER SET utf8mb4 COLLATE utf8mb4_general_ci NULL DEFAULT NULL COMMENT '资格等级（01初级、02中级、03高级）',
  `scope` varchar(100) CHARACTER SET utf8mb4 COLLATE utf8mb4_general_ci NOT NULL COMMENT '范围',
  `evaluate_work_type` text CHARACTER SET utf8mb4 COLLATE utf8mb4_general_ci NULL COMMENT '考评工种，存操作项目，多个英文逗号分隔',
  `exam_type` char(20) CHARACTER SET utf8mb4 COLLATE utf8mb4_general_ci NULL DEFAULT NULL COMMENT '监考类型、执考类型、巡考类型，有01初证、02复证、03换证',
  `exam_level` char(20) CHARACTER SET utf8mb4 COLLATE utf8mb4_general_ci NULL DEFAULT NULL COMMENT '监考类别、执考类别、巡考类别，有01主要负责人、02安全生产管理人员、03特种作业人员',
  `certificate_no` varchar(50) CHARACTER SET utf8mb4 COLLATE utf8mb4_general_ci NULL DEFAULT NULL COMMENT '证书编号',
  `certificate_start` date NULL DEFAULT NULL COMMENT '发证日期',
  `certificate_end` date NULL DEFAULT NULL COMMENT '有效期',
  `other_certificate` varchar(1000) CHARACTER SET utf8mb4 COLLATE utf8mb4_general_ci NULL DEFAULT NULL COMMENT '其他证书图片路径',
  `country_examiner_id` bigint(20) NULL DEFAULT NULL COMMENT '国家平台考评员ID',
  `create_time` datetime(0) NULL DEFAULT current_timestamp(0) COMMENT '创建时间',
  `update_time` datetime(0) NULL DEFAULT current_timestamp(0) ON UPDATE CURRENT_TIMESTAMP(0) COMMENT '修改时间',
  `del_flag` char(1) CHARACTER SET utf8mb4 COLLATE utf8mb4_general_ci NULL DEFAULT '0' COMMENT '删除标志(0=正常,1=删除)',
  `tenant_id` bigint(20) NOT NULL DEFAULT 1 COMMENT '租户',
  `certificate_path` varchar(1000) CHARACTER SET utf8mb4 COLLATE utf8mb4_general_ci NULL DEFAULT NULL COMMENT '证书图片路径',
  `user_id` bigint(20) NULL DEFAULT NULL COMMENT '用户ID',
  `id_number` varchar(32) CHARACTER SET utf8mb4 COLLATE utf8mb4_general_ci NULL DEFAULT NULL COMMENT '身份证号',
  `area_ids` varchar(100) CHARACTER SET utf8mb4 COLLATE utf8mb4_general_ci NULL DEFAULT NULL COMMENT '行政区域路径',
  `is_sms_verification` tinyint(4) NULL DEFAULT NULL COMMENT '是否强制短信验证(考评员)',
  PRIMARY KEY (`id`) USING BTREE,
  INDEX `idx_staff_type`(`staff_type`) USING BTREE,
  INDEX `idx_exam_staff_exam_center_id`(`exam_center_id`) USING BTREE,
  INDEX `idx_exam_staff_type_area_center`(`staff_type`, `area_id`, `exam_center_id`) USING BTREE,
  INDEX `idx_exam_staff_filing_authority_id`(`filing_authority_id`) USING BTREE,
  INDEX `idx_exam_staff_id_card_type_id_number`(`id_card_type`, `id_number`) USING BTREE,
  INDEX `idx_exam_staff_work_type`(`work_schedule_type`) USING BTREE,
  INDEX `idx_exam_staff_political_status`(`political_status`) USING BTREE
) ENGINE = InnoDB AUTO_INCREMENT = 2063799881707872259 CHARACTER SET = utf8mb4 COLLATE = utf8mb4_general_ci COMMENT = '考务人员表' ROW_FORMAT = Dynamic;

-- ----------------------------
-- Table structure for exam_violation_record
-- ----------------------------
DROP TABLE IF EXISTS `exam_violation_record`;
CREATE TABLE `exam_violation_record`  (
  `id` bigint(20) UNSIGNED NOT NULL AUTO_INCREMENT COMMENT '主键ID',
  `staff_type` char(10) CHARACTER SET utf8mb4 COLLATE utf8mb4_general_ci NOT NULL COMMENT '人员类型（01-监考员，02-考评员，03-巡考员）',
  `staff_id` bigint(20) UNSIGNED NOT NULL COMMENT '人员编号',
  `name` varchar(20) CHARACTER SET utf8mb4 COLLATE utf8mb4_general_ci NOT NULL COMMENT '人员姓名',
  `area_ids` varchar(100) CHARACTER SET utf8mb4 COLLATE utf8mb4_general_ci NOT NULL COMMENT '行政区域路径',
  `area_id` varchar(50) CHARACTER SET utf8mb4 COLLATE utf8mb4_general_ci NOT NULL COMMENT '所属地市',
  `exam_point_id` bigint(20) NOT NULL COMMENT '考试点id',
  `exam_point_name` varchar(100) CHARACTER SET utf8mb4 COLLATE utf8mb4_general_ci NOT NULL COMMENT '考试点名称',
  `violation_kind` varchar(20) CHARACTER SET utf8mb4 COLLATE utf8mb4_general_ci NULL DEFAULT NULL COMMENT '违规类型',
  `violation_context` varchar(500) CHARACTER SET utf8mb4 COLLATE utf8mb4_general_ci NULL DEFAULT NULL COMMENT '违规内容',
  `violation_time` datetime(0) NULL DEFAULT current_timestamp(0) COMMENT '违规时间',
  `resolve_result` varchar(20) CHARACTER SET utf8mb4 COLLATE utf8mb4_general_ci NULL DEFAULT NULL COMMENT '处理结果',
  `resolve_people` varchar(20) CHARACTER SET utf8mb4 COLLATE utf8mb4_general_ci NULL DEFAULT NULL COMMENT '处理人',
  `resolve_dept` varchar(50) CHARACTER SET utf8mb4 COLLATE utf8mb4_general_ci NULL DEFAULT NULL COMMENT '处理部门',
  `create_time` datetime(0) NULL DEFAULT current_timestamp(0) COMMENT '创建时间',
  `update_time` datetime(0) NULL DEFAULT current_timestamp(0) ON UPDATE CURRENT_TIMESTAMP(0) COMMENT '修改时间',
  `accessary_file` varchar(200) CHARACTER SET utf8mb4 COLLATE utf8mb4_general_ci NULL DEFAULT NULL COMMENT '附件',
  PRIMARY KEY (`id`) USING BTREE
) ENGINE = InnoDB AUTO_INCREMENT = 2061990135371780098 CHARACTER SET = utf8mb4 COLLATE = utf8mb4_general_ci COMMENT = '违规记录表' ROW_FORMAT = Dynamic;

-- ----------------------------
-- Table structure for exm_exam
-- ----------------------------
DROP TABLE IF EXISTS `exm_exam`;
CREATE TABLE `exm_exam`  (
  `id` bigint(20) NOT NULL AUTO_INCREMENT COMMENT 'id',
  `type` varchar(10) CHARACTER SET utf8mb4 COLLATE utf8mb4_general_ci NULL DEFAULT NULL COMMENT '1理论 2实操',
  `name` varchar(100) CHARACTER SET utf8mb4 COLLATE utf8mb4_general_ci NOT NULL COMMENT '考试计划名称',
  `sequence` int(11) NULL DEFAULT NULL COMMENT '序号',
  `alias` varchar(100) CHARACTER SET utf8mb4 COLLATE utf8mb4_general_ci NULL DEFAULT NULL COMMENT '考试计划别名',
  `exam_plan_type` varchar(10) CHARACTER SET utf8mb4 COLLATE utf8mb4_general_ci NULL DEFAULT NULL COMMENT '考试计划类型，ag：主要负责人和安全生产管理人员，tz：特种作业人员',
  `training_type` varchar(10) CHARACTER SET utf8mb4 COLLATE utf8mb4_general_ci NULL DEFAULT NULL COMMENT '考试类型(1初训 2复训)',
  `exam_codes` varchar(255) CHARACTER SET utf8mb4 COLLATE utf8mb4_general_ci NULL DEFAULT NULL COMMENT '人员类型|作业类别|操作项目 编码',
  `exam_labels` varchar(500) CHARACTER SET utf8mb4 COLLATE utf8mb4_general_ci NULL DEFAULT NULL COMMENT '人员类型|作业类别|操作项目 名称',
  `examinee_number` int(11) NULL DEFAULT NULL COMMENT '考试人数',
  `exam_center_id` bigint(20) NULL DEFAULT NULL COMMENT '考试中心id',
  `place_id` bigint(20) NULL DEFAULT NULL COMMENT '考点id',
  `place_room_id` bigint(20) NULL DEFAULT NULL COMMENT '考场id',
  `exam_mode` varchar(10) CHARACTER SET utf8mb4 COLLATE utf8mb4_general_ci NULL DEFAULT NULL COMMENT '考试实施方式(1流水考试 2固定场次)',
  `theory_exam_method` varchar(10) CHARACTER SET utf8mb4 COLLATE utf8mb4_general_ci NULL DEFAULT NULL COMMENT '理论考试实施方式,1机考2笔答',
  `prac_exam_method` varchar(10) CHARACTER SET utf8mb4 COLLATE utf8mb4_general_ci NULL DEFAULT NULL COMMENT '实操考试实施方式,1人工考评2实操设备考评',
  `remark` varchar(500) CHARACTER SET utf8mb4 COLLATE utf8mb4_general_ci NULL DEFAULT NULL COMMENT '备注',
  `exam_date` date NULL DEFAULT NULL COMMENT '考试日期',
  `exam_period_type` varchar(10) CHARACTER SET utf8mb4 COLLATE utf8mb4_general_ci NULL DEFAULT NULL COMMENT '场次(1上午 2下午)',
  `exam_period_start_time` datetime(0) NULL DEFAULT NULL COMMENT '场次开始时间',
  `exam_period_end_time` datetime(0) NULL DEFAULT NULL COMMENT '场次结束时间',
  `immediate_retake` varchar(1) CHARACTER SET utf8mb4 COLLATE utf8mb4_general_ci NULL DEFAULT NULL COMMENT '是否当场补考(0否 1是)',
  `retake_start_time` datetime(0) NULL DEFAULT NULL COMMENT '补考开始时间',
  `retake_end_time` datetime(0) NULL DEFAULT NULL COMMENT '补考结束时间',
  `limit_start_time` varchar(1) CHARACTER SET utf8mb4 COLLATE utf8mb4_general_ci NULL DEFAULT NULL COMMENT '是否限制考试计划开始时间(0否 1是)',
  `publish_status` varchar(10) CHARACTER SET utf8mb4 COLLATE utf8mb4_general_ci NULL DEFAULT NULL COMMENT '发布状态(0未发布 1发布)',
  `audit_status` varchar(10) CHARACTER SET utf8mb4 COLLATE utf8mb4_general_ci NULL DEFAULT NULL COMMENT '审批状态(0未提交 1待审批 2通过 3不通过)',
  `exam_status` varchar(20) CHARACTER SET utf8mb4 COLLATE utf8mb4_general_ci NULL DEFAULT NULL COMMENT '考试状态(对外展示)',
  `apply_number` int(11) NULL DEFAULT NULL COMMENT '考试申请人数',
  `country_plan_id` bigint(20) NULL DEFAULT NULL COMMENT '国家考试计划ID',
  `create_by` varchar(64) CHARACTER SET utf8mb4 COLLATE utf8mb4_general_ci NOT NULL DEFAULT '' COMMENT '创建人',
  `create_time` datetime(0) NOT NULL DEFAULT current_timestamp(0) COMMENT '创建时间',
  `update_by` varchar(64) CHARACTER SET utf8mb4 COLLATE utf8mb4_general_ci NOT NULL DEFAULT '' COMMENT '修改人',
  `update_time` datetime(0) NOT NULL DEFAULT current_timestamp(0) ON UPDATE CURRENT_TIMESTAMP(0) COMMENT '修改时间',
  `del_flag` char(1) CHARACTER SET utf8mb4 COLLATE utf8mb4_general_ci NOT NULL DEFAULT '0' COMMENT '删除标识（0未删 1删除）',
  `tenant_id` bigint(20) NULL DEFAULT NULL COMMENT '租户id',
  `charge` bigint(20) NULL DEFAULT NULL COMMENT '考试费用',
  `question_type` varchar(2) CHARACTER SET utf8mb4 COLLATE utf8mb4_general_ci NULL DEFAULT NULL COMMENT '考题类型(1旧考题 2新考题)',
  PRIMARY KEY (`id`) USING BTREE
) ENGINE = InnoDB AUTO_INCREMENT = 2099110611000080012 CHARACTER SET = utf8mb4 COLLATE = utf8mb4_general_ci COMMENT = '考试' ROW_FORMAT = Dynamic;

-- ----------------------------
-- Table structure for exm_exam_apply_class
-- ----------------------------
DROP TABLE IF EXISTS `exm_exam_apply_class`;
CREATE TABLE `exm_exam_apply_class`  (
  `id` bigint(20) UNSIGNED NOT NULL AUTO_INCREMENT COMMENT 'ID',
  `class_id` bigint(20) NOT NULL COMMENT '班级ID',
  `report_date` datetime(0) NULL DEFAULT NULL COMMENT '报备日期',
  `city_approver_id` bigint(20) NULL DEFAULT NULL COMMENT '市局审批人ID',
  `city_approver` varchar(200) CHARACTER SET utf8mb4 COLLATE utf8mb4_general_ci NULL DEFAULT NULL COMMENT '市局审批人',
  `city_comment` varchar(500) CHARACTER SET utf8mb4 COLLATE utf8mb4_general_ci NULL DEFAULT NULL COMMENT '市局意见',
  `city_approval_date` datetime(0) NULL DEFAULT NULL COMMENT '市局审批时间',
  `province_approver_id` bigint(20) NULL DEFAULT NULL COMMENT '省局审批人ID',
  `province_approver` varchar(200) CHARACTER SET utf8mb4 COLLATE utf8mb4_general_ci NULL DEFAULT NULL COMMENT '省局审批人',
  `province_comment` varchar(500) CHARACTER SET utf8mb4 COLLATE utf8mb4_general_ci NULL DEFAULT NULL COMMENT '省局意见',
  `province_approval_date` datetime(0) NULL DEFAULT NULL COMMENT '省局审批时间',
  `status` tinyint(1) NOT NULL COMMENT '审批状态',
  `create_time` datetime(0) NULL DEFAULT current_timestamp(0) COMMENT '创建时间',
  `create_by` varchar(20) CHARACTER SET utf8mb4 COLLATE utf8mb4_general_ci NULL DEFAULT '' COMMENT '创建者',
  `update_time` datetime(0) NULL DEFAULT NULL COMMENT '更新时间',
  `update_by` varchar(20) CHARACTER SET utf8mb4 COLLATE utf8mb4_general_ci NULL DEFAULT NULL COMMENT '更新者',
  `del_flag` char(1) CHARACTER SET utf8mb4 COLLATE utf8mb4_general_ci NULL DEFAULT '0' COMMENT '删除标志（0=正常，1=删除）',
  `remark` varchar(500) CHARACTER SET utf8mb4 COLLATE utf8mb4_general_ci NULL DEFAULT '' COMMENT '备注',
  `tenant_id` bigint(20) NULL DEFAULT NULL COMMENT '租户ID',
  `project_training_num` int(11) NULL DEFAULT NULL COMMENT '项目训练次数（申报后保存）',
  `institution_id` bigint(20) NULL DEFAULT NULL COMMENT '所属机构ID',
  `current_node` tinyint(4) NULL DEFAULT 0 COMMENT '当前节点',
  `previous_line` tinyint(4) NULL DEFAULT NULL COMMENT '上一流程操作',
  `current_approval_org` bigint(20) NULL DEFAULT NULL COMMENT '当前审批机构',
  `previous_node` tinyint(4) NULL DEFAULT NULL COMMENT '上一流程节点',
  `inner_status` tinyint(4) NULL DEFAULT NULL COMMENT '内审状态',
  `exam_center_id` bigint(20) NULL DEFAULT NULL COMMENT '考试中心ID',
  `theory_exam_point_id` bigint(20) NULL DEFAULT NULL COMMENT '理论考试点ID',
  `theory_exam_start_time` datetime(0) NULL DEFAULT NULL COMMENT '理论考试开始时间',
  `theory_exam_end_time` datetime(0) NULL DEFAULT NULL COMMENT '理论考试结束时间',
  `practice_exam_point_id` bigint(20) NULL DEFAULT NULL COMMENT '实操考试点ID',
  `practice_exam_start_time` datetime(0) NULL DEFAULT NULL COMMENT '实操考试开始时间',
  `practice_exam_end_time` datetime(0) NULL DEFAULT NULL COMMENT '实操考试结束时间',
  PRIMARY KEY (`id`) USING BTREE
) ENGINE = InnoDB AUTO_INCREMENT = 332393909088948226 CHARACTER SET = utf8mb4 COLLATE = utf8mb4_general_ci COMMENT = '班级考试资格申请' ROW_FORMAT = Dynamic;

