-- ----------------------------
-- Table structure for exm_exam_signup
-- ----------------------------
DROP TABLE IF EXISTS `exm_exam_signup`;
CREATE TABLE `exm_exam_signup`  (
  `id` bigint(20) NOT NULL AUTO_INCREMENT COMMENT 'id',
  `exam_codes` varchar(255) CHARACTER SET utf8mb4 COLLATE utf8mb4_general_ci NULL DEFAULT NULL COMMENT '人员类型|作业类别|操作项目 编码',
  `exam_labels` varchar(500) CHARACTER SET utf8mb4 COLLATE utf8mb4_general_ci NULL DEFAULT NULL COMMENT '人员类型|作业类别|操作项目 名称',
  `trainee_id` bigint(20) NULL DEFAULT NULL COMMENT '报名学员id--traineeSign',
  `class_id` bigint(20) NULL DEFAULT NULL COMMENT '班级id',
  `institution_id` bigint(20) NULL DEFAULT NULL COMMENT '机构id',
  `issue_org_id` bigint(20) NULL DEFAULT NULL COMMENT '发证机关ID',
  `issue_org_name` varchar(255) CHARACTER SET utf8mb4 COLLATE utf8mb4_general_ci NULL DEFAULT NULL COMMENT '发证机关名称',
  `instance_id` bigint(20) NULL DEFAULT NULL COMMENT '考试实例id',
  `allow_signup` tinyint(4) NULL DEFAULT NULL COMMENT '是否允许报名',
  `theory_exempt_flag` char(1) CHARACTER SET utf8mb4 COLLATE utf8mb4_general_ci NOT NULL DEFAULT '0' COMMENT '是否免理论直接报考实操：1是 0否',
  `signup_status` varchar(10) CHARACTER SET utf8mb4 COLLATE utf8mb4_general_ci NULL DEFAULT NULL COMMENT '报名状态 0未报名 1已报名',
  `exam_valid_end_date` date NULL DEFAULT NULL COMMENT '考试报名资格有效截止日期',
  `exam_id` bigint(20) NULL DEFAULT NULL COMMENT '当前报名考试id',
  `exam_type` varchar(10) CHARACTER SET utf8mb4 COLLATE utf8mb4_general_ci NULL DEFAULT NULL COMMENT '当前报名考试类型 1理论 2实操',
  `exam_result` varchar(10) CHARACTER SET utf8mb4 COLLATE utf8mb4_general_ci NULL DEFAULT NULL COMMENT '考试结果 0暂无 1合格 2不合格',
  `exam_count` int(11) NULL DEFAULT NULL COMMENT '考试次数',
  `cancel_signup_times` int(11) NOT NULL DEFAULT 0 COMMENT '取消报名次数',
  `cancel_lock_until` datetime(0) NULL DEFAULT NULL COMMENT '下次允许取消时间',
  `create_by` varchar(64) CHARACTER SET utf8mb4 COLLATE utf8mb4_general_ci NOT NULL DEFAULT '' COMMENT '创建者',
  `create_time` datetime(0) NOT NULL DEFAULT current_timestamp(0) COMMENT '创建时间',
  `update_by` varchar(64) CHARACTER SET utf8mb4 COLLATE utf8mb4_general_ci NOT NULL DEFAULT '' COMMENT '更新者',
  `update_time` datetime(0) NOT NULL DEFAULT current_timestamp(0) ON UPDATE CURRENT_TIMESTAMP(0) COMMENT '更新时间',
  `del_flag` char(1) CHARACTER SET utf8mb4 COLLATE utf8mb4_general_ci NOT NULL DEFAULT '0' COMMENT '删除标志（0=正常，1=删除）',
  `tenant_id` bigint(20) NULL DEFAULT NULL COMMENT '租户ID',
  `id_number` varchar(18) CHARACTER SET utf8mb4 COLLATE utf8mb4_general_ci NULL DEFAULT NULL COMMENT '学员身份证号',
  PRIMARY KEY (`id`) USING BTREE,
  INDEX `idx_exm_signup_theory_exempt`(`theory_exempt_flag`, `del_flag`) USING BTREE
) ENGINE = InnoDB AUTO_INCREMENT = 2099110611000090013 CHARACTER SET = utf8mb4 COLLATE = utf8mb4_general_ci COMMENT = '考试报名汇总表' ROW_FORMAT = Dynamic;

-- ----------------------------
-- Table structure for exm_exam_signup_instance
-- ----------------------------
DROP TABLE IF EXISTS `exm_exam_signup_instance`;
CREATE TABLE `exm_exam_signup_instance`  (
  `id` bigint(20) NOT NULL AUTO_INCREMENT COMMENT 'id',
  `exam_signup_id` bigint(20) NULL DEFAULT NULL COMMENT '考试报名id',
  `ticket` varchar(100) CHARACTER SET utf8mb4 COLLATE utf8mb4_general_ci NULL DEFAULT NULL COMMENT '准考证',
  `signup_time` datetime(0) NULL DEFAULT NULL COMMENT '报名时间',
  `exam_id` bigint(20) NULL DEFAULT NULL COMMENT '当前报名考试id',
  `exam_type` varchar(10) CHARACTER SET utf8mb4 COLLATE utf8mb4_general_ci NULL DEFAULT NULL COMMENT '当前报名考试类型 1理论 2实操',
  `first_score` double NULL DEFAULT NULL COMMENT '初考分数',
  `retake_score` double NULL DEFAULT NULL COMMENT '补考分数',
  `exam_result` varchar(10) CHARACTER SET utf8mb4 COLLATE utf8mb4_general_ci NULL DEFAULT NULL COMMENT '考试结果 0暂无 1合格 2不合格',
  `paid_flag` varchar(10) CHARACTER SET utf8mb4 COLLATE utf8mb4_general_ci NULL DEFAULT NULL COMMENT '报名缴费事实状态：1已缴费 0未缴费',
  `instance_status` varchar(10) CHARACTER SET utf8mb4 COLLATE utf8mb4_general_ci NOT NULL DEFAULT '1' COMMENT '报名实例状态：1有效 2已取消 3已过期',
  `release_reason` varchar(64) CHARACTER SET utf8mb4 COLLATE utf8mb4_general_ci NULL DEFAULT NULL COMMENT '实例释放原因',
  `release_time` datetime(0) NULL DEFAULT NULL COMMENT '实例释放时间',
  `cheat` varchar(10) CHARACTER SET utf8mb4 COLLATE utf8mb4_general_ci NULL DEFAULT NULL COMMENT '是否作弊',
  `cheat_handle` varchar(10) CHARACTER SET utf8mb4 COLLATE utf8mb4_general_ci NULL DEFAULT NULL COMMENT '作弊是否已处理',
  `create_by` varchar(64) CHARACTER SET utf8mb4 COLLATE utf8mb4_general_ci NULL DEFAULT '' COMMENT '创建者',
  `create_time` datetime(0) NOT NULL DEFAULT current_timestamp(0) COMMENT '创建时间',
  `update_by` varchar(64) CHARACTER SET utf8mb4 COLLATE utf8mb4_general_ci NULL DEFAULT '' COMMENT '更新者',
  `update_time` datetime(0) NOT NULL DEFAULT current_timestamp(0) ON UPDATE CURRENT_TIMESTAMP(0) COMMENT '更新时间',
  `del_flag` char(1) CHARACTER SET utf8mb4 COLLATE utf8mb4_general_ci NOT NULL DEFAULT '0' COMMENT '删除标志（0=正常，1=删除）',
  `tenant_id` bigint(20) NULL DEFAULT NULL COMMENT '租户ID',
  `trainee_id` bigint(20) NOT NULL COMMENT '学员ID',
  `sequence` int(11) NULL DEFAULT NULL COMMENT '序号',
  `exam_attempt_type` tinyint(4) NULL DEFAULT NULL COMMENT '考试性质 0初考 1补考',
  `score_source` varchar(20) CHARACTER SET utf8mb4 COLLATE utf8mb4_general_ci NOT NULL DEFAULT 'MANUAL' COMMENT '成绩来源：MANUAL手工录入 TABLET平板录入',
  `score` double NULL DEFAULT NULL COMMENT '考试分数',
  `cycle_no` int(11) NULL DEFAULT NULL COMMENT '考试轮次，同一轮初考和补考使用相同轮次',
  `id_number` varchar(18) CHARACTER SET utf8mb4 COLLATE utf8mb4_general_ci NULL DEFAULT NULL COMMENT '学员身份证号',
  `first_cheat` tinyint(1) NULL DEFAULT 0 COMMENT '初考是否作弊',
  `makeup_cheat` tinyint(1) NULL DEFAULT 0 COMMENT '补考是否作弊',
  `first_cheat_handle` tinyint(1) NULL DEFAULT NULL COMMENT '初考作弊是否已处理',
  `makeup_cheat_handle` tinyint(1) NULL DEFAULT NULL COMMENT '补考作弊是否已处理',
  `result_report_status` tinyint(1) NULL DEFAULT 0 COMMENT '成绩上报状态',
  `download_count` int(11) NOT NULL DEFAULT 0 COMMENT '准考证下载次数',
  `national_push_status` tinyint(1) NOT NULL DEFAULT 0 COMMENT '国家平台推送状态：0未推送 1已推送 2推送失败',
  `national_push_error_msg` varchar(1000) CHARACTER SET utf8mb4 COLLATE utf8mb4_general_ci NULL DEFAULT NULL COMMENT '国家平台推送失败原因',
  `national_plan_examinee_id` varchar(64) CHARACTER SET utf8mb4 COLLATE utf8mb4_general_ci NULL DEFAULT NULL COMMENT '国家平台约考考生标识，对应provincePlanExamineeId',
  `ticket_status` varchar(1) CHARACTER SET utf8mb4 COLLATE utf8mb4_general_ci NULL DEFAULT '0' COMMENT '准考证是否下载 1是 0否',
  PRIMARY KEY (`id`) USING BTREE,
  INDEX `idx_exm_exam_signup_instance_ticket`(`ticket`, `del_flag`) USING BTREE,
  INDEX `idx_exam_signup_instance_exam_status`(`exam_id`, `instance_status`, `del_flag`) USING BTREE,
  INDEX `idx_exam_signup_instance_signup_paid_status`(`exam_signup_id`, `instance_status`, `paid_flag`, `del_flag`) USING BTREE,
  INDEX `idx_esi_national_plan_examinee_id`(`national_plan_examinee_id`) USING BTREE
) ENGINE = InnoDB AUTO_INCREMENT = 2099110611000100013 CHARACTER SET = utf8mb4 COLLATE = utf8mb4_general_ci COMMENT = '考试报名实例' ROW_FORMAT = Dynamic;

-- ----------------------------
-- Table structure for exm_exam_staff_check_in
-- ----------------------------
DROP TABLE IF EXISTS `exm_exam_staff_check_in`;
CREATE TABLE `exm_exam_staff_check_in`  (
  `id` bigint(20) NOT NULL COMMENT '主键ID',
  `exam_id` bigint(20) NULL DEFAULT NULL COMMENT '考试ID',
  `staff_id` bigint(20) NOT NULL COMMENT '考务人员ID',
  `staff_name` varchar(100) CHARACTER SET utf8mb4 COLLATE utf8mb4_general_ci NULL DEFAULT NULL COMMENT '考务人员姓名',
  `staff_type` varchar(10) CHARACTER SET utf8mb4 COLLATE utf8mb4_general_ci NULL DEFAULT NULL COMMENT '考务人员类型',
  `check_in_time` datetime(0) NOT NULL DEFAULT current_timestamp(0) COMMENT '签到时间',
  `check_in_way` varchar(16) CHARACTER SET utf8mb4 COLLATE utf8mb4_general_ci NOT NULL COMMENT '签到方式(FACE:人脸, PHOTO:拍照)',
  `photo_url` varchar(500) CHARACTER SET utf8mb4 COLLATE utf8mb4_general_ci NULL DEFAULT NULL COMMENT '照片地址',
  `create_by` varchar(64) CHARACTER SET utf8mb4 COLLATE utf8mb4_general_ci NOT NULL DEFAULT '' COMMENT '创建者',
  `create_time` datetime(0) NOT NULL DEFAULT current_timestamp(0) COMMENT '创建时间',
  `update_by` varchar(64) CHARACTER SET utf8mb4 COLLATE utf8mb4_general_ci NOT NULL DEFAULT '' COMMENT '更新者',
  `update_time` datetime(0) NOT NULL DEFAULT current_timestamp(0) ON UPDATE CURRENT_TIMESTAMP(0) COMMENT '更新时间',
  `del_flag` char(1) CHARACTER SET utf8mb4 COLLATE utf8mb4_general_ci NOT NULL DEFAULT '0' COMMENT '删除标志(0=正常,1=删除)',
  PRIMARY KEY (`id`) USING BTREE,
  INDEX `idx_exam_staff_check_in_staff_id`(`staff_id`) USING BTREE,
  INDEX `idx_exam_staff_check_in_exam_id`(`exam_id`) USING BTREE,
  INDEX `idx_exam_staff_check_in_time`(`check_in_time`) USING BTREE
) ENGINE = InnoDB CHARACTER SET = utf8mb4 COLLATE = utf8mb4_general_ci COMMENT = '考试工作人员签到记录' ROW_FORMAT = Dynamic;

-- ----------------------------
-- Table structure for exm_exam_staff_rel
-- ----------------------------
DROP TABLE IF EXISTS `exm_exam_staff_rel`;
CREATE TABLE `exm_exam_staff_rel`  (
  `id` bigint(20) NOT NULL AUTO_INCREMENT COMMENT 'id',
  `exam_id` bigint(20) NULL DEFAULT NULL COMMENT '考试id',
  `exam_type` varchar(10) CHARACTER SET utf8mb4 COLLATE utf8mb4_general_ci NULL DEFAULT NULL COMMENT '1理论 2实操',
  `place_id` bigint(20) NULL DEFAULT NULL COMMENT '考试点id',
  `place_room_id` bigint(20) NULL DEFAULT NULL COMMENT '考场id',
  `staff_id` bigint(20) NULL DEFAULT NULL COMMENT '考务人员id',
  `staff_type` varchar(50) CHARACTER SET utf8mb4 COLLATE utf8mb4_general_ci NULL DEFAULT NULL COMMENT '考务人员类型',
  `create_by` varchar(64) CHARACTER SET utf8mb4 COLLATE utf8mb4_general_ci NOT NULL DEFAULT '' COMMENT '创建人',
  `create_time` datetime(0) NOT NULL DEFAULT current_timestamp(0) COMMENT '创建时间',
  `update_by` varchar(64) CHARACTER SET utf8mb4 COLLATE utf8mb4_general_ci NOT NULL DEFAULT '' COMMENT '修改人',
  `update_time` datetime(0) NOT NULL DEFAULT current_timestamp(0) ON UPDATE CURRENT_TIMESTAMP(0) COMMENT '修改时间',
  `del_flag` char(1) CHARACTER SET utf8mb4 COLLATE utf8mb4_general_ci NOT NULL DEFAULT '0' COMMENT '删除标志（0=正常，1=删除）',
  `tenant_id` bigint(20) NULL DEFAULT NULL COMMENT '租户ID',
  `country_arranged` int(11) NULL DEFAULT 0 COMMENT '是否已同步国家平台考评员安排（0=未安排，1=已安排）',
  PRIMARY KEY (`id`) USING BTREE
) ENGINE = InnoDB AUTO_INCREMENT = 2072606061178953732 CHARACTER SET = utf8mb4 COLLATE = utf8mb4_general_ci COMMENT = '考试考务人员关联表' ROW_FORMAT = Dynamic;

-- ----------------------------
-- Table structure for exm_examiner_account
-- ----------------------------
DROP TABLE IF EXISTS `exm_examiner_account`;
CREATE TABLE `exm_examiner_account`  (
  `id` bigint(20) NOT NULL COMMENT '主键ID',
  `staff_id` bigint(20) NOT NULL COMMENT '考务人员ID (关联 exam_staff)',
  `account` varchar(50) CHARACTER SET utf8mb4 COLLATE utf8mb4_general_ci NOT NULL COMMENT '登录账号',
  `password` varchar(100) CHARACTER SET utf8mb4 COLLATE utf8mb4_general_ci NOT NULL COMMENT '密码 (加密存储)',
  `mobile` varchar(20) CHARACTER SET utf8mb4 COLLATE utf8mb4_general_ci NOT NULL COMMENT '绑定手机号',
  `is_two_factor` char(1) CHARACTER SET utf8mb4 COLLATE utf8mb4_general_ci NULL DEFAULT '1' COMMENT '强制短信验证(1-是, 0-否)',
  `status` char(1) CHARACTER SET utf8mb4 COLLATE utf8mb4_general_ci NULL DEFAULT '1' COMMENT '状态(1-启用, 0-禁用)',
  `create_by` varchar(64) CHARACTER SET utf8mb4 COLLATE utf8mb4_general_ci NULL DEFAULT NULL COMMENT '创建者',
  `create_time` datetime(0) NULL DEFAULT NULL COMMENT '创建时间',
  `update_by` varchar(64) CHARACTER SET utf8mb4 COLLATE utf8mb4_general_ci NULL DEFAULT NULL COMMENT '更新者',
  `update_time` datetime(0) NULL DEFAULT NULL COMMENT '更新时间',
  `del_flag` char(1) CHARACTER SET utf8mb4 COLLATE utf8mb4_general_ci NULL DEFAULT '0' COMMENT '删除标志(0-正常, 1-删除)',
  `tenant_id` bigint(20) NULL DEFAULT NULL COMMENT '租户ID',
  PRIMARY KEY (`id`) USING BTREE,
  UNIQUE INDEX `uk_account`(`account`) USING BTREE,
  INDEX `idx_staff_id`(`staff_id`) USING BTREE
) ENGINE = InnoDB CHARACTER SET = utf8mb4 COLLATE = utf8mb4_general_ci COMMENT = '实操考评员账号表' ROW_FORMAT = Dynamic;

