) ENGINE = InnoDB CHARACTER SET = utf8mb4 COLLATE = utf8mb4_general_ci COMMENT = '流程节点记录' ROW_FORMAT = Dynamic;

-- ----------------------------
-- Table structure for process_node_record_assign_user
-- ----------------------------
