) ENGINE = InnoDB CHARACTER SET = utf8mb4 COLLATE = utf8mb4_general_ci COMMENT = '流程节点记录-执行人' ROW_FORMAT = Dynamic;

-- ----------------------------
-- Table structure for process_starter
-- ----------------------------
