-- ----------------------------
-- Table structure for sync_company
-- ----------------------------
DROP TABLE IF EXISTS `sync_company`;
CREATE TABLE `sync_company`  (
  `id` bigint(20) NOT NULL COMMENT '主键',
  `lx_code` varchar(36) CHARACTER SET utf8mb4 COLLATE utf8mb4_general_ci NULL DEFAULT NULL COMMENT '流向系统内企业code',
  `company_code` varchar(16) CHARACTER SET utf8mb4 COLLATE utf8mb4_general_ci NOT NULL COMMENT '企业code',
  `company_name` varchar(64) CHARACTER SET utf8mb4 COLLATE utf8mb4_general_ci NOT NULL COMMENT '企业名称',
  `social_credit_code` varchar(36) CHARACTER SET utf8mb4 COLLATE utf8mb4_general_ci NOT NULL COMMENT '社会统一信用代码',
  `social_credit_file` varchar(128) CHARACTER SET utf8mb4 COLLATE utf8mb4_general_ci NULL DEFAULT NULL COMMENT '营业执照附件key',
  `social_credit_established` date NULL DEFAULT NULL COMMENT '营业执照成立时间',
  `social_credit_deadline` date NULL DEFAULT NULL COMMENT '营业执照经营期限',
  `social_credit_scope` varchar(512) CHARACTER SET utf8mb4 COLLATE utf8mb4_general_ci NULL DEFAULT NULL COMMENT '营业执照经营范围',
  `social_credit_issuing_authority` varchar(128) CHARACTER SET utf8mb4 COLLATE utf8mb4_general_ci NULL DEFAULT NULL COMMENT '营业执照发证机关',
  `business_license` varchar(64) CHARACTER SET utf8mb4 COLLATE utf8mb4_general_ci NULL DEFAULT NULL COMMENT '经营批发许可证编号',
  `business_license_file` varchar(128) CHARACTER SET utf8mb4 COLLATE utf8mb4_general_ci NULL DEFAULT NULL COMMENT '许可证文件key',
  `business_license_start` date NULL DEFAULT NULL COMMENT '许可证开始日期',
  `business_license_end` date NULL DEFAULT NULL COMMENT '许可证截止日期',
  `business_license_scope` varchar(512) CHARACTER SET utf8mb4 COLLATE utf8mb4_general_ci NULL DEFAULT NULL COMMENT '许可证证书范围',
  `business_license_issuing_authority` varchar(128) CHARACTER SET utf8mb4 COLLATE utf8mb4_general_ci NULL DEFAULT NULL COMMENT '许可证发证机关',
  `address` varchar(128) CHARACTER SET utf8mb4 COLLATE utf8mb4_general_ci NULL DEFAULT NULL COMMENT '仓储地址',
  `register_address` varchar(128) CHARACTER SET utf8mb4 COLLATE utf8mb4_general_ci NULL DEFAULT NULL COMMENT '注册地址',
  `company_type` varchar(8) CHARACTER SET utf8mb4 COLLATE utf8mb4_general_ci NULL DEFAULT NULL COMMENT '企业类型',
  `company_status` int(11) NULL DEFAULT NULL COMMENT '企业状态(1.有效；2.无效；3.注销；4.过期；)',
  `access_status` varchar(16) CHARACTER SET utf8mb4 COLLATE utf8mb4_general_ci NULL DEFAULT NULL COMMENT '接入状态（0:未接入/1:已接入）',
  `principal_person` varchar(36) CHARACTER SET utf8mb4 COLLATE utf8mb4_general_ci NULL DEFAULT NULL COMMENT '主要负责人',
  `principal_person_phone` varchar(36) CHARACTER SET utf8mb4 COLLATE utf8mb4_general_ci NULL DEFAULT NULL COMMENT '主要负责人电话',
  `safety_person` varchar(36) CHARACTER SET utf8mb4 COLLATE utf8mb4_general_ci NULL DEFAULT NULL COMMENT '安全负责人',
  `safety_person_phone` varchar(36) CHARACTER SET utf8mb4 COLLATE utf8mb4_general_ci NULL DEFAULT NULL COMMENT '安全负责人电话',
  `dosage` decimal(10, 2) NULL DEFAULT NULL COMMENT '核定药量',
  `reservoir_area` varchar(36) CHARACTER SET utf8mb4 COLLATE utf8mb4_general_ci NULL DEFAULT NULL COMMENT '库区面积',
  `storeroom_area` varchar(36) CHARACTER SET utf8mb4 COLLATE utf8mb4_general_ci NULL DEFAULT NULL COMMENT '库房面积',
  `longitude` decimal(12, 8) NULL DEFAULT NULL COMMENT '经度',
  `latitude` decimal(12, 8) NULL DEFAULT NULL COMMENT '纬度',
  `province_code` varchar(16) CHARACTER SET utf8mb4 COLLATE utf8mb4_general_ci NULL DEFAULT NULL COMMENT '省编码',
  `city_code` varchar(16) CHARACTER SET utf8mb4 COLLATE utf8mb4_general_ci NULL DEFAULT NULL COMMENT '市编码',
  `area_code` varchar(16) CHARACTER SET utf8mb4 COLLATE utf8mb4_general_ci NULL DEFAULT NULL COMMENT '区县编码',
  `province_name` varchar(36) CHARACTER SET utf8mb4 COLLATE utf8mb4_general_ci NULL DEFAULT NULL COMMENT '省名称',
  `city_name` varchar(36) CHARACTER SET utf8mb4 COLLATE utf8mb4_general_ci NULL DEFAULT NULL COMMENT '市名称',
  `area_name` varchar(36) CHARACTER SET utf8mb4 COLLATE utf8mb4_general_ci NULL DEFAULT NULL COMMENT '区县名称',
  `data_source` int(11) NOT NULL DEFAULT 1 COMMENT '数据来源(1:手动录入;2:接口同步)',
  `sync_status` int(11) NOT NULL DEFAULT 0 COMMENT '同步状态(0:未同步;1:已同步;2:同步失败)',
  `sync_message` varchar(512) CHARACTER SET utf8mb4 COLLATE utf8mb4_general_ci NULL DEFAULT NULL COMMENT '同步结果消息',
  `create_by` varchar(64) CHARACTER SET utf8mb4 COLLATE utf8mb4_general_ci NULL DEFAULT NULL COMMENT '创建人',
  `update_by` varchar(64) CHARACTER SET utf8mb4 COLLATE utf8mb4_general_ci NULL DEFAULT NULL COMMENT '更新人',
  `create_time` datetime(0) NOT NULL DEFAULT current_timestamp(0) COMMENT '创建时间',
  `update_time` datetime(0) NOT NULL DEFAULT current_timestamp(0) ON UPDATE CURRENT_TIMESTAMP(0) COMMENT '更新时间',
  `delete_flag` tinyint(4) NOT NULL DEFAULT 0 COMMENT '删除标志（0：未删除/1：已删除）',
  PRIMARY KEY (`id`) USING BTREE,
  UNIQUE INDEX `uk_company_code`(`company_code`) USING BTREE,
  INDEX `idx_sync_status`(`sync_status`) USING BTREE,
  INDEX `idx_data_source`(`data_source`) USING BTREE
) ENGINE = InnoDB CHARACTER SET = utf8mb4 COLLATE = utf8mb4_general_ci COMMENT = '企业信息同步表' ROW_FORMAT = Dynamic;

-- ----------------------------
-- Table structure for sync_device
-- ----------------------------
DROP TABLE IF EXISTS `sync_device`;
CREATE TABLE `sync_device`  (
  `id` bigint(20) NOT NULL COMMENT '主键',
  `device_code` varchar(64) CHARACTER SET utf8mb4 COLLATE utf8mb4_general_ci NOT NULL COMMENT '设备code',
  `device_name` varchar(64) CHARACTER SET utf8mb4 COLLATE utf8mb4_general_ci NOT NULL COMMENT '设备名称',
  `device_type` int(11) NOT NULL COMMENT '设备类型（1:监控/2:门禁/3:温度传感器/4:湿度传感器/5:定位传感器/6:火灾探测器/7:防雷装置/8:静电接地装置/9:视频接入服务器/10:交换机/11:车辆道闸/12:人脸识别终端）',
  `company_code` varchar(16) CHARACTER SET utf8mb4 COLLATE utf8mb4_general_ci NOT NULL COMMENT '关联企业code',
  `store_num` varchar(64) CHARACTER SET utf8mb4 COLLATE utf8mb4_general_ci NOT NULL COMMENT '关联仓库编号',
  `storeroom_num` varchar(64) CHARACTER SET utf8mb4 COLLATE utf8mb4_general_ci NULL DEFAULT NULL COMMENT '关联库房编号',
  `upper` decimal(10, 2) NULL DEFAULT NULL COMMENT '设备值阈值上限',
  `lower` decimal(10, 2) NULL DEFAULT NULL COMMENT '设备值阈值下限',
  `unit` varchar(16) CHARACTER SET utf8mb4 COLLATE utf8mb4_general_ci NULL DEFAULT NULL COMMENT '设备值单位',
  `data_source` int(11) NOT NULL DEFAULT 1 COMMENT '数据来源(1:手动录入;2:接口同步)',
  `sync_status` int(11) NOT NULL DEFAULT 0 COMMENT '同步状态(0:未同步;1:已同步;2:同步失败)',
  `sync_message` varchar(512) CHARACTER SET utf8mb4 COLLATE utf8mb4_general_ci NULL DEFAULT NULL COMMENT '同步结果消息',
  `create_by` varchar(64) CHARACTER SET utf8mb4 COLLATE utf8mb4_general_ci NULL DEFAULT NULL COMMENT '创建人',
  `update_by` varchar(64) CHARACTER SET utf8mb4 COLLATE utf8mb4_general_ci NULL DEFAULT NULL COMMENT '更新人',
  `create_time` datetime(0) NOT NULL DEFAULT current_timestamp(0) COMMENT '创建时间',
  `update_time` datetime(0) NOT NULL DEFAULT current_timestamp(0) ON UPDATE CURRENT_TIMESTAMP(0) COMMENT '更新时间',
  `delete_flag` tinyint(4) NOT NULL DEFAULT 0 COMMENT '删除标志（0：未删除/1：已删除）',
  PRIMARY KEY (`id`) USING BTREE,
  INDEX `idx_company_code`(`company_code`) USING BTREE,
  INDEX `idx_sync_status`(`sync_status`) USING BTREE,
  INDEX `idx_data_source`(`data_source`) USING BTREE
) ENGINE = InnoDB CHARACTER SET = utf8mb4 COLLATE = utf8mb4_general_ci COMMENT = '设备信息同步表' ROW_FORMAT = Dynamic;

-- ----------------------------
-- Table structure for sync_log
-- ----------------------------
DROP TABLE IF EXISTS `sync_log`;
CREATE TABLE `sync_log`  (
  `id` bigint(20) NOT NULL COMMENT '主键',
  `biz_id` varchar(36) CHARACTER SET utf8mb4 COLLATE utf8mb4_general_ci NOT NULL COMMENT '业务ID',
  `biz_type` varchar(20) CHARACTER SET utf8mb4 COLLATE utf8mb4_general_ci NOT NULL COMMENT '业务类型(company,person,storeroom,storeroom_info,device)',
  `sync_status` int(11) NOT NULL COMMENT '同步状态(0:未同步;1:已同步;2:同步失败)',
  `sync_message` varchar(512) CHARACTER SET utf8mb4 COLLATE utf8mb4_general_ci NULL DEFAULT NULL COMMENT '同步结果消息',
  `create_time` datetime(0) NOT NULL DEFAULT current_timestamp(0) COMMENT '创建时间',
  PRIMARY KEY (`id`) USING BTREE,
  INDEX `idx_biz_id`(`biz_id`) USING BTREE,
  INDEX `idx_biz_type`(`biz_type`) USING BTREE
) ENGINE = InnoDB CHARACTER SET = utf8mb4 COLLATE = utf8mb4_general_ci COMMENT = '数据同步日志表' ROW_FORMAT = Dynamic;

-- ----------------------------
-- Table structure for sync_person
-- ----------------------------
DROP TABLE IF EXISTS `sync_person`;
CREATE TABLE `sync_person`  (
  `id` bigint(20) NOT NULL COMMENT '主键',
  `company_code` varchar(16) CHARACTER SET utf8mb4 COLLATE utf8mb4_general_ci NOT NULL COMMENT '关联企业code',
  `person_name` varchar(64) CHARACTER SET utf8mb4 COLLATE utf8mb4_general_ci NOT NULL COMMENT '姓名',
  `idcard` varchar(32) CHARACTER SET utf8mb4 COLLATE utf8mb4_general_ci NOT NULL COMMENT '身份证号',
  `is_certified` int(11) NOT NULL DEFAULT 0 COMMENT '是否有证书（0：无/1：有）',
  `person_type` int(11) NOT NULL COMMENT '人员类型（1：法定代表人/2：主要负责人/3：安全管理人员/4：特种作业人员/5：其他）',
  `mb` varchar(36) CHARACTER SET utf8mb4 COLLATE utf8mb4_general_ci NULL DEFAULT NULL COMMENT '手机号码',
  `certificate_num` varchar(64) CHARACTER SET utf8mb4 COLLATE utf8mb4_general_ci NULL DEFAULT NULL COMMENT '证书编号',
  `certificate_type` int(11) NULL DEFAULT NULL COMMENT '证书类型（1：爆破作业人员/2：保管员/3：采购员/4：销售员/5：押运员）',
  `certificate_start` date NULL DEFAULT NULL COMMENT '证书开始日期',
  `certificate_end` date NULL DEFAULT NULL COMMENT '证书截止日期',
  `data_source` int(11) NOT NULL DEFAULT 1 COMMENT '数据来源(1:手动录入;2:接口同步)',
  `sync_status` int(11) NOT NULL DEFAULT 0 COMMENT '同步状态(0:未同步;1:已同步;2:同步失败)',
  `sync_message` varchar(512) CHARACTER SET utf8mb4 COLLATE utf8mb4_general_ci NULL DEFAULT NULL COMMENT '同步结果消息',
  `create_by` varchar(64) CHARACTER SET utf8mb4 COLLATE utf8mb4_general_ci NULL DEFAULT NULL COMMENT '创建人',
  `update_by` varchar(64) CHARACTER SET utf8mb4 COLLATE utf8mb4_general_ci NULL DEFAULT NULL COMMENT '更新人',
  `create_time` datetime(0) NOT NULL DEFAULT current_timestamp(0) COMMENT '创建时间',
  `update_time` datetime(0) NOT NULL DEFAULT current_timestamp(0) ON UPDATE CURRENT_TIMESTAMP(0) COMMENT '更新时间',
  `delete_flag` tinyint(4) NOT NULL DEFAULT 0 COMMENT '删除标志（0：未删除/1：已删除）',
  PRIMARY KEY (`id`) USING BTREE,
  INDEX `idx_company_code`(`company_code`) USING BTREE,
  INDEX `idx_sync_status`(`sync_status`) USING BTREE,
  INDEX `idx_data_source`(`data_source`) USING BTREE
) ENGINE = InnoDB CHARACTER SET = utf8mb4 COLLATE = utf8mb4_general_ci COMMENT = '人员信息同步表' ROW_FORMAT = Dynamic;

-- ----------------------------
-- Table structure for sync_storeroom
-- ----------------------------
DROP TABLE IF EXISTS `sync_storeroom`;
CREATE TABLE `sync_storeroom`  (
  `id` bigint(20) NOT NULL COMMENT '主键',
  `company_code` varchar(16) CHARACTER SET utf8mb4 COLLATE utf8mb4_general_ci NOT NULL COMMENT '关联企业code',
  `store_name` varchar(64) CHARACTER SET utf8mb4 COLLATE utf8mb4_general_ci NOT NULL COMMENT '仓库名称',
  `store_num` varchar(64) CHARACTER SET utf8mb4 COLLATE utf8mb4_general_ci NOT NULL COMMENT '仓库编号',
  `acreage` decimal(10, 2) NULL DEFAULT NULL COMMENT '面积',
  `danger_level` varchar(16) CHARACTER SET utf8mb4 COLLATE utf8mb4_general_ci NULL DEFAULT NULL COMMENT '危险等级（01:1.1-2级/02:1.3级/03：无药库房）',
  `dosage` decimal(10, 2) NULL DEFAULT NULL COMMENT '核定药量',
  `principal_person` varchar(64) CHARACTER SET utf8mb4 COLLATE utf8mb4_general_ci NULL DEFAULT NULL COMMENT '库区负责人',
  `principal_person_phone` varchar(36) CHARACTER SET utf8mb4 COLLATE utf8mb4_general_ci NULL DEFAULT NULL COMMENT '库区负责人电话',
  `safety_person` varchar(64) CHARACTER SET utf8mb4 COLLATE utf8mb4_general_ci NULL DEFAULT NULL COMMENT '库区安全员',
  `safety_person_phone` varchar(36) CHARACTER SET utf8mb4 COLLATE utf8mb4_general_ci NULL DEFAULT NULL COMMENT '库区安全员电话',
  `longitude` decimal(12, 8) NULL DEFAULT NULL COMMENT '经度',
  `latitude` decimal(12, 8) NULL DEFAULT NULL COMMENT '纬度',
  `data_source` int(11) NOT NULL DEFAULT 1 COMMENT '数据来源(1:手动录入;2:接口同步)',
  `sync_status` int(11) NOT NULL DEFAULT 0 COMMENT '同步状态(0:未同步;1:已同步;2:同步失败)',
  `sync_message` varchar(512) CHARACTER SET utf8mb4 COLLATE utf8mb4_general_ci NULL DEFAULT NULL COMMENT '同步结果消息',
  `create_by` varchar(64) CHARACTER SET utf8mb4 COLLATE utf8mb4_general_ci NULL DEFAULT NULL COMMENT '创建人',
  `update_by` varchar(64) CHARACTER SET utf8mb4 COLLATE utf8mb4_general_ci NULL DEFAULT NULL COMMENT '更新人',
  `create_time` datetime(0) NOT NULL DEFAULT current_timestamp(0) COMMENT '创建时间',
  `update_time` datetime(0) NOT NULL DEFAULT current_timestamp(0) ON UPDATE CURRENT_TIMESTAMP(0) COMMENT '更新时间',
  `delete_flag` tinyint(4) NOT NULL DEFAULT 0 COMMENT '删除标志（0：未删除/1：已删除）',
  PRIMARY KEY (`id`) USING BTREE,
  INDEX `idx_company_code`(`company_code`) USING BTREE,
  INDEX `idx_sync_status`(`sync_status`) USING BTREE,
  INDEX `idx_data_source`(`data_source`) USING BTREE
) ENGINE = InnoDB CHARACTER SET = utf8mb4 COLLATE = utf8mb4_general_ci COMMENT = '库区信息同步表' ROW_FORMAT = Dynamic;

-- ----------------------------
-- Table structure for sync_storeroom_info
-- ----------------------------
DROP TABLE IF EXISTS `sync_storeroom_info`;
CREATE TABLE `sync_storeroom_info`  (
  `id` bigint(20) NOT NULL COMMENT '主键',
  `company_code` varchar(16) CHARACTER SET utf8mb4 COLLATE utf8mb4_general_ci NOT NULL COMMENT '关联企业code',
