  `storeroom_danger_level` varchar(16) CHARACTER SET utf8mb4 COLLATE utf8mb4_general_ci NULL DEFAULT NULL COMMENT '危险等级（01:1.1-2级/02:1.3级/03：无药库房）',
  `storeroom_dosage` decimal(10, 2) NULL DEFAULT NULL COMMENT '核定药量',
