-- ----------------------------
-- Table structure for tr_curriculum
-- ----------------------------
DROP TABLE IF EXISTS `tr_curriculum`;
CREATE TABLE `tr_curriculum`  (
  `id` bigint(20) UNSIGNED NOT NULL AUTO_INCREMENT COMMENT 'ID',
  `class_id` bigint(20) UNSIGNED NOT NULL COMMENT '班级ID',
  `type` tinyint(4) NULL DEFAULT NULL COMMENT '分类 0-理论 1-实践',
  `teacher_id` bigint(20) NOT NULL DEFAULT 0 COMMENT '教师ID',
  `title` varchar(1000) CHARACTER SET utf8mb4 COLLATE utf8mb4_general_ci NOT NULL DEFAULT '' COMMENT '标题',
  `course_date` datetime(0) NULL DEFAULT NULL COMMENT '课程日期',
  `start_time` time(0) NULL DEFAULT '08:00:00' COMMENT '开始时间',
  `end_time` time(0) NULL DEFAULT '17:30:00' COMMENT '结束时间',
  `sort` int(11) NULL DEFAULT 0 COMMENT '排序号',
  `create_time` datetime(0) NULL DEFAULT current_timestamp(0) COMMENT '创建时间',
  `create_by` varchar(20) CHARACTER SET utf8mb4 COLLATE utf8mb4_general_ci NULL DEFAULT '' COMMENT '创建者',
  `update_time` datetime(0) NULL DEFAULT NULL COMMENT '更新时间',
  `update_by` varchar(20) CHARACTER SET utf8mb4 COLLATE utf8mb4_general_ci NULL DEFAULT NULL COMMENT '更新者',
  `del_flag` char(1) CHARACTER SET utf8mb4 COLLATE utf8mb4_general_ci NULL DEFAULT '0' COMMENT '删除标志（0=正常，1=删除）',
  `remark` varchar(500) CHARACTER SET utf8mb4 COLLATE utf8mb4_general_ci NULL DEFAULT '' COMMENT '备注',
  `monitor_id` varchar(64) CHARACTER SET utf8mb4 COLLATE utf8mb4_general_ci NULL DEFAULT NULL COMMENT '监控设备ID',
  `tenant_id` bigint(20) NOT NULL DEFAULT 1 COMMENT '租户',
  `online_training_institution_id` bigint(20) NULL DEFAULT NULL COMMENT '网络培训机构ID',
  PRIMARY KEY (`id`) USING BTREE
) ENGINE = InnoDB AUTO_INCREMENT = 2073949436822237196 CHARACTER SET = utf8mb4 COLLATE = utf8mb4_general_ci COMMENT = '班级课程表信息表' ROW_FORMAT = Dynamic;

-- ----------------------------
-- Table structure for tr_curriculum_course
-- ----------------------------
DROP TABLE IF EXISTS `tr_curriculum_course`;
CREATE TABLE `tr_curriculum_course`  (
  `id` bigint(20) UNSIGNED NOT NULL AUTO_INCREMENT COMMENT 'ID',
  `curriculum_id` bigint(20) NOT NULL COMMENT '课程表ID',
  `course_id` bigint(20) NOT NULL COMMENT '课程ID',
  `create_time` datetime(0) NULL DEFAULT current_timestamp(0) COMMENT '创建时间',
  `create_by` varchar(20) CHARACTER SET utf8mb4 COLLATE utf8mb4_general_ci NOT NULL DEFAULT '' COMMENT '创建者',
  `update_time` datetime(0) NULL DEFAULT NULL COMMENT '更新时间',
  `update_by` varchar(20) CHARACTER SET utf8mb4 COLLATE utf8mb4_general_ci NULL DEFAULT NULL COMMENT '更新者',
  `del_flag` char(1) CHARACTER SET utf8mb4 COLLATE utf8mb4_general_ci NULL DEFAULT '0' COMMENT '删除标志（0=正常，1=删除）',
  `remark` varchar(500) CHARACTER SET utf8mb4 COLLATE utf8mb4_general_ci NULL DEFAULT '' COMMENT '备注',
  `tenant_id` bigint(20) NULL DEFAULT NULL COMMENT '租户ID',
  `class_id` bigint(20) NULL DEFAULT NULL COMMENT '班级ID',
  `institution_id` bigint(20) NULL DEFAULT NULL COMMENT '所属机构ID',
  PRIMARY KEY (`id`) USING BTREE
) ENGINE = InnoDB AUTO_INCREMENT = 2073949436847403024 CHARACTER SET = utf8mb4 COLLATE = utf8mb4_general_ci COMMENT = '课程集合映射表' ROW_FORMAT = Dynamic;

-- ----------------------------
-- Table structure for tr_equipment
-- ----------------------------
DROP TABLE IF EXISTS `tr_equipment`;
CREATE TABLE `tr_equipment`  (
  `id` bigint(20) UNSIGNED NOT NULL AUTO_INCREMENT COMMENT 'ID',
  `name` varchar(200) CHARACTER SET utf8mb4 COLLATE utf8mb4_general_ci NOT NULL COMMENT '设备名称',
  `type_code` tinyint(2) UNSIGNED NOT NULL COMMENT '设备类型',
  `brand` varchar(50) CHARACTER SET utf8mb4 COLLATE utf8mb4_general_ci NULL DEFAULT '' COMMENT '品牌',
  `model` varchar(50) CHARACTER SET utf8mb4 COLLATE utf8mb4_general_ci NULL DEFAULT '' COMMENT '型号',
  `ip_address` varchar(39) CHARACTER SET utf8mb4 COLLATE utf8mb4_general_ci NULL DEFAULT NULL COMMENT 'IP地址',
  `mac_address` varchar(17) CHARACTER SET utf8mb4 COLLATE utf8mb4_general_ci NULL DEFAULT NULL COMMENT 'MAC地址',
  `create_time` datetime(0) NULL DEFAULT current_timestamp(0) COMMENT '创建时间',
  `create_by` varchar(20) CHARACTER SET utf8mb4 COLLATE utf8mb4_general_ci NOT NULL DEFAULT '' COMMENT '创建者',
  `update_time` datetime(0) NULL DEFAULT NULL COMMENT '更新时间',
  `update_by` varchar(20) CHARACTER SET utf8mb4 COLLATE utf8mb4_general_ci NULL DEFAULT NULL COMMENT '更新者',
  `del_flag` char(1) CHARACTER SET utf8mb4 COLLATE utf8mb4_general_ci NULL DEFAULT '0' COMMENT '删除标志（0=正常，1=删除）',
  `remark` varchar(500) CHARACTER SET utf8mb4 COLLATE utf8mb4_general_ci NULL DEFAULT '' COMMENT '备注',
  `tenant_id` bigint(20) NULL DEFAULT NULL COMMENT '租户',
  PRIMARY KEY (`id`) USING BTREE,
  UNIQUE INDEX `uniq_name`(`name`) USING BTREE,
  INDEX `idx_type`(`type_code`) USING BTREE,
  INDEX `idx_ip`(`ip_address`) USING BTREE
) ENGINE = InnoDB AUTO_INCREMENT = 1 CHARACTER SET = utf8mb4 COLLATE = utf8mb4_general_ci COMMENT = '设备信息表' ROW_FORMAT = Dynamic;

-- ----------------------------
-- Table structure for tr_equipment_param
-- ----------------------------
DROP TABLE IF EXISTS `tr_equipment_param`;
CREATE TABLE `tr_equipment_param`  (
  `id` bigint(20) UNSIGNED NOT NULL AUTO_INCREMENT,
  `equipment_id` bigint(20) UNSIGNED NOT NULL,
  `param_key` varchar(50) CHARACTER SET utf8mb4 COLLATE utf8mb4_general_ci NOT NULL COMMENT '参数键',
  `param_value` varchar(200) CHARACTER SET utf8mb4 COLLATE utf8mb4_general_ci NOT NULL COMMENT '参数值',
  PRIMARY KEY (`id`) USING BTREE,
  INDEX `idx_equipment`(`equipment_id`) USING BTREE
) ENGINE = InnoDB AUTO_INCREMENT = 1 CHARACTER SET = utf8mb4 COLLATE = utf8mb4_general_ci COMMENT = '设备参数表' ROW_FORMAT = Dynamic;

-- ----------------------------
-- Table structure for tr_equipment_status
-- ----------------------------
DROP TABLE IF EXISTS `tr_equipment_status`;
CREATE TABLE `tr_equipment_status`  (
  `equipment_id` bigint(20) UNSIGNED NOT NULL,
  `is_online` tinyint(1) NULL DEFAULT 0 COMMENT '在线状态',
  `last_heartbeat` datetime(0) NULL DEFAULT NULL COMMENT '最后心跳',
  `version` varchar(20) CHARACTER SET utf8mb4 COLLATE utf8mb4_general_ci NULL DEFAULT '' COMMENT '固件版本',
  PRIMARY KEY (`equipment_id`) USING BTREE
) ENGINE = InnoDB CHARACTER SET = utf8mb4 COLLATE = utf8mb4_general_ci COMMENT = '设备状态表' ROW_FORMAT = Dynamic;

-- ----------------------------
-- Table structure for tr_excel_import_record
-- ----------------------------
DROP TABLE IF EXISTS `tr_excel_import_record`;
CREATE TABLE `tr_excel_import_record`  (
  `id` bigint(20) NOT NULL COMMENT '主键ID',
  `batch_no` varchar(64) CHARACTER SET utf8mb4 COLLATE utf8mb4_general_ci NOT NULL COMMENT '导入批次号',
  `source_file_name` varchar(255) CHARACTER SET utf8mb4 COLLATE utf8mb4_general_ci NULL DEFAULT NULL COMMENT '源文件名',
  `file_hash` varchar(64) CHARACTER SET utf8mb4 COLLATE utf8mb4_general_ci NULL DEFAULT NULL COMMENT '文件内容SHA-256哈希，用于去重',
  `total_count` int(11) NULL DEFAULT 0 COMMENT '总行数',
  `success_count` int(11) NULL DEFAULT 0 COMMENT '成功行数',
  `failed_count` int(11) NULL DEFAULT 0 COMMENT '失败行数',
  `skipped_count` int(11) NULL DEFAULT 0 COMMENT '跳过行数',
  `parse_status` varchar(32) CHARACTER SET utf8mb4 COLLATE utf8mb4_general_ci NOT NULL DEFAULT 'PENDING' COMMENT '解析状态：PENDING/PROCESSING/COMPLETED/FAILED',
  `tenant_id` bigint(20) NULL DEFAULT NULL COMMENT '租户ID',
  `create_time` datetime(0) NULL DEFAULT current_timestamp(0) COMMENT '创建时间',
  `update_time` datetime(0) NULL DEFAULT current_timestamp(0) ON UPDATE CURRENT_TIMESTAMP(0) COMMENT '更新时间',
  `del_flag` char(1) CHARACTER SET utf8mb4 COLLATE utf8mb4_general_ci NOT NULL DEFAULT '0' COMMENT '删除标记，0未删除，1已删除',
  PRIMARY KEY (`id`) USING BTREE,
  UNIQUE INDEX `uk_excel_import_file_hash`(`file_hash`) USING BTREE,
  INDEX `idx_excel_import_batch`(`batch_no`) USING BTREE
) ENGINE = InnoDB CHARACTER SET = utf8mb4 COLLATE = utf8mb4_general_ci COMMENT = 'Excel 导入记录表（文件级）' ROW_FORMAT = Dynamic;

-- ----------------------------
-- Table structure for tr_hikvision_access_event
-- ----------------------------
DROP TABLE IF EXISTS `tr_hikvision_access_event`;
CREATE TABLE `tr_hikvision_access_event`  (
  `id` bigint(20) NOT NULL COMMENT '主键ID',
  `mac_address` varchar(64) CHARACTER SET utf8mb4 COLLATE utf8mb4_general_ci NULL DEFAULT NULL COMMENT '设备MAC地址',
  `event_type` varchar(64) CHARACTER SET utf8mb4 COLLATE utf8mb4_general_ci NOT NULL COMMENT '事件类型，如AccessControllerEvent',
  `serial_no` bigint(20) NULL DEFAULT NULL COMMENT 'AccessControllerEvent.serialNo',
  `event_payload` longtext CHARACTER SET utf8mb4 COLLATE utf8mb4_general_ci NOT NULL COMMENT '门禁事件完整JSON数据结构',
  `picture_url` varchar(512) CHARACTER SET utf8mb4 COLLATE utf8mb4_general_ci NULL DEFAULT NULL COMMENT 'Picture上传OSS后的访问地址',
  `receive_time` datetime(0) NOT NULL COMMENT '平台接收时间',
  `create_time` datetime(0) NULL DEFAULT current_timestamp(0) COMMENT '创建时间',
  `update_time` datetime(0) NULL DEFAULT current_timestamp(0) ON UPDATE CURRENT_TIMESTAMP(0) COMMENT '更新时间',
  PRIMARY KEY (`id`) USING BTREE,
  INDEX `idx_hikvision_access_mac`(`mac_address`) USING BTREE,
  INDEX `idx_hikvision_access_serial`(`serial_no`) USING BTREE,
  INDEX `idx_hikvision_access_event_type`(`event_type`) USING BTREE,
  INDEX `idx_hikvision_access_receive_time`(`receive_time`) USING BTREE
) ENGINE = InnoDB CHARACTER SET = utf8mb4 COLLATE = utf8mb4_general_ci COMMENT = '海康门禁事件表' ROW_FORMAT = Dynamic;

-- ----------------------------
-- Table structure for tr_hikvision_attendance_event
-- ----------------------------
DROP TABLE IF EXISTS `tr_hikvision_attendance_event`;
CREATE TABLE `tr_hikvision_attendance_event`  (
  `id` bigint(20) NOT NULL COMMENT '主键ID',
  `event_id` varchar(64) CHARACTER SET utf8mb4 COLLATE utf8mb4_general_ci NOT NULL COMMENT '全局稳定事件键；基于设备与事件时间/人员/类型等规范字段生成的设备作用域SHA-256键，用于PUSH/PULL去重',
  `device_id` bigint(20) NULL DEFAULT NULL COMMENT '海康设备ID',
  `device_sn` varchar(128) CHARACTER SET utf8mb4 COLLATE utf8mb4_general_ci NULL DEFAULT NULL COMMENT '设备序列号',
  `employee_no` varchar(64) CHARACTER SET utf8mb4 COLLATE utf8mb4_general_ci NULL DEFAULT NULL COMMENT '海康人员编号',
  `person_name` varchar(64) CHARACTER SET utf8mb4 COLLATE utf8mb4_general_ci NULL DEFAULT NULL COMMENT '人员姓名',
  `event_time` datetime(0) NULL DEFAULT NULL COMMENT '事件时间',
  `major` varchar(64) CHARACTER SET utf8mb4 COLLATE utf8mb4_general_ci NULL DEFAULT NULL COMMENT '主类型',
  `minor` varchar(64) CHARACTER SET utf8mb4 COLLATE utf8mb4_general_ci NULL DEFAULT NULL COMMENT '次类型',
  `event_type` varchar(128) CHARACTER SET utf8mb4 COLLATE utf8mb4_general_ci NULL DEFAULT NULL COMMENT '事件类型',
  `verify_type` varchar(64) CHARACTER SET utf8mb4 COLLATE utf8mb4_general_ci NULL DEFAULT NULL COMMENT '认证方式',
  `attendance_status` varchar(64) CHARACTER SET utf8mb4 COLLATE utf8mb4_general_ci NULL DEFAULT NULL COMMENT '认证/通行结果',
  `picture_url` varchar(512) CHARACTER SET utf8mb4 COLLATE utf8mb4_general_ci NULL DEFAULT NULL COMMENT '现场图片地址',
  `source_channel` varchar(16) CHARACTER SET utf8mb4 COLLATE utf8mb4_general_ci NOT NULL COMMENT 'PUSH/PULL',
  `raw_payload` longtext CHARACTER SET utf8mb4 COLLATE utf8mb4_general_ci NULL COMMENT '原始报文',
  `sync_time` datetime(0) NULL DEFAULT NULL COMMENT '同步时间',
  `last_seen_time` datetime(0) NULL DEFAULT NULL COMMENT '最后一次收到时间',
  `tenant_id` bigint(20) NOT NULL COMMENT '租户ID',
  `create_time` datetime(0) NULL DEFAULT current_timestamp(0) COMMENT '创建时间',
  `update_time` datetime(0) NULL DEFAULT current_timestamp(0) ON UPDATE CURRENT_TIMESTAMP(0) COMMENT '更新时间',
  `del_flag` char(1) CHARACTER SET utf8mb4 COLLATE utf8mb4_general_ci NOT NULL DEFAULT '0' COMMENT '删除标记',
  PRIMARY KEY (`id`) USING BTREE,
  UNIQUE INDEX `uk_hikvision_event`(`tenant_id`, `event_id`) USING BTREE,
  INDEX `idx_hikvision_event_time`(`event_time`) USING BTREE,
  INDEX `idx_hikvision_employee_time`(`employee_no`, `event_time`) USING BTREE,
  INDEX `idx_hikvision_device_time`(`device_sn`, `event_time`) USING BTREE,
  INDEX `idx_hikvision_event_tenant`(`tenant_id`) USING BTREE
) ENGINE = InnoDB CHARACTER SET = utf8mb4 COLLATE = utf8mb4_general_ci COMMENT = '海康考勤原始事件表' ROW_FORMAT = Dynamic;

-- ----------------------------
-- Table structure for tr_hikvision_device
-- ----------------------------
DROP TABLE IF EXISTS `tr_hikvision_device`;
CREATE TABLE `tr_hikvision_device`  (
  `id` bigint(20) NOT NULL COMMENT '主键ID',
  `device_code` varchar(64) CHARACTER SET utf8mb4 COLLATE utf8mb4_general_ci NOT NULL COMMENT '系统内设备编码',
  `device_name` varchar(128) CHARACTER SET utf8mb4 COLLATE utf8mb4_general_ci NOT NULL COMMENT '设备名称',
  `device_base_url` varchar(255) CHARACTER SET utf8mb4 COLLATE utf8mb4_general_ci NOT NULL COMMENT '设备ISAPI基础地址，如http://192.168.1.10:80',
  `username` varchar(64) CHARACTER SET utf8mb4 COLLATE utf8mb4_general_ci NOT NULL COMMENT '设备用户名',
  `password_cipher` varchar(512) CHARACTER SET utf8mb4 COLLATE utf8mb4_general_ci NOT NULL COMMENT '设备密码密文',
  `device_sn` varchar(128) CHARACTER SET utf8mb4 COLLATE utf8mb4_general_ci NULL DEFAULT NULL COMMENT '设备序列号',
  `device_model` varchar(128) CHARACTER SET utf8mb4 COLLATE utf8mb4_general_ci NULL DEFAULT NULL COMMENT '设备型号',
  `status` varchar(32) CHARACTER SET utf8mb4 COLLATE utf8mb4_general_ci NOT NULL DEFAULT 'OFFLINE' COMMENT 'ONLINE/OFFLINE/DISABLED',
  `callback_url` varchar(512) CHARACTER SET utf8mb4 COLLATE utf8mb4_general_ci NULL DEFAULT NULL COMMENT 'SPX回调地址，不含token',
  `callback_token` varchar(128) CHARACTER SET utf8mb4 COLLATE utf8mb4_general_ci NULL DEFAULT NULL COMMENT 'SPX回调令牌',
  `last_heartbeat_time` datetime(0) NULL DEFAULT NULL COMMENT '最后心跳时间',
  `last_sync_time` datetime(0) NULL DEFAULT NULL COMMENT '最后同步时间',
  `tenant_id` bigint(20) NOT NULL COMMENT '租户ID',
  `create_time` datetime(0) NULL DEFAULT current_timestamp(0) COMMENT '创建时间',
  `update_time` datetime(0) NULL DEFAULT current_timestamp(0) ON UPDATE CURRENT_TIMESTAMP(0) COMMENT '更新时间',
  `del_flag` char(1) CHARACTER SET utf8mb4 COLLATE utf8mb4_general_ci NOT NULL DEFAULT '0' COMMENT '删除标记',
  PRIMARY KEY (`id`) USING BTREE,
  UNIQUE INDEX `uk_hikvision_device_code`(`tenant_id`, `device_code`) USING BTREE,
  INDEX `idx_hikvision_device_tenant_status`(`tenant_id`, `status`) USING BTREE,
  INDEX `idx_hikvision_device_sn`(`device_sn`) USING BTREE
) ENGINE = InnoDB CHARACTER SET = utf8mb4 COLLATE = utf8mb4_general_ci COMMENT = '海康设备表' ROW_FORMAT = Dynamic;

-- ----------------------------
-- Table structure for tr_hikvision_person_sync
-- ----------------------------
DROP TABLE IF EXISTS `tr_hikvision_person_sync`;
CREATE TABLE `tr_hikvision_person_sync`  (
  `id` bigint(20) NOT NULL COMMENT '主键ID',
  `device_id` bigint(20) NOT NULL COMMENT '海康设备ID',
  `person_type` varchar(32) CHARACTER SET utf8mb4 COLLATE utf8mb4_general_ci NOT NULL DEFAULT 'TRAINEE' COMMENT '人员类型',
  `person_id` bigint(20) NOT NULL COMMENT 'SPX人员ID',
  `signup_id` bigint(20) NOT NULL COMMENT '报名/入班记录ID',
  `employee_no` varchar(64) CHARACTER SET utf8mb4 COLLATE utf8mb4_general_ci NOT NULL COMMENT '海康人员编号',
  `person_name` varchar(64) CHARACTER SET utf8mb4 COLLATE utf8mb4_general_ci NULL DEFAULT NULL COMMENT '人员姓名',
  `face_photo_url` varchar(512) CHARACTER SET utf8mb4 COLLATE utf8mb4_general_ci NULL DEFAULT NULL COMMENT '人脸照片地址',
  `user_sync_status` varchar(32) CHARACTER SET utf8mb4 COLLATE utf8mb4_general_ci NOT NULL DEFAULT 'PENDING' COMMENT '人员同步状态',
  `face_sync_status` varchar(32) CHARACTER SET utf8mb4 COLLATE utf8mb4_general_ci NOT NULL DEFAULT 'PENDING' COMMENT '人脸同步状态',
  `last_sync_time` datetime(0) NULL DEFAULT NULL COMMENT '最后同步时间',
  `last_error_message` varchar(1024) CHARACTER SET utf8mb4 COLLATE utf8mb4_general_ci NULL DEFAULT NULL COMMENT '最后错误信息',
  `retry_count` int(11) NOT NULL DEFAULT 0 COMMENT '重试次数',
  `tenant_id` bigint(20) NOT NULL COMMENT '租户ID',
  `create_time` datetime(0) NULL DEFAULT current_timestamp(0) COMMENT '创建时间',
  `update_time` datetime(0) NULL DEFAULT current_timestamp(0) ON UPDATE CURRENT_TIMESTAMP(0) COMMENT '更新时间',
  `del_flag` char(1) CHARACTER SET utf8mb4 COLLATE utf8mb4_general_ci NOT NULL DEFAULT '0' COMMENT '删除标记',
  PRIMARY KEY (`id`) USING BTREE,
  UNIQUE INDEX `uk_hikvision_person_device_signup`(`tenant_id`, `device_id`, `signup_id`) USING BTREE,
  INDEX `idx_hikvision_person_employee`(`employee_no`) USING BTREE,
  INDEX `idx_hikvision_person_status`(`user_sync_status`, `face_sync_status`) USING BTREE,
  INDEX `idx_hikvision_person_tenant`(`tenant_id`) USING BTREE
) ENGINE = InnoDB CHARACTER SET = utf8mb4 COLLATE = utf8mb4_general_ci COMMENT = '海康人员下发记录表' ROW_FORMAT = Dynamic;

-- ----------------------------
-- Table structure for tr_hours_certificate
-- ----------------------------
DROP TABLE IF EXISTS `tr_hours_certificate`;
CREATE TABLE `tr_hours_certificate`  (
  `id` bigint(20) UNSIGNED NOT NULL AUTO_INCREMENT COMMENT '主键ID',
  `signup_id` bigint(20) NOT NULL COMMENT '学员报名ID（关联tr_trainee_signup.id）',
  `class_id` bigint(20) NOT NULL COMMENT '培训班级ID（关联tr_class.id）',
  `learning_hours` decimal(10, 2) NULL COMMENT '已修学时（单位：小时，保留2位小数）',
  `offline_learning_hours` decimal(10, 2) NULL COMMENT '线下学时（单位：小时，保留2位小数）',
  `online_learning_hours` decimal(10, 2) NULL COMMENT '线上学时（单位：小时，保留2位小数）',
  `hour_qualify_status` tinyint(4) NULL DEFAULT NULL COMMENT '课时合格状态（0-不合格，1-合格）',
  `is_generate_cert` tinyint(4) NULL DEFAULT NULL COMMENT '是否生成课时证明（0-否，1-是）',
  `sequence` varchar(10) CHARACTER SET utf8mb4 COLLATE utf8mb4_general_ci NULL DEFAULT NULL COMMENT '年份+6位递增序号，如2023000001',
  `cert_no` varchar(64) CHARACTER SET utf8mb4 COLLATE utf8mb4_general_ci NULL DEFAULT NULL COMMENT '证书编号',
  `cert_create_time` datetime(0) NULL DEFAULT NULL COMMENT '学时证明创建时间',
  `cert_path_url` varchar(1000) CHARACTER SET utf8mb4 COLLATE utf8mb4_general_ci NULL DEFAULT '' COMMENT '学时证明图片',
  `cert_file_url` varchar(500) CHARACTER SET utf8mb4 COLLATE utf8mb4_general_ci NULL DEFAULT NULL COMMENT '学时证明文件服务URL',
  `source` varchar(16) CHARACTER SET utf8mb4 COLLATE utf8mb4_general_ci NOT NULL DEFAULT 'sync' COMMENT '学时证明来源：sync=同步，manual=手动导入',
  `create_time` datetime(0) NOT NULL DEFAULT current_timestamp(0) COMMENT '创建时间',
  `update_time` datetime(0) NOT NULL DEFAULT current_timestamp(0) ON UPDATE CURRENT_TIMESTAMP(0) COMMENT '更新时间',
  `del_flag` char(1) CHARACTER SET utf8mb4 COLLATE utf8mb4_general_ci NOT NULL DEFAULT '0' COMMENT '删除标志（0-正常，1-删除）',
  `tenant_id` bigint(20) NOT NULL COMMENT '租户ID（多租户数据隔离）',
  `archive_flag` tinyint(4) NULL DEFAULT NULL COMMENT '归档标识：0=未归档，1=已归档',
  PRIMARY KEY (`id`) USING BTREE,
  INDEX `idx_tenant_id`(`tenant_id`) USING BTREE,
  INDEX `idx_class_id`(`class_id`) USING BTREE,
  INDEX `idx_is_generate_cert`(`is_generate_cert`) USING BTREE,
  INDEX `uk_signup_class`(`signup_id`, `class_id`) USING BTREE,
  INDEX `idx_hours_cert_sequence`(`sequence`) USING BTREE
) ENGINE = InnoDB AUTO_INCREMENT = 332393909088948225 CHARACTER SET = utf8mb4 COLLATE = utf8mb4_general_ci COMMENT = '学员-班级学时证明表' ROW_FORMAT = Dynamic;

-- ----------------------------
-- Table structure for tr_id_card
-- ----------------------------
DROP TABLE IF EXISTS `tr_id_card`;
CREATE TABLE `tr_id_card`  (
  `id` bigint(20) NOT NULL AUTO_INCREMENT COMMENT 'ID',
  `portrait` varchar(255) CHARACTER SET utf8mb4 COLLATE utf8mb4_general_ci NULL DEFAULT NULL COMMENT '人像',
  `name` varchar(20) CHARACTER SET utf8mb4 COLLATE utf8mb4_general_ci NULL DEFAULT NULL COMMENT '名称',
  `nationality` varchar(7) CHARACTER SET utf8mb4 COLLATE utf8mb4_general_ci NULL DEFAULT NULL COMMENT '民族',
  `birth_date` date NULL DEFAULT NULL COMMENT '出生日期',
  `address` varchar(255) CHARACTER SET utf8mb4 COLLATE utf8mb4_general_ci NULL DEFAULT NULL COMMENT '住址',
  `area_id` bigint(20) NULL DEFAULT NULL COMMENT '行政区域ID',
  `area_ids` varchar(200) CHARACTER SET utf8mb4 COLLATE utf8mb4_general_ci NULL DEFAULT NULL COMMENT '行政区域路径',
  `area_name` varchar(100) CHARACTER SET utf8mb4 COLLATE utf8mb4_general_ci NULL DEFAULT NULL COMMENT '行政区域名称',
  `area_names` varchar(200) CHARACTER SET utf8mb4 COLLATE utf8mb4_general_ci NULL DEFAULT NULL COMMENT '行政区域全称',
  `id_number` char(18) CHARACTER SET utf8mb4 COLLATE utf8mb4_general_ci NOT NULL COMMENT '公民身份证号',
  `issuer` varchar(20) CHARACTER SET utf8mb4 COLLATE utf8mb4_general_ci NULL DEFAULT NULL COMMENT '签发机关',
  `effective_date` date NULL DEFAULT NULL COMMENT '生效日期',
  `expire_date` date NULL DEFAULT NULL COMMENT '失效日期',
  `practitioner_id` bigint(20) NOT NULL COMMENT '从业人员ID',
  `front_file_path` varchar(255) CHARACTER SET utf8mb4 COLLATE utf8mb4_general_ci NULL DEFAULT NULL COMMENT '正面文件路径',
  `back_filepath` varchar(255) CHARACTER SET utf8mb4 COLLATE utf8mb4_general_ci NULL DEFAULT NULL COMMENT '反面文件路径',
  `create_time` datetime(0) NULL DEFAULT current_timestamp(0) COMMENT '创建时间',
  `create_by` varchar(20) CHARACTER SET utf8mb4 COLLATE utf8mb4_general_ci NOT NULL DEFAULT '' COMMENT '创建者',
  `update_time` datetime(0) NULL DEFAULT NULL COMMENT '更新时间',
  `update_by` varchar(20) CHARACTER SET utf8mb4 COLLATE utf8mb4_general_ci NULL DEFAULT NULL COMMENT '更新者',
  `del_flag` char(1) CHARACTER SET utf8mb4 COLLATE utf8mb4_general_ci NULL DEFAULT '0' COMMENT '删除标志（0=正常，1=删除）',
  `remark` varchar(500) CHARACTER SET utf8mb4 COLLATE utf8mb4_general_ci NULL DEFAULT '' COMMENT '备注',
  `tenant_id` bigint(20) NOT NULL DEFAULT 1 COMMENT '租户',
  `gender` tinyint(4) NULL DEFAULT NULL COMMENT '性别，1男，2女，0未知',
  `class_id` bigint(20) NULL DEFAULT NULL COMMENT '班级ID',
  `institution_id` bigint(20) NULL DEFAULT NULL COMMENT '所属机构ID',
  PRIMARY KEY (`id`) USING BTREE
) ENGINE = InnoDB AUTO_INCREMENT = 2099110611000040013 CHARACTER SET = utf8mb4 COLLATE = utf8mb4_general_ci COMMENT = '身份证表' ROW_FORMAT = Dynamic;

-- ----------------------------
-- Table structure for tr_institution
-- ----------------------------
DROP TABLE IF EXISTS `tr_institution`;
CREATE TABLE `tr_institution`  (
  `id` bigint(20) UNSIGNED NOT NULL AUTO_INCREMENT COMMENT 'ID',
  `logical_user_id` bigint(20) NULL DEFAULT NULL COMMENT '逻辑用户ID',
  `area_id` varchar(50) CHARACTER SET utf8mb4 COLLATE utf8mb4_general_ci NULL DEFAULT NULL COMMENT '行政区域ID',
  `area_ids` varchar(100) CHARACTER SET utf8mb4 COLLATE utf8mb4_general_ci NULL DEFAULT NULL COMMENT '行政区域路径',
  `area_name` varchar(100) CHARACTER SET utf8mb4 COLLATE utf8mb4_general_ci NULL DEFAULT NULL COMMENT '行政区域名称',
  `area_names` varchar(100) CHARACTER SET utf8mb4 COLLATE utf8mb4_general_ci NULL DEFAULT NULL COMMENT '行政区域全称',
  `address` varchar(500) CHARACTER SET utf8mb4 COLLATE utf8mb4_general_ci NULL DEFAULT NULL COMMENT '地址',
  `institution_name` varchar(100) CHARACTER SET utf8mb4 COLLATE utf8mb4_general_ci NOT NULL COMMENT '机构名称',
  `code` varchar(20) CHARACTER SET utf8mb4 COLLATE utf8mb4_general_ci NOT NULL COMMENT '机构编码',
  `introduction` varchar(500) CHARACTER SET utf8mb4 COLLATE utf8mb4_general_ci NULL DEFAULT NULL COMMENT '机构简介',
  `institution_level` tinyint(1) NULL DEFAULT NULL COMMENT '机构资质级别',
  `create_time` datetime(0) NULL DEFAULT current_timestamp(0) COMMENT '创建时间',
  `create_by` varchar(20) CHARACTER SET utf8mb4 COLLATE utf8mb4_general_ci NULL DEFAULT '' COMMENT '创建者',
  `update_time` datetime(0) NULL DEFAULT NULL COMMENT '更新时间',
  `update_by` varchar(20) CHARACTER SET utf8mb4 COLLATE utf8mb4_general_ci NULL DEFAULT NULL COMMENT '更新者',
  `del_flag` char(1) CHARACTER SET utf8mb4 COLLATE utf8mb4_general_ci NULL DEFAULT '0' COMMENT '删除标志（0=正常，1=删除）',
  `remark` varchar(500) CHARACTER SET utf8mb4 COLLATE utf8mb4_general_ci NULL DEFAULT '' COMMENT '备注',
  `tenant_id` bigint(20) NOT NULL DEFAULT 1 COMMENT '租户',
  `seal_path` varchar(255) CHARACTER SET utf8mb4 COLLATE utf8mb4_general_ci NULL DEFAULT NULL COMMENT '印章路径',
  `institution_signature_path` varchar(500) CHARACTER SET utf8mb4 COLLATE utf8mb4_general_ci NULL DEFAULT NULL COMMENT '机构负责人签名路径',
  `seal_update_time` datetime(0) NULL DEFAULT NULL COMMENT '印章更新时间',
  `institution_tenant_id` bigint(20) NULL DEFAULT NULL COMMENT '机构租户ID',
  `establishment_time` date NULL DEFAULT NULL COMMENT '成立时间',
  `site_photo_paths` varchar(2000) CHARACTER SET utf8mb4 COLLATE utf8mb4_general_ci NULL DEFAULT NULL COMMENT '现场照片路径，使用|分割',
  `qualification_paths` varchar(2000) CHARACTER SET utf8mb4 COLLATE utf8mb4_general_ci NULL DEFAULT NULL COMMENT '资质证明路径',
  `score` decimal(3, 1) NULL DEFAULT NULL COMMENT '机构评分',
  `parent_id` bigint(20) NULL DEFAULT NULL COMMENT '父单位id',
  `parent_name` varchar(255) CHARACTER SET utf8mb4 COLLATE utf8mb4_general_ci NULL DEFAULT NULL COMMENT '上级单位',
  `org_class` varchar(64) CHARACTER SET utf8mb4 COLLATE utf8mb4_general_ci NULL DEFAULT NULL COMMENT '单位类别',
  `org_name` varchar(255) CHARACTER SET utf8mb4 COLLATE utf8mb4_general_ci NULL DEFAULT NULL COMMENT '单位名称',
  `used_name1` varchar(255) CHARACTER SET utf8mb4 COLLATE utf8mb4_general_ci NULL DEFAULT NULL COMMENT '曾用名1',
  `used_name2` varchar(255) CHARACTER SET utf8mb4 COLLATE utf8mb4_general_ci NULL DEFAULT NULL COMMENT '曾用名2',
  `order_num` bigint(20) NULL DEFAULT NULL COMMENT '排序号',
  `linkman` varchar(64) CHARACTER SET utf8mb4 COLLATE utf8mb4_general_ci NULL DEFAULT NULL COMMENT '联系人',
  `phone` varchar(32) CHARACTER SET utf8mb4 COLLATE utf8mb4_general_ci NULL DEFAULT NULL COMMENT '联系电话',
  `office_phone` varchar(32) CHARACTER SET utf8mb4 COLLATE utf8mb4_general_ci NULL DEFAULT NULL COMMENT '办公电话',
  `hotline` varchar(32) CHARACTER SET utf8mb4 COLLATE utf8mb4_general_ci NULL DEFAULT NULL COMMENT '业务咨询电话',
  `postal_code` varchar(32) CHARACTER SET utf8mb4 COLLATE utf8mb4_general_ci NULL DEFAULT NULL COMMENT '邮政编码',
  `mailing_address` varchar(255) CHARACTER SET utf8mb4 COLLATE utf8mb4_general_ci NULL DEFAULT NULL COMMENT '通讯地址',
  `longitude` varchar(64) CHARACTER SET utf8mb4 COLLATE utf8mb4_general_ci NULL DEFAULT NULL COMMENT '经维度',
  `service_level` varchar(64) CHARACTER SET utf8mb4 COLLATE utf8mb4_general_ci NULL DEFAULT NULL COMMENT '业务层级',
  `service_type` varchar(64) CHARACTER SET utf8mb4 COLLATE utf8mb4_general_ci NULL DEFAULT NULL COMMENT '业务性质',
  `dept_type` varchar(64) CHARACTER SET utf8mb4 COLLATE utf8mb4_general_ci NULL DEFAULT NULL COMMENT '机构性质',
  `authority_code` varchar(64) CHARACTER SET utf8mb4 COLLATE utf8mb4_general_ci NULL DEFAULT NULL COMMENT '签发机关编码',
  `status` varchar(32) CHARACTER SET utf8mb4 COLLATE utf8mb4_general_ci NULL DEFAULT NULL COMMENT '部门状态（0正常 1停用）',
  `credit_code` varchar(64) CHARACTER SET utf8mb4 COLLATE utf8mb4_general_ci NULL DEFAULT NULL COMMENT '统一信用代码',
  `examination_type` varchar(64) CHARACTER SET utf8mb4 COLLATE utf8mb4_general_ci NULL DEFAULT NULL COMMENT '考试点类型',
  `unit_introduction` text CHARACTER SET utf8mb4 COLLATE utf8mb4_general_ci NULL COMMENT '单位简介',
  `fulltime_teacher_num` bigint(20) NULL DEFAULT NULL COMMENT '专职教师数量',
  `parttime_teacher_num` bigint(20) NULL DEFAULT NULL COMMENT '兼职教书数量',
  `org_status` varchar(32) CHARACTER SET utf8mb4 COLLATE utf8mb4_general_ci NULL DEFAULT NULL COMMENT '机构状态',
  `service_scope` text CHARACTER SET utf8mb4 COLLATE utf8mb4_general_ci NULL COMMENT '业务范围',
  `play_service_scope` text CHARACTER SET utf8mb4 COLLATE utf8mb4_general_ci NULL COMMENT '实操业务范围',
  `theory_service_scope` text CHARACTER SET utf8mb4 COLLATE utf8mb4_general_ci NULL COMMENT '理论业务范围',
  `exam_record` varchar(255) CHARACTER SET utf8mb4 COLLATE utf8mb4_general_ci NULL DEFAULT NULL COMMENT '备案单位',
  `exam_plan` varchar(255) CHARACTER SET utf8mb4 COLLATE utf8mb4_general_ci NULL DEFAULT NULL COMMENT '计划单位',
  `service_scope_id` varchar(64) CHARACTER SET utf8mb4 COLLATE utf8mb4_general_ci NULL DEFAULT NULL COMMENT '业务范围id',
  `play_service_scope_id` varchar(64) CHARACTER SET utf8mb4 COLLATE utf8mb4_general_ci NULL DEFAULT NULL COMMENT '实操业务范围id',
  `theory_service_scope_id` varchar(64) CHARACTER SET utf8mb4 COLLATE utf8mb4_general_ci NULL DEFAULT NULL COMMENT '理论业务范围id',
  `theory_service_scope_code` varchar(2000) CHARACTER SET utf8mb4 COLLATE utf8mb4_general_ci NULL DEFAULT NULL COMMENT '理论业务范围编码',
  `exam_record_id` varchar(200) CHARACTER SET utf8mb4 COLLATE utf8mb4_general_ci NULL DEFAULT NULL COMMENT '备案单位id',
  `exam_plan_id` varchar(64) CHARACTER SET utf8mb4 COLLATE utf8mb4_general_ci NULL DEFAULT NULL COMMENT '计划单位id',
  `industry_type` varchar(64) CHARACTER SET utf8mb4 COLLATE utf8mb4_general_ci NULL DEFAULT NULL COMMENT '行业类别',
  `work_time` varchar(128) CHARACTER SET utf8mb4 COLLATE utf8mb4_general_ci NULL DEFAULT NULL COMMENT '办公时间',
  `province` varchar(64) CHARACTER SET utf8mb4 COLLATE utf8mb4_general_ci NULL DEFAULT NULL COMMENT '省',
  `city` varchar(64) CHARACTER SET utf8mb4 COLLATE utf8mb4_general_ci NULL DEFAULT NULL COMMENT '市',
  `area` varchar(64) CHARACTER SET utf8mb4 COLLATE utf8mb4_general_ci NULL DEFAULT NULL COMMENT '区',
  PRIMARY KEY (`id`) USING BTREE,
  INDEX `idx_tr_institution_area_id`(`area_id`) USING BTREE
) ENGINE = InnoDB AUTO_INCREMENT = 1000000100010001 CHARACTER SET = utf8mb4 COLLATE = utf8mb4_general_ci COMMENT = '机构信息表' ROW_FORMAT = Dynamic;

-- ----------------------------
-- Table structure for tr_institution_evaluation
-- ----------------------------
DROP TABLE IF EXISTS `tr_institution_evaluation`;
CREATE TABLE `tr_institution_evaluation`  (
  `id` bigint(20) UNSIGNED NOT NULL AUTO_INCREMENT COMMENT '主键ID（自增）',
  `institution_id` bigint(20) NOT NULL COMMENT '机构ID（关联培训机构表主键）',
  `evaluation_year` int(11) NOT NULL COMMENT '评估年度（如2025）',
  `evaluation_grade` tinyint(4) NOT NULL COMMENT '评估等级：1-优秀(A)，2-良好(B)，3-合格(C)，4-不合格(D)',
  `basic_condition_score` tinyint(4) NOT NULL COMMENT '基本条件分数（满分100分）',
  `infrastructure_score` tinyint(4) NOT NULL COMMENT '基础设施分数（满分100分）',
  `training_effect_score` tinyint(4) NOT NULL COMMENT '培训效果分数（满分100分）',
  `violation_count` tinyint(4) NOT NULL COMMENT '违规次数',
  `average_score` decimal(5, 1) NULL DEFAULT NULL COMMENT '平均分',
  `evaluation_status` tinyint(4) NOT NULL DEFAULT 0 COMMENT '评估状态：0-未评估，1-已评估',
  `create_time` datetime(0) NOT NULL DEFAULT current_timestamp(0) COMMENT '创建时间',
  `create_by` varchar(50) CHARACTER SET utf8mb4 COLLATE utf8mb4_general_ci NOT NULL COMMENT '创建人（监管侧操作人员账号/姓名）',
  `del_flag` char(1) CHARACTER SET utf8mb4 COLLATE utf8mb4_general_ci NULL DEFAULT '0' COMMENT '删除标志(0=正常,1=删除)',
  `tenant_id` bigint(20) NOT NULL DEFAULT 1 COMMENT '租户',
  PRIMARY KEY (`id`) USING BTREE,
  UNIQUE INDEX `uk_institution_year`(`institution_id`, `evaluation_year`) USING BTREE COMMENT '联合唯一索引：同一机构同一年度仅允许一条评估记录',
  INDEX `idx_evaluation_year`(`evaluation_year`) USING BTREE COMMENT '评估年度索引（便于按年度统计查询）'
) ENGINE = InnoDB AUTO_INCREMENT = 19 CHARACTER SET = utf8mb4 COLLATE = utf8mb4_general_ci COMMENT = '监管侧培训机构年度评估评分表' ROW_FORMAT = Dynamic;

-- ----------------------------
-- Table structure for tr_institution_online_training_mapping
-- ----------------------------
DROP TABLE IF EXISTS `tr_institution_online_training_mapping`;
CREATE TABLE `tr_institution_online_training_mapping`  (
  `id` bigint(20) NOT NULL COMMENT '主键ID',
  `online_training_institution_id` bigint(20) NOT NULL COMMENT '网络培训机构ID',
  `app_key` varchar(100) CHARACTER SET utf8mb4 COLLATE utf8mb4_general_ci NOT NULL COMMENT '对接 appKey',
  `app_secret` varchar(200) CHARACTER SET utf8mb4 COLLATE utf8mb4_general_ci NOT NULL COMMENT '对接 appSecret',
  `enabled` varchar(1) CHARACTER SET utf8mb4 COLLATE utf8mb4_general_ci NOT NULL DEFAULT '1' COMMENT '是否启用（0-否，1-是）',
  `remark` varchar(500) CHARACTER SET utf8mb4 COLLATE utf8mb4_general_ci NULL DEFAULT NULL COMMENT '备注',
  `create_by` varchar(64) CHARACTER SET utf8mb4 COLLATE utf8mb4_general_ci NULL DEFAULT NULL COMMENT '创建者',
  `create_time` datetime(0) NULL DEFAULT current_timestamp(0) COMMENT '创建时间',
  `update_by` varchar(64) CHARACTER SET utf8mb4 COLLATE utf8mb4_general_ci NULL DEFAULT NULL COMMENT '更新者',
  `update_time` datetime(0) NULL DEFAULT current_timestamp(0) ON UPDATE CURRENT_TIMESTAMP(0) COMMENT '更新时间',
  `del_flag` char(1) CHARACTER SET utf8mb4 COLLATE utf8mb4_general_ci NOT NULL DEFAULT '0' COMMENT '删除标志（0=正常，1=删除）',
  `tenant_id` bigint(20) NOT NULL COMMENT '租户ID/线下培训机构ID',
  PRIMARY KEY (`id`) USING BTREE,
  INDEX `idx_tr_iotm_tenant_provider`(`tenant_id`, `online_training_institution_id`) USING BTREE,
  INDEX `idx_tr_iotm_provider`(`online_training_institution_id`) USING BTREE
) ENGINE = InnoDB CHARACTER SET = utf8mb4 COLLATE = utf8mb4_general_ci COMMENT = '线下机构网络培训机构映射表' ROW_FORMAT = Dynamic;

-- ----------------------------
-- Table structure for tr_institution_qualification
-- ----------------------------
DROP TABLE IF EXISTS `tr_institution_qualification`;
CREATE TABLE `tr_institution_qualification`  (
  `id` bigint(20) UNSIGNED NOT NULL AUTO_INCREMENT COMMENT 'ID',
  `institution_id` bigint(20) NOT NULL COMMENT '机构ID',
  `qualification_id` bigint(20) NOT NULL COMMENT '资格ID',
  `create_time` datetime(0) NULL DEFAULT current_timestamp(0) COMMENT '创建时间',
