-- ----------------------------
-- Table structure for tr_national_training_plan
-- ----------------------------
DROP TABLE IF EXISTS `tr_national_training_plan`;
CREATE TABLE `tr_national_training_plan`  (
  `id` bigint(20) NOT NULL COMMENT '国家平台计划ID；历史主计划记录使用tr_training_plan.id，新子计划使用新ID',
  `main_plan_id` bigint(20) NOT NULL COMMENT '业务主培训计划ID，关联tr_training_plan.id',
  `class_id` bigint(20) NULL DEFAULT NULL COMMENT '班级ID',
  `plan_name` varchar(255) CHARACTER SET utf8mb4 COLLATE utf8mb4_general_ci NOT NULL COMMENT '国家平台计划名称',
  `main_plan_name` varchar(255) CHARACTER SET utf8mb4 COLLATE utf8mb4_general_ci NULL DEFAULT NULL COMMENT '主计划名称',
  `sub_plan_no` int(11) NULL DEFAULT NULL COMMENT '子计划序号；历史主计划兼容记录为空',
  `suffix` varchar(16) CHARACTER SET utf8mb4 COLLATE utf8mb4_general_ci NULL DEFAULT NULL COMMENT '子计划后缀：A/B/C...；历史主计划兼容记录为空',
  `push_status` tinyint(4) NOT NULL DEFAULT 0 COMMENT '推送状态：0未推送 1已推送 2推送失败 3未知',
  `student_count` int(11) NULL DEFAULT 0 COMMENT '关联学员数',
  `error_msg` varchar(1000) CHARACTER SET utf8mb4 COLLATE utf8mb4_general_ci NULL DEFAULT NULL COMMENT '错误信息',
  `tenant_id` bigint(20) NULL DEFAULT NULL COMMENT '租户ID/培训机构ID',
  `create_by` varchar(64) CHARACTER SET utf8mb4 COLLATE utf8mb4_general_ci NULL DEFAULT NULL COMMENT '创建者',
  `create_time` datetime(0) NULL DEFAULT NULL COMMENT '创建时间',
  `update_by` varchar(64) CHARACTER SET utf8mb4 COLLATE utf8mb4_general_ci NULL DEFAULT NULL COMMENT '更新者',
  `update_time` datetime(0) NULL DEFAULT NULL COMMENT '更新时间',
  `del_flag` char(1) CHARACTER SET utf8mb4 COLLATE utf8mb4_general_ci NOT NULL DEFAULT '0' COMMENT '删除标志（0=正常，1=删除）',
  PRIMARY KEY (`id`) USING BTREE,
  UNIQUE INDEX `uk_main_plan_sub_no`(`main_plan_id`, `sub_plan_no`) USING BTREE,
  INDEX `idx_main_plan_id`(`main_plan_id`) USING BTREE,
  INDEX `idx_class_id`(`class_id`) USING BTREE,
  INDEX `idx_push_status`(`push_status`) USING BTREE
) ENGINE = InnoDB CHARACTER SET = utf8mb4 COLLATE = utf8mb4_general_ci COMMENT = '国家平台培训计划表' ROW_FORMAT = Dynamic;

-- ----------------------------
-- Table structure for tr_national_training_student
-- ----------------------------
DROP TABLE IF EXISTS `tr_national_training_student`;
CREATE TABLE `tr_national_training_student`  (
  `id` bigint(20) NOT NULL AUTO_INCREMENT COMMENT '独立主键',
  `national_training_plan_id` bigint(20) NOT NULL COMMENT '关联tr_national_training_plan.id',
  `class_id` bigint(20) NOT NULL COMMENT '班级ID',
  `trainee_id` bigint(20) NOT NULL COMMENT '学员ID，关联tr_trainee.id',
  `signup_id` bigint(20) NOT NULL COMMENT '报名ID，关联tr_trainee_signup.id',
  `push_status` tinyint(4) NOT NULL DEFAULT 0 COMMENT '推送状态：0未推送 1已推送 2推送失败 3未知',
  `push_time` datetime(0) NULL DEFAULT NULL COMMENT '推送成功时间',
  `error_msg` varchar(1000) CHARACTER SET utf8mb4 COLLATE utf8mb4_general_ci NULL DEFAULT NULL COMMENT '错误信息',
  `tenant_id` bigint(20) NULL DEFAULT NULL COMMENT '租户ID/培训机构ID',
  `create_by` varchar(64) CHARACTER SET utf8mb4 COLLATE utf8mb4_general_ci NULL DEFAULT NULL COMMENT '创建者',
  `create_time` datetime(0) NULL DEFAULT NULL COMMENT '创建时间',
  `update_by` varchar(64) CHARACTER SET utf8mb4 COLLATE utf8mb4_general_ci NULL DEFAULT NULL COMMENT '更新者',
  `update_time` datetime(0) NULL DEFAULT NULL COMMENT '更新时间',
  `del_flag` char(1) CHARACTER SET utf8mb4 COLLATE utf8mb4_general_ci NOT NULL DEFAULT '0' COMMENT '删除标志（0=正常，1=删除）',
  PRIMARY KEY (`id`) USING BTREE,
  UNIQUE INDEX `uk_class_signup`(`class_id`, `signup_id`) USING BTREE,
  INDEX `idx_plan_id`(`national_training_plan_id`) USING BTREE,
  INDEX `idx_trainee_id`(`trainee_id`) USING BTREE,
  INDEX `idx_signup_id`(`signup_id`) USING BTREE,
  INDEX `idx_push_status`(`push_status`) USING BTREE
) ENGINE = InnoDB AUTO_INCREMENT = 2069681879104557073 CHARACTER SET = utf8mb4 COLLATE = utf8mb4_general_ci COMMENT = '国家平台培训计划学员关联表' ROW_FORMAT = Dynamic;

-- ----------------------------
-- Table structure for tr_national_uploaded_file
-- ----------------------------
DROP TABLE IF EXISTS `tr_national_uploaded_file`;
CREATE TABLE `tr_national_uploaded_file`  (
  `id` bigint(20) NOT NULL COMMENT '主键',
  `file_name` varchar(255) CHARACTER SET utf8mb4 COLLATE utf8mb4_general_ci NOT NULL COMMENT '本地文件名（从 filePath 提取）',
  `national_url` varchar(500) CHARACTER SET utf8mb4 COLLATE utf8mb4_general_ci NOT NULL COMMENT '国家平台返回的文件 URL',
  `create_by` varchar(64) CHARACTER SET utf8mb4 COLLATE utf8mb4_general_ci NULL DEFAULT '' COMMENT '创建者',
  `create_time` datetime(0) NULL DEFAULT NULL COMMENT '创建时间',
  `update_by` varchar(64) CHARACTER SET utf8mb4 COLLATE utf8mb4_general_ci NULL DEFAULT '' COMMENT '更新者',
  `update_time` datetime(0) NULL DEFAULT NULL COMMENT '更新时间',
  PRIMARY KEY (`id`) USING BTREE,
  UNIQUE INDEX `uk_file_name`(`file_name`) USING BTREE
) ENGINE = InnoDB CHARACTER SET = utf8mb4 COLLATE = utf8mb4_general_ci COMMENT = '国家平台已上传文件缓存' ROW_FORMAT = Dynamic;

-- ----------------------------
-- Table structure for tr_online_training_institution
-- ----------------------------
DROP TABLE IF EXISTS `tr_online_training_institution`;
CREATE TABLE `tr_online_training_institution`  (
  `id` bigint(20) NOT NULL COMMENT 'ID',
  `name` varchar(255) CHARACTER SET utf8mb4 COLLATE utf8mb4_general_ci NULL DEFAULT NULL COMMENT '机构名称',
  `code` varchar(100) CHARACTER SET utf8mb4 COLLATE utf8mb4_general_ci NULL DEFAULT NULL COMMENT '机构编码',
  `contact` varchar(100) CHARACTER SET utf8mb4 COLLATE utf8mb4_general_ci NULL DEFAULT NULL COMMENT '联系人',
  `phone` varchar(50) CHARACTER SET utf8mb4 COLLATE utf8mb4_general_ci NULL DEFAULT NULL COMMENT '联系电话',
  `address` varchar(500) CHARACTER SET utf8mb4 COLLATE utf8mb4_general_ci NULL DEFAULT NULL COMMENT '地址',
  `remark` varchar(500) CHARACTER SET utf8mb4 COLLATE utf8mb4_general_ci NULL DEFAULT NULL COMMENT '备注',
  `base_url` varchar(200) CHARACTER SET utf8mb4 COLLATE utf8mb4_general_ci NULL DEFAULT NULL COMMENT '对接 Base URL（例：https://api.xxx.com）',
  `app_key` varchar(100) CHARACTER SET utf8mb4 COLLATE utf8mb4_general_ci NULL DEFAULT NULL COMMENT '对接 appKey',
  `app_secret` varchar(200) CHARACTER SET utf8mb4 COLLATE utf8mb4_general_ci NULL DEFAULT NULL COMMENT '对接 appSecret',
  `sign_method` varchar(50) CHARACTER SET utf8mb4 COLLATE utf8mb4_general_ci NULL DEFAULT 'HMAC-SHA256' COMMENT '签名算法',
  `enabled` varchar(1) CHARACTER SET utf8mb4 COLLATE utf8mb4_general_ci NULL DEFAULT '1' COMMENT '是否启用（0-否，1-是）',
  `create_by` varchar(64) CHARACTER SET utf8mb4 COLLATE utf8mb4_general_ci NULL DEFAULT NULL COMMENT '创建者',
  `create_time` datetime(0) NULL DEFAULT NULL COMMENT '创建时间',
  `update_by` varchar(64) CHARACTER SET utf8mb4 COLLATE utf8mb4_general_ci NULL DEFAULT NULL COMMENT '更新者',
  `update_time` datetime(0) NULL DEFAULT NULL COMMENT '更新时间',
  `del_flag` char(1) CHARACTER SET utf8mb4 COLLATE utf8mb4_general_ci NULL DEFAULT '0' COMMENT '删除标志（0=正常，1=删除）',
  `tenant_id` bigint(20) NULL DEFAULT NULL COMMENT '租户id',
  PRIMARY KEY (`id`) USING BTREE
) ENGINE = InnoDB CHARACTER SET = utf8mb4 COLLATE = utf8mb4_general_ci COMMENT = '网络培训机构表' ROW_FORMAT = Dynamic;

-- ----------------------------
-- Table structure for tr_pay_charge_rule
-- ----------------------------
DROP TABLE IF EXISTS `tr_pay_charge_rule`;
CREATE TABLE `tr_pay_charge_rule`  (
  `id` bigint(20) NOT NULL COMMENT '主键ID',
  `qualification_category` varchar(20) CHARACTER SET utf8mb4 COLLATE utf8mb4_general_ci NOT NULL COMMENT '资格类别：1一类 2二类',
  `scope_type` varchar(20) CHARACTER SET utf8mb4 COLLATE utf8mb4_general_ci NOT NULL COMMENT '规则范围：GLOBAL全局 EXAM_ORG考试机构',
  `scope_id` varchar(64) CHARACTER SET utf8mb4 COLLATE utf8mb4_general_ci NOT NULL COMMENT '规则范围ID：一类GLOBAL，二类考试机构ID',
  `scope_name` varchar(200) CHARACTER SET utf8mb4 COLLATE utf8mb4_general_ci NULL DEFAULT NULL COMMENT '规则范围名称',
  `org_name` varchar(200) CHARACTER SET utf8mb4 COLLATE utf8mb4_general_ci NOT NULL COMMENT '收款组织单位',
  `org_unicode` varchar(30) CHARACTER SET utf8mb4 COLLATE utf8mb4_general_ci NOT NULL COMMENT '江西支付执收单位编码',
  `theory_item_unicode` varchar(30) CHARACTER SET utf8mb4 COLLATE utf8mb4_general_ci NULL DEFAULT NULL COMMENT '理论考试项目编码',
  `theory_item_name` varchar(200) CHARACTER SET utf8mb4 COLLATE utf8mb4_general_ci NULL DEFAULT NULL COMMENT '理论考试项目名称',
  `practice_item_unicode` varchar(30) CHARACTER SET utf8mb4 COLLATE utf8mb4_general_ci NULL DEFAULT NULL COMMENT '实操考试项目编码',
  `practice_item_name` varchar(200) CHARACTER SET utf8mb4 COLLATE utf8mb4_general_ci NULL DEFAULT NULL COMMENT '实操考试项目名称',
  `enabled` char(1) CHARACTER SET utf8mb4 COLLATE utf8mb4_general_ci NOT NULL DEFAULT '1' COMMENT '启用状态：0停用 1启用',
  `remark` varchar(500) CHARACTER SET utf8mb4 COLLATE utf8mb4_general_ci NULL DEFAULT NULL COMMENT '备注',
  `create_by` varchar(64) CHARACTER SET utf8mb4 COLLATE utf8mb4_general_ci NULL DEFAULT '' COMMENT '创建者',
  `create_time` datetime(0) NULL DEFAULT current_timestamp(0) COMMENT '创建时间',
  `update_by` varchar(64) CHARACTER SET utf8mb4 COLLATE utf8mb4_general_ci NULL DEFAULT '' COMMENT '更新者',
  `update_time` datetime(0) NULL DEFAULT current_timestamp(0) ON UPDATE CURRENT_TIMESTAMP(0) COMMENT '更新时间',
  `del_flag` char(1) CHARACTER SET utf8mb4 COLLATE utf8mb4_general_ci NOT NULL DEFAULT '0' COMMENT '删除标志（0正常 1删除）',
  `tenant_id` bigint(20) NULL DEFAULT NULL COMMENT '租户ID',
  PRIMARY KEY (`id`) USING BTREE,
  UNIQUE INDEX `uk_pay_charge_rule_scope`(`qualification_category`, `scope_type`, `scope_id`, `del_flag`) USING BTREE,
  INDEX `idx_pay_charge_rule_enabled`(`qualification_category`, `scope_type`, `enabled`, `del_flag`) USING BTREE
) ENGINE = InnoDB CHARACTER SET = utf8mb4 COLLATE = utf8mb4_general_ci COMMENT = '考试缴费规则配置表' ROW_FORMAT = Dynamic;

-- ----------------------------
-- Table structure for tr_pay_log
-- ----------------------------
DROP TABLE IF EXISTS `tr_pay_log`;
CREATE TABLE `tr_pay_log`  (
  `id` bigint(20) NOT NULL COMMENT '主键ID',
  `order_no` varchar(64) CHARACTER SET utf8mb4 COLLATE utf8mb4_general_ci NULL DEFAULT NULL COMMENT '订单号',
  `type` int(11) NULL DEFAULT NULL COMMENT '日志类型 0:请求 1:响应',
  `content` longtext CHARACTER SET utf8mb4 COLLATE utf8mb4_general_ci NULL COMMENT '内容',
  `create_time` datetime(0) NULL DEFAULT NULL COMMENT '创建时间',
  `tenant_id` bigint(20) NULL DEFAULT NULL COMMENT '租户ID',
  PRIMARY KEY (`id`) USING BTREE,
  INDEX `idx_order_no`(`order_no`) USING BTREE
) ENGINE = InnoDB CHARACTER SET = utf8mb4 COLLATE = utf8mb4_general_ci COMMENT = '支付日志表' ROW_FORMAT = Dynamic;

-- ----------------------------
-- Table structure for tr_pay_operation_log
-- ----------------------------
DROP TABLE IF EXISTS `tr_pay_operation_log`;
CREATE TABLE `tr_pay_operation_log`  (
  `id` bigint(20) NOT NULL COMMENT '主键ID',
  `biz_type` varchar(50) CHARACTER SET utf8mb4 COLLATE utf8mb4_general_ci NOT NULL COMMENT '业务类型',
  `biz_id` bigint(20) NULL DEFAULT NULL COMMENT '业务ID',
  `order_no` varchar(64) CHARACTER SET utf8mb4 COLLATE utf8mb4_general_ci NULL DEFAULT NULL COMMENT '订单号',
  `operation` varchar(50) CHARACTER SET utf8mb4 COLLATE utf8mb4_general_ci NOT NULL COMMENT '操作类型',
  `before_value` varchar(1000) CHARACTER SET utf8mb4 COLLATE utf8mb4_general_ci NULL DEFAULT NULL COMMENT '变更前值',
  `after_value` varchar(1000) CHARACTER SET utf8mb4 COLLATE utf8mb4_general_ci NULL DEFAULT NULL COMMENT '变更后值',
  `remark` varchar(1000) CHARACTER SET utf8mb4 COLLATE utf8mb4_general_ci NULL DEFAULT NULL COMMENT '备注',
  `operator` varchar(64) CHARACTER SET utf8mb4 COLLATE utf8mb4_general_ci NULL DEFAULT NULL COMMENT '操作人',
  `operate_time` datetime(0) NULL DEFAULT NULL COMMENT '操作时间',
  `create_time` datetime(0) NULL DEFAULT NULL COMMENT '创建时间',
  `update_time` datetime(0) NULL DEFAULT NULL COMMENT '更新时间',
  `tenant_id` bigint(20) NOT NULL DEFAULT 0 COMMENT '租户ID',
  PRIMARY KEY (`id`) USING BTREE,
  INDEX `idx_pay_operation_log_order`(`order_no`) USING BTREE,
  INDEX `idx_pay_operation_log_biz`(`biz_type`, `biz_id`) USING BTREE,
  INDEX `idx_pay_operation_log_time`(`operate_time`) USING BTREE
) ENGINE = InnoDB CHARACTER SET = utf8mb4 COLLATE = utf8mb4_general_ci COMMENT = '支付操作记录表' ROW_FORMAT = Dynamic;

-- ----------------------------
-- Table structure for tr_pay_order
-- ----------------------------
DROP TABLE IF EXISTS `tr_pay_order`;
CREATE TABLE `tr_pay_order`  (
  `id` bigint(20) NOT NULL COMMENT '主键ID',
  `order_no` varchar(64) CHARACTER SET utf8mb4 COLLATE utf8mb4_general_ci NOT NULL COMMENT '订单号',
  `exam_arrange_id` bigint(20) NULL DEFAULT NULL COMMENT '考试安排ID',
  `amount` decimal(10, 2) NOT NULL COMMENT '支付金额',
  `order_state` char(1) CHARACTER SET utf8mb4 COLLATE utf8mb4_general_ci NOT NULL DEFAULT '0' COMMENT '内部订单状态：4已创建 0支付中 1已支付 2支付失败 3已关闭 5异常成功',
  `third_party_tran_status` char(1) CHARACTER SET utf8mb4 COLLATE utf8mb4_general_ci NULL DEFAULT NULL COMMENT '三方交易状态：1成功 2失败 3待确认',
  `pay_time` datetime(0) NULL DEFAULT NULL COMMENT '支付时间',
  `user_id` bigint(20) NULL DEFAULT NULL COMMENT '用户ID',
  `order_source` varchar(20) CHARACTER SET utf8mb4 COLLATE utf8mb4_general_ci NULL DEFAULT NULL COMMENT '订单来源平台：INSTITUTION培训机构 GFT赣服通',
  `transaction_id` varchar(64) CHARACTER SET utf8mb4 COLLATE utf8mb4_general_ci NULL DEFAULT NULL COMMENT '第三方交易流水号',
  `remark` varchar(500) CHARACTER SET utf8mb4 COLLATE utf8mb4_general_ci NULL DEFAULT NULL COMMENT '备注',
  `create_by` varchar(64) CHARACTER SET utf8mb4 COLLATE utf8mb4_general_ci NULL DEFAULT '' COMMENT '创建者',
  `create_time` datetime(0) NULL DEFAULT NULL COMMENT '创建时间',
  `update_by` varchar(64) CHARACTER SET utf8mb4 COLLATE utf8mb4_general_ci NULL DEFAULT '' COMMENT '更新者',
  `update_time` datetime(0) NULL DEFAULT NULL COMMENT '更新时间',
  `del_flag` char(1) CHARACTER SET utf8mb4 COLLATE utf8mb4_general_ci NULL DEFAULT '0' COMMENT '删除标志（0=正常，1=删除）',
  `tenant_id` bigint(20) NULL DEFAULT NULL COMMENT '租户ID',
  `quantity` bigint(16) NULL DEFAULT 1 COMMENT '子订单数量',
  `payer_name` varchar(80) CHARACTER SET utf8mb4 COLLATE utf8mb4_general_ci NULL DEFAULT NULL COMMENT '付款人姓名',
  `phone` varchar(20) CHARACTER SET utf8mb4 COLLATE utf8mb4_general_ci NULL DEFAULT NULL COMMENT '付款人手机号',
  `order_date` varchar(8) CHARACTER SET utf8mb4 COLLATE utf8mb4_general_ci NULL DEFAULT NULL COMMENT '订单日期(yyyyMMdd)',
  `order_time` varchar(6) CHARACTER SET utf8mb4 COLLATE utf8mb4_general_ci NULL DEFAULT NULL COMMENT '订单时间(HHmmss)',
  `req_time` varchar(17) CHARACTER SET utf8mb4 COLLATE utf8mb4_general_ci NULL DEFAULT NULL COMMENT '请求时间',
  `redirect_url` varchar(200) CHARACTER SET utf8mb4 COLLATE utf8mb4_general_ci NULL DEFAULT NULL COMMENT '跳转地址',
  `notify_url` varchar(200) CHARACTER SET utf8mb4 COLLATE utf8mb4_general_ci NULL DEFAULT NULL COMMENT '通知地址',
  `remark1` varchar(200) CHARACTER SET utf8mb4 COLLATE utf8mb4_general_ci NULL DEFAULT NULL COMMENT '备注1',
  `remark2` varchar(200) CHARACTER SET utf8mb4 COLLATE utf8mb4_general_ci NULL DEFAULT NULL COMMENT '备注2',
  `remark3` varchar(200) CHARACTER SET utf8mb4 COLLATE utf8mb4_general_ci NULL DEFAULT NULL COMMENT '备注3',
  `commpara` varchar(200) CHARACTER SET utf8mb4 COLLATE utf8mb4_general_ci NULL DEFAULT NULL COMMENT '通用参数',
  `tran_bank_no` varchar(32) CHARACTER SET utf8mb4 COLLATE utf8mb4_general_ci NULL DEFAULT NULL COMMENT '交易流水号(银行)',
  `tran_date` varchar(8) CHARACTER SET utf8mb4 COLLATE utf8mb4_general_ci NULL DEFAULT NULL COMMENT '交易日期(yyyyMMdd)',
  `tran_time` varchar(6) CHARACTER SET utf8mb4 COLLATE utf8mb4_general_ci NULL DEFAULT NULL COMMENT '交易时间(HHmmss)',
  `exam_name` varchar(255) CHARACTER SET utf8mb4 COLLATE utf8mb4_general_ci NULL DEFAULT NULL COMMENT '考试名称(冗余)',
  `exam_time` varchar(100) CHARACTER SET utf8mb4 COLLATE utf8mb4_general_ci NULL DEFAULT NULL COMMENT '考试时间(冗余)',
  `subject_name` varchar(255) CHARACTER SET utf8mb4 COLLATE utf8mb4_general_ci NULL DEFAULT NULL COMMENT '科目名称(冗余)',
  `charge_standard_name` varchar(255) CHARACTER SET utf8mb4 COLLATE utf8mb4_general_ci NULL DEFAULT NULL COMMENT '收费标准名称(冗余)',
  `exam_id` bigint(20) NULL DEFAULT NULL COMMENT '考试ID',
  `pay_data` text CHARACTER SET utf8mb4 COLLATE utf8mb4_general_ci NULL COMMENT '第三方支付参数/跳转地址',
  PRIMARY KEY (`id`) USING BTREE,
  UNIQUE INDEX `uk_order_no`(`order_no`) USING BTREE,
  INDEX `idx_tr_pay_order_stat_time_order`(`del_flag`, `order_state`, `pay_time`, `order_no`) USING BTREE,
  INDEX `idx_tr_pay_order_active_scan`(`del_flag`, `order_state`, `id`) USING BTREE,
  INDEX `idx_tr_pay_order_order_date`(`del_flag`, `order_date`, `order_no`) USING BTREE,
  INDEX `idx_tr_pay_order_state_source`(`order_state`, `order_source`, `del_flag`, `id`) USING BTREE
) ENGINE = InnoDB CHARACTER SET = utf8mb4 COLLATE = utf8mb4_general_ci COMMENT = '支付订单表' ROW_FORMAT = Dynamic;

-- ----------------------------
-- Table structure for tr_pay_order_detail
-- ----------------------------
DROP TABLE IF EXISTS `tr_pay_order_detail`;
CREATE TABLE `tr_pay_order_detail`  (
  `id` bigint(20) NOT NULL COMMENT '主键ID',
  `order_no` varchar(32) CHARACTER SET utf8mb4 COLLATE utf8mb4_general_ci NOT NULL COMMENT '订单号',
  `pay_code` varchar(32) CHARACTER SET utf8mb4 COLLATE utf8mb4_general_ci NOT NULL COMMENT '缴费识别码',
  `pay_man` varchar(200) CHARACTER SET utf8mb4 COLLATE utf8mb4_general_ci NULL DEFAULT NULL COMMENT '缴款人姓名',
  `amount` decimal(16, 2) NULL DEFAULT NULL COMMENT '金额',
  `id_card_no` varchar(18) CHARACTER SET utf8mb4 COLLATE utf8mb4_general_ci NULL DEFAULT NULL COMMENT '身份证号',
  `admission_ticket_no` varchar(200) CHARACTER SET utf8mb4 COLLATE utf8mb4_general_ci NULL DEFAULT NULL COMMENT '准考证号',
  `org_unicode` varchar(30) CHARACTER SET utf8mb4 COLLATE utf8mb4_general_ci NULL DEFAULT NULL COMMENT '执收单位编码',
  `e_bill_code` varchar(30) CHARACTER SET utf8mb4 COLLATE utf8mb4_general_ci NULL DEFAULT NULL COMMENT '电子票据代码',
  `create_by` varchar(64) CHARACTER SET utf8mb4 COLLATE utf8mb4_general_ci NULL DEFAULT NULL COMMENT '创建者',
  `create_time` datetime(0) NULL DEFAULT NULL COMMENT '创建时间',
  `update_by` varchar(64) CHARACTER SET utf8mb4 COLLATE utf8mb4_general_ci NULL DEFAULT NULL COMMENT '更新者',
  `update_time` datetime(0) NULL DEFAULT NULL COMMENT '更新时间',
  `del_flag` char(1) CHARACTER SET utf8mb4 COLLATE utf8mb4_general_ci NULL DEFAULT '0' COMMENT '删除标志（0=正常，1=删除）',
  `tenant_id` bigint(20) NULL DEFAULT NULL COMMENT '租户ID',
  `credit_code` varchar(18) CHARACTER SET utf8mb4 COLLATE utf8mb4_general_ci NULL DEFAULT NULL COMMENT '统一社会信用代码',
  `note1` varchar(200) CHARACTER SET utf8mb4 COLLATE utf8mb4_general_ci NULL DEFAULT NULL COMMENT '备注1(准考证号)',
  `note2` varchar(200) CHARACTER SET utf8mb4 COLLATE utf8mb4_general_ci NULL DEFAULT NULL COMMENT '备注2(非税开票人)',
  `passport_no` varchar(9) CHARACTER SET utf8mb4 COLLATE utf8mb4_general_ci NULL DEFAULT NULL COMMENT '护照号',
  `insurance_no` varchar(18) CHARACTER SET utf8mb4 COLLATE utf8mb4_general_ci NULL DEFAULT NULL COMMENT '社保号',
  `student_number` varchar(50) CHARACTER SET utf8mb4 COLLATE utf8mb4_general_ci NULL DEFAULT NULL COMMENT '学号(OtherSerialNo)',
  `signup_id` varchar(255) CHARACTER SET utf8mb4 COLLATE utf8mb4_general_ci NULL DEFAULT NULL COMMENT '学员ID(冗余)',
  `signup_instance_id` bigint(20) NULL DEFAULT NULL COMMENT '报名实例ID',
  PRIMARY KEY (`id`) USING BTREE,
  INDEX `idx_order_no`(`order_no`) USING BTREE,
  INDEX `idx_pay_code`(`pay_code`) USING BTREE,
  INDEX `idx_tr_pay_order_detail_signup_order`(`signup_instance_id`, `del_flag`, `order_no`) USING BTREE,
  INDEX `idx_tr_pay_order_detail_signup_time`(`signup_instance_id`, `del_flag`, `create_time`, `id`) USING BTREE
) ENGINE = InnoDB CHARACTER SET = utf8mb4 COLLATE = utf8mb4_general_ci COMMENT = '支付订单明细表' ROW_FORMAT = Dynamic;

-- ----------------------------
-- Table structure for tr_pay_order_item
-- ----------------------------
DROP TABLE IF EXISTS `tr_pay_order_item`;
CREATE TABLE `tr_pay_order_item`  (
  `id` bigint(20) NOT NULL COMMENT '主键ID',
  `pay_code` varchar(32) CHARACTER SET utf8mb4 COLLATE utf8mb4_general_ci NOT NULL COMMENT '缴费识别码',
  `item_unicode` varchar(15) CHARACTER SET utf8mb4 COLLATE utf8mb4_general_ci NULL DEFAULT NULL COMMENT '项目编码',
  `unit` varchar(20) CHARACTER SET utf8mb4 COLLATE utf8mb4_general_ci NULL DEFAULT NULL COMMENT '计量单位',
  `standard` decimal(16, 2) NULL DEFAULT NULL COMMENT '执收标准',
  `quantity` bigint(16) NULL DEFAULT NULL COMMENT '执收数量',
  `payment` decimal(16, 2) NULL DEFAULT NULL COMMENT '执收金额',
  `create_by` varchar(64) CHARACTER SET utf8mb4 COLLATE utf8mb4_general_ci NULL DEFAULT NULL COMMENT '创建者',
  `create_time` datetime(0) NULL DEFAULT NULL COMMENT '创建时间',
  `update_by` varchar(64) CHARACTER SET utf8mb4 COLLATE utf8mb4_general_ci NULL DEFAULT NULL COMMENT '更新者',
  `update_time` datetime(0) NULL DEFAULT NULL COMMENT '更新时间',
  `del_flag` char(1) CHARACTER SET utf8mb4 COLLATE utf8mb4_general_ci NULL DEFAULT '0' COMMENT '删除标志（0=正常，1=删除）',
  `tenant_id` bigint(20) NULL DEFAULT NULL COMMENT '租户ID',
  PRIMARY KEY (`id`) USING BTREE,
  INDEX `idx_pay_code`(`pay_code`) USING BTREE
) ENGINE = InnoDB CHARACTER SET = utf8mb4 COLLATE = utf8mb4_general_ci COMMENT = '支付收费项目表' ROW_FORMAT = Dynamic;

-- ----------------------------
-- Table structure for tr_pay_reconcile_batch
-- ----------------------------
DROP TABLE IF EXISTS `tr_pay_reconcile_batch`;
CREATE TABLE `tr_pay_reconcile_batch`  (
  `id` bigint(20) NOT NULL COMMENT '主键ID',
  `reconcile_date` varchar(8) CHARACTER SET utf8mb4 COLLATE utf8mb4_general_ci NOT NULL COMMENT '对账日期yyyyMMdd',
  `status` varchar(20) CHARACTER SET utf8mb4 COLLATE utf8mb4_general_ci NOT NULL COMMENT '批次状态 RUNNING/SUCCESS/FAILED',
  `local_count` bigint(20) NULL DEFAULT 0 COMMENT '本地订单数',
  `remote_count` bigint(20) NULL DEFAULT 0 COMMENT '三方订单数',
  `local_success_count` bigint(20) NULL DEFAULT 0 COMMENT '本地成功订单数',
  `remote_success_count` bigint(20) NULL DEFAULT 0 COMMENT '三方成功订单数',
  `local_amount` bigint(20) NULL DEFAULT 0 COMMENT '本地成功金额，单位分',
  `remote_amount` bigint(20) NULL DEFAULT 0 COMMENT '三方成功金额，单位分',
  `diff_count` bigint(20) NULL DEFAULT 0 COMMENT '差异数量',
  `started_at` datetime(0) NULL DEFAULT NULL COMMENT '开始时间',
  `finished_at` datetime(0) NULL DEFAULT NULL COMMENT '结束时间',
  `error_message` varchar(1000) CHARACTER SET utf8mb4 COLLATE utf8mb4_general_ci NULL DEFAULT NULL COMMENT '错误摘要',
  `create_time` datetime(0) NULL DEFAULT NULL COMMENT '创建时间',
  `update_time` datetime(0) NULL DEFAULT NULL COMMENT '更新时间',
  `tenant_id` bigint(20) NOT NULL DEFAULT 0 COMMENT '租户ID',
  PRIMARY KEY (`id`) USING BTREE,
  UNIQUE INDEX `uk_pay_reconcile_batch_date_tenant`(`reconcile_date`, `tenant_id`) USING BTREE,
  INDEX `idx_pay_reconcile_batch_status_date`(`status`, `reconcile_date`) USING BTREE
) ENGINE = InnoDB CHARACTER SET = utf8mb4 COLLATE = utf8mb4_general_ci COMMENT = '支付对账批次表' ROW_FORMAT = Dynamic;

-- ----------------------------
-- Table structure for tr_pay_reconcile_diff
-- ----------------------------
DROP TABLE IF EXISTS `tr_pay_reconcile_diff`;
CREATE TABLE `tr_pay_reconcile_diff`  (
  `id` bigint(20) NOT NULL COMMENT '主键ID',
  `batch_id` bigint(20) NOT NULL COMMENT '对账批次ID',
  `reconcile_date` varchar(8) CHARACTER SET utf8mb4 COLLATE utf8mb4_general_ci NOT NULL COMMENT '对账日期yyyyMMdd',
  `order_no` varchar(64) CHARACTER SET utf8mb4 COLLATE utf8mb4_general_ci NULL DEFAULT NULL COMMENT '订单号',
  `diff_type` varchar(50) CHARACTER SET utf8mb4 COLLATE utf8mb4_general_ci NOT NULL COMMENT '差异类型',
  `local_order_state` varchar(30) CHARACTER SET utf8mb4 COLLATE utf8mb4_general_ci NULL DEFAULT NULL COMMENT '本地订单状态',
  `remote_tran_status` varchar(10) CHARACTER SET utf8mb4 COLLATE utf8mb4_general_ci NULL DEFAULT NULL COMMENT '三方交易状态',
  `local_amount` bigint(20) NULL DEFAULT NULL COMMENT '本地金额，单位分',
  `remote_amount` bigint(20) NULL DEFAULT NULL COMMENT '三方金额，单位分',
  `platform_no` varchar(64) CHARACTER SET utf8mb4 COLLATE utf8mb4_general_ci NULL DEFAULT NULL COMMENT '平台流水号',
  `tran_bank_no` varchar(64) CHARACTER SET utf8mb4 COLLATE utf8mb4_general_ci NULL DEFAULT NULL COMMENT '银行/交易流水号',
  `signup_instance_id` bigint(20) NULL DEFAULT NULL COMMENT '报名实例ID',
  `admission_ticket_no` varchar(200) CHARACTER SET utf8mb4 COLLATE utf8mb4_general_ci NULL DEFAULT NULL COMMENT '准考证号',
  `id_card_no` varchar(18) CHARACTER SET utf8mb4 COLLATE utf8mb4_general_ci NULL DEFAULT NULL COMMENT '身份证号',
  `payer_name` varchar(80) CHARACTER SET utf8mb4 COLLATE utf8mb4_general_ci NULL DEFAULT NULL COMMENT '付款人姓名',
  `phone` varchar(20) CHARACTER SET utf8mb4 COLLATE utf8mb4_general_ci NULL DEFAULT NULL COMMENT '手机号',
  `local_snapshot_json` longtext CHARACTER SET utf8mb4 COLLATE utf8mb4_general_ci NULL COMMENT '本地快照JSON',
  `remote_snapshot_json` longtext CHARACTER SET utf8mb4 COLLATE utf8mb4_general_ci NULL COMMENT '三方快照JSON',
  `handling_status` varchar(20) CHARACTER SET utf8mb4 COLLATE utf8mb4_general_ci NOT NULL DEFAULT 'PENDING' COMMENT '处置状态',
  `handler` varchar(64) CHARACTER SET utf8mb4 COLLATE utf8mb4_general_ci NULL DEFAULT NULL COMMENT '处理人',
  `handled_time` datetime(0) NULL DEFAULT NULL COMMENT '处理时间',
  `remark` varchar(1000) CHARACTER SET utf8mb4 COLLATE utf8mb4_general_ci NULL DEFAULT NULL COMMENT '备注',
  `create_time` datetime(0) NULL DEFAULT NULL COMMENT '创建时间',
  `update_time` datetime(0) NULL DEFAULT NULL COMMENT '更新时间',
  `tenant_id` bigint(20) NOT NULL DEFAULT 0 COMMENT '租户ID',
  PRIMARY KEY (`id`) USING BTREE,
  INDEX `idx_pay_reconcile_diff_batch`(`batch_id`) USING BTREE,
  INDEX `idx_pay_reconcile_diff_date_status`(`reconcile_date`, `handling_status`) USING BTREE,
  INDEX `idx_pay_reconcile_diff_order`(`order_no`) USING BTREE,
  INDEX `idx_pay_reconcile_diff_ticket`(`admission_ticket_no`) USING BTREE,
  INDEX `idx_pay_reconcile_diff_id_card`(`id_card_no`) USING BTREE
) ENGINE = InnoDB CHARACTER SET = utf8mb4 COLLATE = utf8mb4_general_ci COMMENT = '支付对账差异表' ROW_FORMAT = Dynamic;

-- ----------------------------
-- Table structure for tr_practical_exam_assessor_subject
-- ----------------------------
DROP TABLE IF EXISTS `tr_practical_exam_assessor_subject`;
CREATE TABLE `tr_practical_exam_assessor_subject`  (
  `id` bigint(20) NOT NULL COMMENT 'id',
  `exam_id` bigint(20) NOT NULL COMMENT 'exam id',
  `assessor_id` bigint(20) NOT NULL COMMENT 'assessor id',
  `assessor_name` varchar(100) CHARACTER SET utf8mb4 COLLATE utf8mb4_general_ci NULL DEFAULT NULL COMMENT 'assessor name',
  `subject_code` varchar(10) CHARACTER SET utf8mb4 COLLATE utf8mb4_general_ci NOT NULL COMMENT 'subject code',
  `enabled_flag` char(1) CHARACTER SET utf8mb4 COLLATE utf8mb4_general_ci NOT NULL DEFAULT '1' COMMENT 'enabled flag',
  `create_by` varchar(64) CHARACTER SET utf8mb4 COLLATE utf8mb4_general_ci NOT NULL DEFAULT '' COMMENT 'create by',
  `create_time` datetime(0) NOT NULL DEFAULT current_timestamp(0) COMMENT 'create time',
  `update_by` varchar(64) CHARACTER SET utf8mb4 COLLATE utf8mb4_general_ci NOT NULL DEFAULT '' COMMENT 'update by',
  `update_time` datetime(0) NOT NULL DEFAULT current_timestamp(0) ON UPDATE CURRENT_TIMESTAMP(0) COMMENT 'update time',
  `del_flag` char(1) CHARACTER SET utf8mb4 COLLATE utf8mb4_general_ci NOT NULL DEFAULT '0' COMMENT 'delete flag',
  PRIMARY KEY (`id`) USING BTREE,
  UNIQUE INDEX `uk_practical_exam_assessor_subject`(`exam_id`, `assessor_id`, `subject_code`, `del_flag`) USING BTREE
) ENGINE = InnoDB CHARACTER SET = utf8mb4 COLLATE = utf8mb4_general_ci COMMENT = 'practical exam assessor subject' ROW_FORMAT = Dynamic;

-- ----------------------------
-- Table structure for tr_practical_exam_claim_log
-- ----------------------------
DROP TABLE IF EXISTS `tr_practical_exam_claim_log`;
CREATE TABLE `tr_practical_exam_claim_log`  (
  `id` bigint(20) NOT NULL COMMENT 'id',
  `session_id` bigint(20) NOT NULL COMMENT 'session id',
  `subject_record_id` bigint(20) NOT NULL COMMENT 'subject record id',
  `segment_id` bigint(20) NULL DEFAULT NULL COMMENT '分段ID',
  `signup_instance_id` bigint(20) NOT NULL COMMENT 'signup instance id',
  `subject_code` varchar(10) CHARACTER SET utf8mb4 COLLATE utf8mb4_general_ci NOT NULL COMMENT 'subject code',
  `assessor_id` bigint(20) NOT NULL COMMENT 'assessor id',
  `assessor_name` varchar(100) CHARACTER SET utf8mb4 COLLATE utf8mb4_general_ci NULL DEFAULT NULL COMMENT 'assessor name',
  `claim_time` datetime(0) NOT NULL DEFAULT current_timestamp(0) COMMENT 'claim time',
  `release_time` datetime(0) NULL DEFAULT NULL COMMENT 'release time',
  `release_reason` varchar(500) CHARACTER SET utf8mb4 COLLATE utf8mb4_general_ci NULL DEFAULT NULL COMMENT 'release reason',
  `create_by` varchar(64) CHARACTER SET utf8mb4 COLLATE utf8mb4_general_ci NOT NULL DEFAULT '' COMMENT 'create by',
  `create_time` datetime(0) NOT NULL DEFAULT current_timestamp(0) COMMENT 'create time',
  PRIMARY KEY (`id`) USING BTREE,
  INDEX `idx_practical_exam_claim_log_session`(`session_id`, `subject_code`, `release_time`) USING BTREE,
  INDEX `idx_practical_claim_log_segment_id`(`segment_id`) USING BTREE
) ENGINE = InnoDB CHARACTER SET = utf8mb4 COLLATE = utf8mb4_general_ci COMMENT = 'practical exam claim log' ROW_FORMAT = Dynamic;

-- ----------------------------
-- Table structure for tr_practical_exam_face_verify_record
-- ----------------------------
DROP TABLE IF EXISTS `tr_practical_exam_face_verify_record`;
CREATE TABLE `tr_practical_exam_face_verify_record`  (
  `id` bigint(20) NOT NULL COMMENT '主键ID',
  `exam_id` bigint(20) NOT NULL COMMENT '考试ID',
  `signup_instance_id` bigint(20) NOT NULL COMMENT '报名实例ID',
  `session_id` bigint(20) NULL DEFAULT NULL COMMENT '实操考试会话ID',
  `segment_id` bigint(20) NULL DEFAULT NULL COMMENT '实操考试阶段ID',
  `exam_attempt_type` varchar(10) CHARACTER SET utf8mb4 COLLATE utf8mb4_general_ci NULL DEFAULT NULL COMMENT '考试性质',
  `assessor_id` bigint(20) NULL DEFAULT NULL COMMENT '考评员ID',
  `assessor_name` varchar(100) CHARACTER SET utf8mb4 COLLATE utf8mb4_general_ci NULL DEFAULT NULL COMMENT '考评员姓名',
  `reference_photo_path` varchar(500) CHARACTER SET utf8mb4 COLLATE utf8mb4_general_ci NULL DEFAULT NULL COMMENT '参考照片路径',
  `live_photo_path` varchar(500) CHARACTER SET utf8mb4 COLLATE utf8mb4_general_ci NOT NULL COMMENT '现场照片路径',
  `live_photo_bucket_name` varchar(100) CHARACTER SET utf8mb4 COLLATE utf8mb4_general_ci NULL DEFAULT NULL COMMENT '现场照片存储桶',
  `live_photo_file_name` varchar(255) CHARACTER SET utf8mb4 COLLATE utf8mb4_general_ci NULL DEFAULT NULL COMMENT '现场照片系统文件名',
  `score` decimal(8, 4) NULL DEFAULT NULL COMMENT '百度相似度',
  `threshold` decimal(8, 4) NULL DEFAULT NULL COMMENT '本次阈值',
  `passed` tinyint(4) NOT NULL DEFAULT 0 COMMENT '是否通过：1=通过，0=失败',
  `baidu_log_id` bigint(20) NULL DEFAULT NULL COMMENT '百度日志ID',
  `fail_reason` varchar(500) CHARACTER SET utf8mb4 COLLATE utf8mb4_general_ci NULL DEFAULT NULL COMMENT '失败原因或异常摘要',
  `verify_time` datetime(0) NOT NULL DEFAULT current_timestamp(0) COMMENT '核验时间',
  `create_by` varchar(64) CHARACTER SET utf8mb4 COLLATE utf8mb4_general_ci NOT NULL DEFAULT '' COMMENT '创建者',
  `create_time` datetime(0) NOT NULL DEFAULT current_timestamp(0) COMMENT '创建时间',
  `update_by` varchar(64) CHARACTER SET utf8mb4 COLLATE utf8mb4_general_ci NOT NULL DEFAULT '' COMMENT '更新者',
  `update_time` datetime(0) NOT NULL DEFAULT current_timestamp(0) ON UPDATE CURRENT_TIMESTAMP(0) COMMENT '更新时间',
  `del_flag` char(1) CHARACTER SET utf8mb4 COLLATE utf8mb4_general_ci NOT NULL DEFAULT '0' COMMENT '删除标志（0=正常，1=删除）',
  `tenant_id` bigint(20) NULL DEFAULT NULL COMMENT '租户',
  PRIMARY KEY (`id`) USING BTREE,
  INDEX `idx_practical_face_verify_segment`(`segment_id`) USING BTREE,
  INDEX `idx_practical_face_verify_session`(`session_id`, `verify_time`) USING BTREE,
  INDEX `idx_practical_face_verify_signup`(`signup_instance_id`, `exam_attempt_type`, `verify_time`) USING BTREE,
  INDEX `idx_practical_face_verify_live_file`(`live_photo_bucket_name`, `live_photo_file_name`) USING BTREE
) ENGINE = InnoDB CHARACTER SET = utf8mb4 COLLATE = utf8mb4_general_ci COMMENT = '实操考试阶段人脸核验记录' ROW_FORMAT = Dynamic;

-- ----------------------------
-- Table structure for tr_practical_exam_media
-- ----------------------------
DROP TABLE IF EXISTS `tr_practical_exam_media`;
CREATE TABLE `tr_practical_exam_media`  (
  `id` bigint(20) NOT NULL COMMENT 'id',
  `session_id` bigint(20) NOT NULL COMMENT 'session id',
  `subject_record_id` bigint(20) NOT NULL COMMENT 'subject record id',
  `subject_code` varchar(10) CHARACTER SET utf8mb4 COLLATE utf8mb4_general_ci NOT NULL COMMENT 'subject code',
  `media_type` varchar(32) CHARACTER SET utf8mb4 COLLATE utf8mb4_general_ci NOT NULL COMMENT 'media type',
  `file_path` varchar(500) CHARACTER SET utf8mb4 COLLATE utf8mb4_general_ci NOT NULL COMMENT 'file path',
  `shot_time` datetime(0) NOT NULL DEFAULT current_timestamp(0) COMMENT 'shot time',
  `sort_no` int(11) NOT NULL DEFAULT 1 COMMENT 'sort no',
  `create_by` varchar(64) CHARACTER SET utf8mb4 COLLATE utf8mb4_general_ci NOT NULL DEFAULT '' COMMENT 'create by',
  `create_time` datetime(0) NOT NULL DEFAULT current_timestamp(0) COMMENT 'create time',
  `update_by` varchar(64) CHARACTER SET utf8mb4 COLLATE utf8mb4_general_ci NOT NULL DEFAULT '' COMMENT 'update by',
  `update_time` datetime(0) NOT NULL DEFAULT current_timestamp(0) ON UPDATE CURRENT_TIMESTAMP(0) COMMENT 'update time',
  `del_flag` char(1) CHARACTER SET utf8mb4 COLLATE utf8mb4_general_ci NOT NULL DEFAULT '0' COMMENT 'delete flag',
  PRIMARY KEY (`id`) USING BTREE,
  INDEX `idx_practical_exam_media_subject`(`subject_record_id`, `sort_no`, `del_flag`) USING BTREE
) ENGINE = InnoDB CHARACTER SET = utf8mb4 COLLATE = utf8mb4_general_ci COMMENT = 'practical exam media' ROW_FORMAT = Dynamic;

-- ----------------------------
-- Table structure for tr_practical_exam_record
-- ----------------------------
DROP TABLE IF EXISTS `tr_practical_exam_record`;
CREATE TABLE `tr_practical_exam_record`  (
  `id` bigint(20) NOT NULL COMMENT 'ID',
  `exam_id` bigint(20) NULL DEFAULT NULL COMMENT '考试ID',
  `apply_id` bigint(20) NULL DEFAULT NULL COMMENT '报名申请ID',
  `assessor_id` bigint(20) NULL DEFAULT NULL COMMENT '考评员ID(取登录态staffId)',
  `total_score` double NULL DEFAULT NULL COMMENT '总分',
  `start_time` datetime(0) NULL DEFAULT NULL COMMENT '开始时间',
  `end_time` datetime(0) NULL DEFAULT NULL COMMENT '结束时间',
  `violation_level` varchar(50) CHARACTER SET utf8mb4 COLLATE utf8mb4_general_ci NULL DEFAULT NULL COMMENT '违规等级',
  `violation_desc` varchar(500) CHARACTER SET utf8mb4 COLLATE utf8mb4_general_ci NULL DEFAULT NULL COMMENT '违规描述',
  `sign_candidate` varchar(512) CHARACTER SET utf8mb4 COLLATE utf8mb4_general_ci NULL DEFAULT NULL COMMENT '考生签名URL',
  `sign_assessor` varchar(512) CHARACTER SET utf8mb4 COLLATE utf8mb4_general_ci NULL DEFAULT NULL COMMENT '考评员签名URL',
  `photos` varchar(2048) CHARACTER SET utf8mb4 COLLATE utf8mb4_general_ci NULL DEFAULT NULL COMMENT '照片记录URL(多个|分隔)',
  `status` int(11) NULL DEFAULT 0 COMMENT '状态(0进行中 1已完成)',
  `create_by` varchar(64) CHARACTER SET utf8mb4 COLLATE utf8mb4_general_ci NULL DEFAULT NULL COMMENT '创建者',
  `create_time` datetime(0) NULL DEFAULT NULL COMMENT '创建时间',
  `update_by` varchar(64) CHARACTER SET utf8mb4 COLLATE utf8mb4_general_ci NULL DEFAULT NULL COMMENT '更新者',
  `update_time` datetime(0) NULL DEFAULT NULL COMMENT '更新时间',
  `del_flag` char(1) CHARACTER SET utf8mb4 COLLATE utf8mb4_general_ci NULL DEFAULT '0' COMMENT '删除标志(0正常 1删除)',
  `signup_instance_id` bigint(20) NULL DEFAULT NULL COMMENT '报名申请实例ID',
  `exam_attempt_type` varchar(10) CHARACTER SET utf8mb4 COLLATE utf8mb4_general_ci NULL DEFAULT NULL COMMENT '是否初考(1初考 0补考)',
  PRIMARY KEY (`id`) USING BTREE,
  INDEX `idx_exam_id`(`exam_id`) USING BTREE,
  INDEX `idx_apply_id`(`apply_id`) USING BTREE,
  INDEX `idx_assessor_id`(`assessor_id`) USING BTREE
) ENGINE = InnoDB CHARACTER SET = utf8mb4 COLLATE = utf8mb4_general_ci COMMENT = '实操考试记录' ROW_FORMAT = Dynamic;

-- ----------------------------
-- Table structure for tr_practical_exam_record_detail
-- ----------------------------
DROP TABLE IF EXISTS `tr_practical_exam_record_detail`;
CREATE TABLE `tr_practical_exam_record_detail`  (
  `id` bigint(20) NOT NULL COMMENT 'ID',
  `record_id` bigint(20) NULL DEFAULT NULL COMMENT '实操记录ID',
  `subject_code` varchar(50) CHARACTER SET utf8mb4 COLLATE utf8mb4_general_ci NULL DEFAULT NULL COMMENT '科目编号',
  `question_id` bigint(20) NULL DEFAULT NULL COMMENT '考题ID',
  `standard_id` bigint(20) NULL DEFAULT NULL COMMENT '评分标准ID',
  `score` double NULL DEFAULT NULL COMMENT '得分',
  `remark` varchar(500) CHARACTER SET utf8mb4 COLLATE utf8mb4_general_ci NULL DEFAULT NULL COMMENT '备注',
  PRIMARY KEY (`id`) USING BTREE,
  INDEX `idx_record_id`(`record_id`) USING BTREE
) ENGINE = InnoDB CHARACTER SET = utf8mb4 COLLATE = utf8mb4_general_ci COMMENT = '实操考试记录明细' ROW_FORMAT = Dynamic;

-- ----------------------------
-- Table structure for tr_practical_exam_score_change_log
-- ----------------------------
DROP TABLE IF EXISTS `tr_practical_exam_score_change_log`;
CREATE TABLE `tr_practical_exam_score_change_log`  (
  `id` bigint(20) NOT NULL COMMENT 'id',
  `session_id` bigint(20) NOT NULL COMMENT 'session id',
  `subject_record_id` bigint(20) NOT NULL COMMENT 'subject record id',
  `subject_item_id` bigint(20) NOT NULL COMMENT 'subject item id',
  `subject_code` varchar(10) CHARACTER SET utf8mb4 COLLATE utf8mb4_general_ci NOT NULL COMMENT 'subject code',
  `before_score` decimal(6, 2) NOT NULL COMMENT 'before score',
  `after_score` decimal(6, 2) NOT NULL COMMENT 'after score',
  `change_reason` varchar(500) CHARACTER SET utf8mb4 COLLATE utf8mb4_general_ci NOT NULL COMMENT 'change reason',
  `changed_by_assessor_id` bigint(20) NOT NULL COMMENT 'changed by assessor id',
  `changed_by_assessor_name` varchar(100) CHARACTER SET utf8mb4 COLLATE utf8mb4_general_ci NULL DEFAULT NULL COMMENT 'changed by assessor name',
  `changed_time` datetime(0) NOT NULL DEFAULT current_timestamp(0) COMMENT 'changed time',
  `score_version_before` int(11) NOT NULL DEFAULT 1 COMMENT 'score version before',
  `score_version_after` int(11) NOT NULL DEFAULT 1 COMMENT 'score version after',
  PRIMARY KEY (`id`) USING BTREE,
  INDEX `idx_practical_exam_score_change_log_subject`(`subject_record_id`, `changed_time`) USING BTREE
) ENGINE = InnoDB CHARACTER SET = utf8mb4 COLLATE = utf8mb4_general_ci COMMENT = 'practical exam score change log' ROW_FORMAT = Dynamic;

-- ----------------------------
-- Table structure for tr_practical_exam_segment
-- ----------------------------
DROP TABLE IF EXISTS `tr_practical_exam_segment`;
CREATE TABLE `tr_practical_exam_segment`  (
  `id` bigint(20) NOT NULL COMMENT '主键ID',
  `session_id` bigint(20) NOT NULL COMMENT '会话ID',
  `exam_id` bigint(20) NOT NULL COMMENT '考试ID',
  `signup_instance_id` bigint(20) NOT NULL COMMENT '报名实例ID',
  `assessor_id` bigint(20) NOT NULL COMMENT '考评员ID',
  `assessor_name` varchar(64) CHARACTER SET utf8mb4 COLLATE utf8mb4_general_ci NULL DEFAULT NULL COMMENT '考评员姓名',
  `segment_no` int(11) NOT NULL COMMENT '分段序号',
  `segment_status` varchar(32) CHARACTER SET utf8mb4 COLLATE utf8mb4_general_ci NOT NULL COMMENT '分段状态',
  `locked_subject_codes` varchar(64) CHARACTER SET utf8mb4 COLLATE utf8mb4_general_ci NOT NULL COMMENT '锁定科目编码列表',
  `completed_subject_codes` varchar(64) CHARACTER SET utf8mb4 COLLATE utf8mb4_general_ci NULL DEFAULT NULL COMMENT '已完成科目编码列表',
  `start_time` datetime(0) NULL DEFAULT NULL COMMENT '开始时间',
  `end_time` datetime(0) NULL DEFAULT NULL COMMENT '结束时间',
  `create_by` varchar(64) CHARACTER SET utf8mb4 COLLATE utf8mb4_general_ci NOT NULL DEFAULT '' COMMENT '创建者',
  `create_time` datetime(0) NOT NULL DEFAULT current_timestamp(0) COMMENT '创建时间',
  `update_by` varchar(64) CHARACTER SET utf8mb4 COLLATE utf8mb4_general_ci NOT NULL DEFAULT '' COMMENT '更新者',
  `update_time` datetime(0) NOT NULL DEFAULT current_timestamp(0) ON UPDATE CURRENT_TIMESTAMP(0) COMMENT '更新时间',
  `del_flag` char(1) CHARACTER SET utf8mb4 COLLATE utf8mb4_general_ci NOT NULL DEFAULT '0' COMMENT '删除标志（0=正常，1=删除）',
  `tenant_id` bigint(20) NULL DEFAULT NULL COMMENT '租户',
  PRIMARY KEY (`id`) USING BTREE,
  INDEX `idx_practical_segment_session_status`(`session_id`, `segment_status`) USING BTREE,
  INDEX `idx_practical_segment_signup`(`signup_instance_id`) USING BTREE
) ENGINE = InnoDB CHARACTER SET = utf8mb4 COLLATE = utf8mb4_general_ci COMMENT = '实操考试分段表' ROW_FORMAT = Dynamic;

-- ----------------------------
-- Table structure for tr_practical_exam_session
-- ----------------------------
DROP TABLE IF EXISTS `tr_practical_exam_session`;
CREATE TABLE `tr_practical_exam_session`  (
  `id` bigint(20) NOT NULL COMMENT 'id',
  `exam_id` bigint(20) NOT NULL COMMENT 'exam id',
  `signup_instance_id` bigint(20) NOT NULL COMMENT 'signup instance id',
  `exam_signup_id` bigint(20) NULL DEFAULT NULL COMMENT 'exam signup id',
  `trainee_id` bigint(20) NULL DEFAULT NULL COMMENT 'trainee id',
  `ticket` varchar(100) CHARACTER SET utf8mb4 COLLATE utf8mb4_general_ci NULL DEFAULT NULL COMMENT 'ticket',
  `exam_attempt_type` varchar(10) CHARACTER SET utf8mb4 COLLATE utf8mb4_general_ci NOT NULL COMMENT 'attempt type',
  `session_status` varchar(32) CHARACTER SET utf8mb4 COLLATE utf8mb4_general_ci NOT NULL COMMENT 'session status',
  `occupy_assessor_id` bigint(20) NULL DEFAULT NULL COMMENT 'occupy assessor id',
  `occupy_assessor_name` varchar(100) CHARACTER SET utf8mb4 COLLATE utf8mb4_general_ci NULL DEFAULT NULL COMMENT 'occupy assessor name',
  `occupy_subject_code` varchar(10) CHARACTER SET utf8mb4 COLLATE utf8mb4_general_ci NULL DEFAULT NULL COMMENT 'occupy subject code',
  `occupy_start_time` datetime(0) NULL DEFAULT NULL COMMENT 'occupy start time',
  `total_score` decimal(6, 2) NULL DEFAULT NULL COMMENT 'total score',
  `final_result` varchar(10) CHARACTER SET utf8mb4 COLLATE utf8mb4_general_ci NULL DEFAULT NULL COMMENT 'final result',
  `start_time` datetime(0) NULL DEFAULT NULL COMMENT 'start time',
  `all_subject_completed_time` datetime(0) NULL DEFAULT NULL COMMENT 'all subject completed time',
  `final_confirm_assessor_id` bigint(20) NULL DEFAULT NULL COMMENT 'final confirm assessor id',
  `final_confirm_assessor_name` varchar(100) CHARACTER SET utf8mb4 COLLATE utf8mb4_general_ci NULL DEFAULT NULL COMMENT 'final confirm assessor name',
  `final_confirm_time` datetime(0) NULL DEFAULT NULL COMMENT 'final confirm time',
  `candidate_sign_path` varchar(500) CHARACTER SET utf8mb4 COLLATE utf8mb4_general_ci NULL DEFAULT NULL COMMENT 'candidate sign path',
  `locked_time` datetime(0) NULL DEFAULT NULL COMMENT 'locked time',
  `verify_theory_pass_flag` char(1) CHARACTER SET utf8mb4 COLLATE utf8mb4_general_ci NOT NULL DEFAULT '0' COMMENT 'verify theory flag',
  `verify_pay_pass_flag` char(1) CHARACTER SET utf8mb4 COLLATE utf8mb4_general_ci NOT NULL DEFAULT '0' COMMENT 'verify pay flag',
  `verify_live_pass_flag` char(1) CHARACTER SET utf8mb4 COLLATE utf8mb4_general_ci NOT NULL DEFAULT '0' COMMENT 'verify live flag',
  `version` int(11) NOT NULL DEFAULT 0 COMMENT 'version',
  `create_by` varchar(64) CHARACTER SET utf8mb4 COLLATE utf8mb4_general_ci NOT NULL DEFAULT '' COMMENT 'create by',
  `create_time` datetime(0) NOT NULL DEFAULT current_timestamp(0) COMMENT 'create time',
  `update_by` varchar(64) CHARACTER SET utf8mb4 COLLATE utf8mb4_general_ci NOT NULL DEFAULT '' COMMENT 'update by',
  `update_time` datetime(0) NOT NULL DEFAULT current_timestamp(0) ON UPDATE CURRENT_TIMESTAMP(0) COMMENT 'update time',
  `del_flag` char(1) CHARACTER SET utf8mb4 COLLATE utf8mb4_general_ci NOT NULL DEFAULT '0' COMMENT 'delete flag',
  PRIMARY KEY (`id`) USING BTREE,
  UNIQUE INDEX `uk_practical_exam_session`(`signup_instance_id`, `exam_attempt_type`, `del_flag`) USING BTREE,
  INDEX `idx_practical_exam_session_exam`(`exam_id`, `session_status`) USING BTREE,
  INDEX `idx_practical_exam_session_occupy`(`occupy_assessor_id`, `occupy_subject_code`) USING BTREE
) ENGINE = InnoDB CHARACTER SET = utf8mb4 COLLATE = utf8mb4_general_ci COMMENT = 'practical exam session' ROW_FORMAT = Dynamic;

-- ----------------------------
-- Table structure for tr_practical_exam_subject_item
-- ----------------------------
DROP TABLE IF EXISTS `tr_practical_exam_subject_item`;
CREATE TABLE `tr_practical_exam_subject_item`  (
  `id` bigint(20) NOT NULL COMMENT 'id',
  `subject_record_id` bigint(20) NOT NULL COMMENT 'subject record id',
  `question_standard_id` bigint(20) NULL DEFAULT NULL COMMENT 'question standard id',
  `item_sort` int(11) NOT NULL COMMENT 'item sort',
  `item_type` varchar(32) CHARACTER SET utf8mb4 COLLATE utf8mb4_general_ci NULL DEFAULT NULL COMMENT 'item type',
  `item_content_snapshot` text CHARACTER SET utf8mb4 COLLATE utf8mb4_general_ci NULL COMMENT 'item content snapshot',
  `grading_standard_snapshot` text CHARACTER SET utf8mb4 COLLATE utf8mb4_general_ci NULL COMMENT 'grading standard snapshot',
  `full_score` decimal(6, 2) NOT NULL COMMENT 'full score',
  `full_score_text` varchar(128) CHARACTER SET utf8mb4 COLLATE utf8mb4_general_ci NULL DEFAULT NULL COMMENT '满分文本，否定项使用',
  `negative_flag` int(11) NOT NULL DEFAULT 0 COMMENT 'negative flag',
  `negative_hit_flag` int(11) NOT NULL DEFAULT 0 COMMENT 'negative hit flag',
  `score` decimal(6, 2) NOT NULL COMMENT 'score',
  `score_remark` varchar(500) CHARACTER SET utf8mb4 COLLATE utf8mb4_general_ci NULL DEFAULT NULL COMMENT 'score remark',
  `create_by` varchar(64) CHARACTER SET utf8mb4 COLLATE utf8mb4_general_ci NOT NULL DEFAULT '' COMMENT 'create by',
  `create_time` datetime(0) NOT NULL DEFAULT current_timestamp(0) COMMENT 'create time',
  `update_by` varchar(64) CHARACTER SET utf8mb4 COLLATE utf8mb4_general_ci NOT NULL DEFAULT '' COMMENT 'update by',
  `update_time` datetime(0) NOT NULL DEFAULT current_timestamp(0) ON UPDATE CURRENT_TIMESTAMP(0) COMMENT 'update time',
  `del_flag` char(1) CHARACTER SET utf8mb4 COLLATE utf8mb4_general_ci NOT NULL DEFAULT '0' COMMENT 'delete flag',
  PRIMARY KEY (`id`) USING BTREE,
  UNIQUE INDEX `uk_practical_exam_subject_item`(`subject_record_id`, `item_sort`, `del_flag`) USING BTREE
) ENGINE = InnoDB CHARACTER SET = utf8mb4 COLLATE = utf8mb4_general_ci COMMENT = 'practical exam subject item' ROW_FORMAT = Dynamic;

-- ----------------------------
-- Table structure for tr_practical_exam_subject_record
-- ----------------------------
DROP TABLE IF EXISTS `tr_practical_exam_subject_record`;
CREATE TABLE `tr_practical_exam_subject_record`  (
  `id` bigint(20) NOT NULL COMMENT 'id',
  `session_id` bigint(20) NOT NULL COMMENT 'session id',
  `subject_code` varchar(10) CHARACTER SET utf8mb4 COLLATE utf8mb4_general_ci NOT NULL COMMENT 'subject code',
  `subject_name_snapshot` varchar(128) CHARACTER SET utf8mb4 COLLATE utf8mb4_general_ci NULL DEFAULT NULL COMMENT '科目名称快照',
  `subject_weight_percent` decimal(5, 2) NULL DEFAULT NULL COMMENT '科目权重快照',
  `subject_sort_no` int(11) NULL DEFAULT NULL COMMENT '科目排序号快照',
  `segment_id` bigint(20) NULL DEFAULT NULL COMMENT '分段ID',
  `subject_status` varchar(32) CHARACTER SET utf8mb4 COLLATE utf8mb4_general_ci NOT NULL COMMENT 'subject status',
  `question_id` bigint(20) NULL DEFAULT NULL COMMENT 'question id',
  `question_title_snapshot` varchar(255) CHARACTER SET utf8mb4 COLLATE utf8mb4_general_ci NULL DEFAULT NULL COMMENT 'question title snapshot',
  `question_duration` int(11) NULL DEFAULT NULL COMMENT 'question duration',
  `claimed_assessor_id` bigint(20) NULL DEFAULT NULL COMMENT 'claimed assessor id',
  `claimed_assessor_name` varchar(100) CHARACTER SET utf8mb4 COLLATE utf8mb4_general_ci NULL DEFAULT NULL COMMENT 'claimed assessor name',
  `claim_time` datetime(0) NULL DEFAULT NULL COMMENT 'claim time',
  `subject_total_score` decimal(6, 2) NULL DEFAULT NULL COMMENT 'subject total score',
  `score_source` varchar(32) CHARACTER SET utf8mb4 COLLATE utf8mb4_general_ci NULL DEFAULT 'MANUAL_ITEM' COMMENT '评分来源：MANUAL_ITEM逐项人工评分，OFFLINE_DEVICE线下设备分数录入',
  `start_time` datetime(0) NULL DEFAULT NULL COMMENT 'start time',
  `end_time` datetime(0) NULL DEFAULT NULL COMMENT 'end time',
  `auto_submit_flag` char(1) CHARACTER SET utf8mb4 COLLATE utf8mb4_general_ci NOT NULL DEFAULT '0' COMMENT 'auto submit flag',
  `assessor_sign_path` varchar(500) CHARACTER SET utf8mb4 COLLATE utf8mb4_general_ci NULL DEFAULT NULL COMMENT 'assessor sign path',
  `assessor_sign_time` datetime(0) NULL DEFAULT NULL COMMENT 'assessor sign time',
  `score_version` int(11) NOT NULL DEFAULT 1 COMMENT 'score version',
  `last_change_reason` varchar(500) CHARACTER SET utf8mb4 COLLATE utf8mb4_general_ci NULL DEFAULT NULL COMMENT 'last change reason',
  `create_by` varchar(64) CHARACTER SET utf8mb4 COLLATE utf8mb4_general_ci NOT NULL DEFAULT '' COMMENT 'create by',
  `create_time` datetime(0) NOT NULL DEFAULT current_timestamp(0) COMMENT 'create time',
  `update_by` varchar(64) CHARACTER SET utf8mb4 COLLATE utf8mb4_general_ci NOT NULL DEFAULT '' COMMENT 'update by',
  `update_time` datetime(0) NOT NULL DEFAULT current_timestamp(0) ON UPDATE CURRENT_TIMESTAMP(0) COMMENT 'update time',
  `del_flag` char(1) CHARACTER SET utf8mb4 COLLATE utf8mb4_general_ci NOT NULL DEFAULT '0' COMMENT 'delete flag',
  PRIMARY KEY (`id`) USING BTREE,
  UNIQUE INDEX `uk_practical_exam_subject_record`(`session_id`, `subject_code`, `del_flag`) USING BTREE,
  INDEX `idx_practical_exam_subject_record_status`(`session_id`, `subject_status`) USING BTREE,
  INDEX `idx_practical_subject_record_segment_id`(`segment_id`) USING BTREE
) ENGINE = InnoDB CHARACTER SET = utf8mb4 COLLATE = utf8mb4_general_ci COMMENT = 'practical exam subject record' ROW_FORMAT = Dynamic;

-- ----------------------------
-- Table structure for tr_practical_exam_violation_log
-- ----------------------------
DROP TABLE IF EXISTS `tr_practical_exam_violation_log`;
CREATE TABLE `tr_practical_exam_violation_log`  (
  `id` bigint(20) NOT NULL COMMENT 'id',
  `session_id` bigint(20) NOT NULL COMMENT 'session id',
  `subject_record_id` bigint(20) NOT NULL COMMENT 'subject record id',
  `subject_code` varchar(10) CHARACTER SET utf8mb4 COLLATE utf8mb4_general_ci NOT NULL COMMENT 'subject code',
  `violation_type` varchar(64) CHARACTER SET utf8mb4 COLLATE utf8mb4_general_ci NULL DEFAULT NULL COMMENT 'violation type',
  `violation_level` varchar(64) CHARACTER SET utf8mb4 COLLATE utf8mb4_general_ci NULL DEFAULT NULL COMMENT 'violation level',
  `violation_desc` varchar(500) CHARACTER SET utf8mb4 COLLATE utf8mb4_general_ci NULL DEFAULT NULL COMMENT 'violation desc',
  `recorded_by_assessor_id` bigint(20) NOT NULL COMMENT 'recorded by assessor id',
  `recorded_by_assessor_name` varchar(100) CHARACTER SET utf8mb4 COLLATE utf8mb4_general_ci NULL DEFAULT NULL COMMENT 'recorded by assessor name',
  `record_time` datetime(0) NOT NULL DEFAULT current_timestamp(0) COMMENT 'record time',
  PRIMARY KEY (`id`) USING BTREE,
  INDEX `idx_practical_exam_violation_log_subject`(`subject_record_id`, `record_time`) USING BTREE
) ENGINE = InnoDB CHARACTER SET = utf8mb4 COLLATE = utf8mb4_general_ci COMMENT = 'practical exam violation log' ROW_FORMAT = Dynamic;

-- ----------------------------
-- Table structure for tr_practical_question
-- ----------------------------
DROP TABLE IF EXISTS `tr_practical_question`;
CREATE TABLE `tr_practical_question`  (
  `id` bigint(20) NOT NULL COMMENT 'ID',
  `qualification_code` varchar(64) CHARACTER SET utf8mb4 COLLATE utf8mb4_general_ci NULL DEFAULT NULL COMMENT '操作项目编号(关联资格表)',
  `subject_category_code` varchar(32) CHARACTER SET utf8mb4 COLLATE utf8mb4_general_ci NULL DEFAULT NULL COMMENT '科目大类编码',
  `subject_code` varchar(64) CHARACTER SET utf8mb4 COLLATE utf8mb4_general_ci NULL DEFAULT NULL COMMENT '科目编号',
  `exam_item` varchar(64) CHARACTER SET utf8mb4 COLLATE utf8mb4_general_ci NULL DEFAULT NULL COMMENT '考试项目',
  `duration` int(11) NULL DEFAULT NULL COMMENT '考试时长(分钟)',
  `question_type` varchar(10) CHARACTER SET utf8mb4 COLLATE utf8mb4_general_ci NULL DEFAULT NULL COMMENT '考题类型(1旧考题 2新考题)',
  `create_by` varchar(64) CHARACTER SET utf8mb4 COLLATE utf8mb4_general_ci NULL DEFAULT NULL COMMENT '创建人',
  `create_time` datetime(0) NULL DEFAULT NULL COMMENT '创建时间',
  `update_by` varchar(64) CHARACTER SET utf8mb4 COLLATE utf8mb4_general_ci NULL DEFAULT NULL COMMENT '更新人',
  `update_time` datetime(0) NULL DEFAULT NULL COMMENT '更新时间',
  `del_flag` char(1) CHARACTER SET utf8mb4 COLLATE utf8mb4_general_ci NULL DEFAULT '0' COMMENT '逻辑删除(1删除0正常)',
  PRIMARY KEY (`id`) USING BTREE,
  INDEX `idx_practical_question_qualification_subject_type_del`(`qualification_code`, `subject_code`, `question_type`, `del_flag`) USING BTREE,
  INDEX `idx_practical_question_qualification_category_type_del`(`qualification_code`, `subject_category_code`, `question_type`, `del_flag`) USING BTREE
) ENGINE = InnoDB CHARACTER SET = utf8mb4 COLLATE = utf8mb4_general_ci COMMENT = '实操考题' ROW_FORMAT = Dynamic;

-- ----------------------------
-- Table structure for tr_practical_question_standard
-- ----------------------------
DROP TABLE IF EXISTS `tr_practical_question_standard`;
CREATE TABLE `tr_practical_question_standard`  (
  `id` bigint(20) NOT NULL COMMENT 'ID',
  `question_id` bigint(20) NULL DEFAULT NULL COMMENT '考题ID',
  `sort` int(11) NULL DEFAULT NULL COMMENT '序号',
  `content` text CHARACTER SET utf8mb4 COLLATE utf8mb4_general_ci NULL COMMENT '考试内容',
  `score` int(11) NULL DEFAULT NULL COMMENT '配分',
  `score_text` varchar(128) CHARACTER SET utf8mb4 COLLATE utf8mb4_general_ci NULL DEFAULT NULL COMMENT '配分文本，否定项使用',
  `grading_standard` text CHARACTER SET utf8mb4 COLLATE utf8mb4_general_ci NULL COMMENT '评分标准',
  `is_negative` int(1) NULL DEFAULT 0 COMMENT '是否否定项(1是0否)',
  PRIMARY KEY (`id`) USING BTREE
) ENGINE = InnoDB CHARACTER SET = utf8mb4 COLLATE = utf8mb4_general_ci COMMENT = '实操考题标准' ROW_FORMAT = Dynamic;

-- ----------------------------
-- Table structure for tr_practical_subject_category
-- ----------------------------
DROP TABLE IF EXISTS `tr_practical_subject_category`;
CREATE TABLE `tr_practical_subject_category`  (
  `id` bigint(20) UNSIGNED NOT NULL AUTO_INCREMENT COMMENT 'ID',
  `qualification_code` varchar(64) CHARACTER SET utf8mb4 COLLATE utf8mb4_general_ci NOT NULL COMMENT '操作项目编号',
  `subject_category_code` varchar(32) CHARACTER SET utf8mb4 COLLATE utf8mb4_general_ci NOT NULL COMMENT '科目大类编码，如 K1/K2/K3',
  `weight_percent` decimal(5, 2) NOT NULL COMMENT '权重占比',
  `sort_no` int(11) NULL DEFAULT 0 COMMENT '排序号',
  `create_by` varchar(64) CHARACTER SET utf8mb4 COLLATE utf8mb4_general_ci NULL DEFAULT NULL COMMENT '创建人',
  `create_time` datetime(0) NULL DEFAULT current_timestamp(0) COMMENT '创建时间',
  `update_by` varchar(64) CHARACTER SET utf8mb4 COLLATE utf8mb4_general_ci NULL DEFAULT NULL COMMENT '更新人',
  `update_time` datetime(0) NULL DEFAULT NULL COMMENT '更新时间',
  `del_flag` char(1) CHARACTER SET utf8mb4 COLLATE utf8mb4_general_ci NULL DEFAULT '0' COMMENT '删除标志（0=正常，1=删除）',
  `tenant_id` bigint(20) NULL DEFAULT NULL COMMENT '租户ID',
  PRIMARY KEY (`id`) USING BTREE,
  UNIQUE INDEX `uk_practical_subject_category`(`qualification_code`, `subject_category_code`) USING BTREE,
  INDEX `idx_practical_subject_category_qualification`(`qualification_code`, `del_flag`, `sort_no`) USING BTREE
) ENGINE = InnoDB AUTO_INCREMENT = 2061057436008120324 CHARACTER SET = utf8mb4 COLLATE = utf8mb4_general_ci COMMENT = '实操科目大类权重表' ROW_FORMAT = Dynamic;

-- ----------------------------
-- Table structure for tr_project
-- ----------------------------
