-- ----------------------------
-- Table structure for tr_qualification
-- ----------------------------
DROP TABLE IF EXISTS `tr_qualification`;
CREATE TABLE `tr_qualification`  (
  `id` bigint(20) UNSIGNED NOT NULL AUTO_INCREMENT COMMENT 'ID',
  `code` varchar(20) CHARACTER SET utf8mb4 COLLATE utf8mb4_general_ci NOT NULL COMMENT '编号',
  `category` varchar(20) CHARACTER SET utf8mb4 COLLATE utf8mb4_general_ci NULL DEFAULT NULL COMMENT '类别',
  `codes` varchar(100) CHARACTER SET utf8mb4 COLLATE utf8mb4_general_ci NOT NULL COMMENT '类型编号路径',
  `name` varchar(200) CHARACTER SET utf8mb4 COLLATE utf8mb4_general_ci NOT NULL COMMENT '名称',
  `names` varchar(500) CHARACTER SET utf8mb4 COLLATE utf8mb4_general_ci NOT NULL COMMENT '行政区域全称',
  `level` tinyint(1) NOT NULL COMMENT '行政区域等级',
  `parent_code` varchar(20) CHARACTER SET utf8mb4 COLLATE utf8mb4_general_ci NULL DEFAULT NULL COMMENT '父节点',
  `review_year` tinyint(4) NULL DEFAULT 3 COMMENT '复审年限',
  `renew_year` tinyint(4) NULL DEFAULT 6 COMMENT '换证年限',
  `inclusion_practice` tinyint(4) NOT NULL DEFAULT 0 COMMENT '是否包含实操（1是0否）',
  `min_age_women` tinyint(4) NULL DEFAULT 16 COMMENT '最小年龄(女性)',
  `max_age_women` tinyint(4) NULL DEFAULT 16 COMMENT '最大年龄(女性)',
  `min_age_man` tinyint(4) NULL DEFAULT 16 COMMENT '最小年龄(男性)',
  `max_age_man` tinyint(4) NULL DEFAULT 16 COMMENT '最大年龄(男性)',
  `min_education` tinyint(4) NULL DEFAULT 0 COMMENT '最低学历',
  `free_train_types` varchar(255) CHARACTER SET utf8mb4 COLLATE utf8mb4_general_ci NULL DEFAULT NULL COMMENT '免培类型，多个用英文逗号分隔',
  `exemption_min_education` varchar(32) CHARACTER SET utf8mb4 COLLATE utf8mb4_general_ci NULL DEFAULT NULL COMMENT '免培最低学历要求',
  `create_time` datetime(0) NULL DEFAULT current_timestamp(0) COMMENT '创建时间',
  `create_by` varchar(20) CHARACTER SET utf8mb4 COLLATE utf8mb4_general_ci NOT NULL DEFAULT '' COMMENT '创建者',
  `update_time` datetime(0) NULL DEFAULT NULL COMMENT '更新时间',
  `update_by` varchar(20) CHARACTER SET utf8mb4 COLLATE utf8mb4_general_ci NULL DEFAULT NULL COMMENT '更新者',
  `del_flag` char(1) CHARACTER SET utf8mb4 COLLATE utf8mb4_general_ci NULL DEFAULT '0' COMMENT '删除标志（0=正常，1=删除）',
  `remark` varchar(500) CHARACTER SET utf8mb4 COLLATE utf8mb4_general_ci NULL DEFAULT '' COMMENT '备注',
  `training_enable` tinyint(3) NULL DEFAULT 1 COMMENT '培训机构启用',
  `regulation_enable` tinyint(3) NULL DEFAULT 1 COMMENT '监管机构启用',
  `online_training` tinyint(1) NOT NULL DEFAULT 0 COMMENT '是否线上实训（1是0否）',
  `required_hours` int(11) NULL DEFAULT 0 COMMENT '应修学时',
  `initial_training_theory_hours` int(11) NULL DEFAULT 0 COMMENT '初训理论学时',
  `initial_training_practice_hours` int(11) NULL DEFAULT 0 COMMENT '初训实操学时',
  `retraining_theory_hours` int(11) NULL DEFAULT 0 COMMENT '复训理论学时',
  PRIMARY KEY (`id`) USING BTREE,
  UNIQUE INDEX `uk_code`(`code`) USING BTREE
) ENGINE = InnoDB AUTO_INCREMENT = 9184089747471407113 CHARACTER SET = utf8mb4 COLLATE = utf8mb4_general_ci COMMENT = '资格表' ROW_FORMAT = Dynamic;

