-- ----------------------------
-- Table structure for tr_regulator_org_config
-- ----------------------------
DROP TABLE IF EXISTS `tr_regulator_org_config`;
CREATE TABLE `tr_regulator_org_config`  (
  `id` bigint(20) NOT NULL COMMENT '主键',
  `target_id` bigint(20) NOT NULL COMMENT '配置对象ID，对应tr_institution.id',
  `target_name` varchar(255) CHARACTER SET utf8mb4 COLLATE utf8mb4_general_ci NULL DEFAULT NULL COMMENT '配置对象名称快照',
  `org_class` varchar(8) CHARACTER SET utf8mb4 COLLATE utf8mb4_general_ci NOT NULL COMMENT '机构分类：1考试中心、2考试点等',
  `service_level` varchar(8) CHARACTER SET utf8mb4 COLLATE utf8mb4_general_ci NULL DEFAULT NULL COMMENT '业务层级：2省级、3市级等',
  `area_id` varchar(32) CHARACTER SET utf8mb4 COLLATE utf8mb4_general_ci NULL DEFAULT NULL COMMENT '行政区域ID',
  `area_ids` varchar(255) CHARACTER SET utf8mb4 COLLATE utf8mb4_general_ci NULL DEFAULT NULL COMMENT '行政区域路径',
  `config_module` varchar(64) CHARACTER SET utf8mb4 COLLATE utf8mb4_general_ci NOT NULL COMMENT '配置模块',
  `config_key` varchar(128) CHARACTER SET utf8mb4 COLLATE utf8mb4_general_ci NOT NULL COMMENT '配置项',
  `config_value` varchar(1024) CHARACTER SET utf8mb4 COLLATE utf8mb4_general_ci NOT NULL COMMENT '配置值',
  `value_type` varchar(32) CHARACTER SET utf8mb4 COLLATE utf8mb4_general_ci NOT NULL DEFAULT 'string' COMMENT '值类型：number/string/boolean/json',
  `remark` varchar(500) CHARACTER SET utf8mb4 COLLATE utf8mb4_general_ci NULL DEFAULT NULL COMMENT '备注',
  `tenant_id` bigint(20) NULL DEFAULT NULL COMMENT '系统租户字段',
  `create_by` varchar(64) CHARACTER SET utf8mb4 COLLATE utf8mb4_general_ci NULL DEFAULT NULL COMMENT '创建人',
  `create_time` datetime(0) NULL DEFAULT NULL COMMENT '创建时间',
  `update_by` varchar(64) CHARACTER SET utf8mb4 COLLATE utf8mb4_general_ci NULL DEFAULT NULL COMMENT '修改人',
  `update_time` datetime(0) NULL DEFAULT NULL COMMENT '修改时间',
  `del_flag` varchar(1) CHARACTER SET utf8mb4 COLLATE utf8mb4_general_ci NOT NULL DEFAULT '0' COMMENT '删除标记：0正常，1删除',
  PRIMARY KEY (`id`) USING BTREE,
  UNIQUE INDEX `uk_regulator_org_config_target_key`(`target_id`, `config_module`, `config_key`, `del_flag`) USING BTREE,
  INDEX `idx_regulator_org_config_lookup`(`config_module`, `config_key`, `org_class`, `service_level`, `area_id`) USING BTREE,
  INDEX `idx_regulator_org_config_target`(`target_id`) USING BTREE
) ENGINE = InnoDB CHARACTER SET = utf8mb4 COLLATE = utf8mb4_general_ci COMMENT = '监管组织配置表' ROW_FORMAT = Dynamic;

-- ----------------------------
-- Table structure for tr_signature_record
-- ----------------------------
DROP TABLE IF EXISTS `tr_signature_record`;
CREATE TABLE `tr_signature_record`  (
  `id` bigint(20) NOT NULL COMMENT '主键ID',
  `signature_id` varchar(64) CHARACTER SET utf8mb4 COLLATE utf8mb4_general_ci NOT NULL COMMENT '签名ID',
  `signature_path` varchar(500) CHARACTER SET utf8mb4 COLLATE utf8mb4_general_ci NOT NULL COMMENT '签名路径',
  `signed_time` datetime(0) NOT NULL COMMENT '签名时间',
  `create_by` varchar(64) CHARACTER SET utf8mb4 COLLATE utf8mb4_general_ci NOT NULL DEFAULT '' COMMENT '创建者',
  `create_time` datetime(0) NOT NULL DEFAULT current_timestamp(0) COMMENT '创建时间',
  `update_by` varchar(64) CHARACTER SET utf8mb4 COLLATE utf8mb4_general_ci NOT NULL DEFAULT '' COMMENT '更新者',
  `update_time` datetime(0) NOT NULL DEFAULT current_timestamp(0) ON UPDATE CURRENT_TIMESTAMP(0) COMMENT '更新时间',
  `del_flag` char(1) CHARACTER SET utf8mb4 COLLATE utf8mb4_general_ci NOT NULL DEFAULT '0' COMMENT '删除标志（0=正常，1=删除）',
  `tenant_id` bigint(20) NULL DEFAULT NULL COMMENT '租户',
  PRIMARY KEY (`id`) USING BTREE,
  INDEX `idx_tr_signature_record_signature_id`(`signature_id`) USING BTREE,
  INDEX `idx_tr_signature_record_signature_path`(`signature_path`) USING BTREE,
  INDEX `idx_tr_signature_record_signed_time`(`signed_time`) USING BTREE
) ENGINE = InnoDB CHARACTER SET = utf8mb4 COLLATE = utf8mb4_general_ci COMMENT = '签名记录表' ROW_FORMAT = Dynamic;

-- ----------------------------
-- Table structure for tr_sms_send_log
-- ----------------------------
DROP TABLE IF EXISTS `tr_sms_send_log`;
CREATE TABLE `tr_sms_send_log`  (
  `id` bigint(20) NOT NULL COMMENT '主键ID',
  `template_code` varchar(64) CHARACTER SET utf8mb4 COLLATE utf8mb4_general_ci NULL DEFAULT NULL COMMENT '业务模板编码',
  `biz_key` varchar(128) CHARACTER SET utf8mb4 COLLATE utf8mb4_general_ci NULL DEFAULT NULL COMMENT '业务去重键',
  `template_id` varchar(128) CHARACTER SET utf8mb4 COLLATE utf8mb4_general_ci NULL DEFAULT NULL COMMENT '短信平台模板ID',
  `mobile` varchar(32) CHARACTER SET utf8mb4 COLLATE utf8mb4_general_ci NULL DEFAULT NULL COMMENT '接收手机号',
  `request_payload` text CHARACTER SET utf8mb4 COLLATE utf8mb4_general_ci NULL COMMENT '发送请求入参JSON',
  `response_payload` text CHARACTER SET utf8mb4 COLLATE utf8mb4_general_ci NULL COMMENT '平台返回出参/异常JSON',
  `success` tinyint(1) NULL DEFAULT NULL COMMENT '是否发送成功：1成功，0失败',
  `create_time` datetime(0) NOT NULL DEFAULT current_timestamp(0) COMMENT '创建时间',
  PRIMARY KEY (`id`) USING BTREE,
  UNIQUE INDEX `uk_tr_sms_send_log_template_biz`(`template_code`, `biz_key`) USING BTREE,
  INDEX `idx_tr_sms_send_log_template_code`(`template_code`) USING BTREE,
  INDEX `idx_tr_sms_send_log_mobile`(`mobile`) USING BTREE,
  INDEX `idx_tr_sms_send_log_create_time`(`create_time`) USING BTREE
) ENGINE = InnoDB CHARACTER SET = utf8mb4 COLLATE = utf8mb4_general_ci COMMENT = '短信发送日志' ROW_FORMAT = Dynamic;

-- ----------------------------
-- Table structure for tr_teacher
-- ----------------------------
DROP TABLE IF EXISTS `tr_teacher`;
CREATE TABLE `tr_teacher`  (
  `id` bigint(20) UNSIGNED NOT NULL DEFAULT 0 COMMENT 'ID',
  `logical_user_id` bigint(20) NOT NULL COMMENT '逻辑用户ID',
  `education_level` tinyint(1) NULL DEFAULT NULL COMMENT '文化程度(小学、初中、高中、中专、大专、本科、研究生)',
  `graduate_school` varchar(100) CHARACTER SET utf8mb4 COLLATE utf8mb4_general_ci NULL DEFAULT NULL COMMENT '毕业院校',
  `major` varchar(50) CHARACTER SET utf8mb4 COLLATE utf8mb4_general_ci NULL DEFAULT NULL COMMENT '专业',
  `work_address` varchar(200) CHARACTER SET utf8mb4 COLLATE utf8mb4_general_ci NULL DEFAULT NULL COMMENT '单位地址',
  `position` varchar(50) CHARACTER SET utf8mb4 COLLATE utf8mb4_general_ci NULL DEFAULT NULL COMMENT '职位',
  `position_title` varchar(50) CHARACTER SET utf8mb4 COLLATE utf8mb4_general_ci NULL DEFAULT NULL COMMENT '职称',
  `entry_date` datetime(0) NULL DEFAULT NULL COMMENT '入职时间',
  `teaching_type` tinyint(1) UNSIGNED NOT NULL DEFAULT 0 COMMENT '授课类型',
  `is_head_teacher` tinyint(1) NULL DEFAULT NULL COMMENT '是否班主任',
  `staff_category` tinyint(1) NOT NULL COMMENT '人员分类',
  `professional_qualification` varchar(255) CHARACTER SET utf8mb4 COLLATE utf8mb4_general_ci NULL DEFAULT NULL COMMENT '职业资格',
  `introduction` text CHARACTER SET utf8mb4 COLLATE utf8mb4_general_ci NULL COMMENT '个人简介',
  `diploma_cert_path` varchar(1000) CHARACTER SET utf8mb4 COLLATE utf8mb4_general_ci NULL DEFAULT NULL,
  `teacher_cert_path` varchar(1000) CHARACTER SET utf8mb4 COLLATE utf8mb4_general_ci NULL DEFAULT NULL,
  `title_cert_path` varchar(1000) CHARACTER SET utf8mb4 COLLATE utf8mb4_general_ci NULL DEFAULT NULL COMMENT '职称证书路径（多个用分号分隔）',
  `social_security_info_path` varchar(1000) CHARACTER SET utf8mb4 COLLATE utf8mb4_general_ci NULL DEFAULT NULL COMMENT '社保信息路径（多个用分号分隔）',
  `other_cert_path` varchar(1000) CHARACTER SET utf8mb4 COLLATE utf8mb4_general_ci NULL DEFAULT NULL COMMENT '其他证书路径（多个用分号分隔）',
  `create_time` datetime(0) NULL DEFAULT current_timestamp(0) COMMENT '创建时间',
  `create_by` varchar(20) CHARACTER SET utf8mb4 COLLATE utf8mb4_general_ci NOT NULL DEFAULT '' COMMENT '创建者',
  `update_time` datetime(0) NULL DEFAULT NULL COMMENT '更新时间',
  `update_by` varchar(20) CHARACTER SET utf8mb4 COLLATE utf8mb4_general_ci NULL DEFAULT NULL COMMENT '更新者',
  `del_flag` char(1) CHARACTER SET utf8mb4 COLLATE utf8mb4_general_ci NULL DEFAULT '0' COMMENT '删除标志（0=正常，1=删除）',
  `remark` varchar(500) CHARACTER SET utf8mb4 COLLATE utf8mb4_general_ci NULL DEFAULT '' COMMENT '备注',
  `tenant_id` bigint(20) NOT NULL DEFAULT 1 COMMENT '租户',
  `work_unit` varchar(100) CHARACTER SET utf8mb4 COLLATE utf8mb4_general_ci NULL DEFAULT NULL COMMENT '工作单位',
  `dept` varchar(100) CHARACTER SET utf8mb4 COLLATE utf8mb4_general_ci NULL DEFAULT NULL COMMENT '部门',
  `political_status` varchar(20) CHARACTER SET utf8mb4 COLLATE utf8mb4_general_ci NULL DEFAULT NULL COMMENT '政治面貌',
  `special_cert_path` varchar(255) CHARACTER SET utf8mb4 COLLATE utf8mb4_general_ci NULL DEFAULT NULL COMMENT '特种作业证照片（存储文件路径）',
  `teacher_status` tinyint(1) NULL DEFAULT NULL COMMENT '教师状态（0-禁用，1-启用）',
  `filing_authority_id` bigint(20) NULL DEFAULT NULL COMMENT '备案单位ID',
  PRIMARY KEY (`id`) USING BTREE
) ENGINE = InnoDB CHARACTER SET = utf8mb4 COLLATE = utf8mb4_general_ci COMMENT = '教师信息表' ROW_FORMAT = Dynamic;

-- ----------------------------
-- Table structure for tr_teacher_approval
-- ----------------------------
DROP TABLE IF EXISTS `tr_teacher_approval`;
CREATE TABLE `tr_teacher_approval`  (
  `id` bigint(20) UNSIGNED NOT NULL AUTO_INCREMENT COMMENT 'ID',
  `teacher_id` bigint(20) NOT NULL COMMENT '被审批教师ID',
  `reviewer_id` bigint(20) NULL DEFAULT NULL COMMENT '审核人ID',
  `reviewer_name` varchar(200) CHARACTER SET utf8mb4 COLLATE utf8mb4_general_ci NULL DEFAULT NULL COMMENT '审核人姓名',
  `comment` varchar(1000) CHARACTER SET utf8mb4 COLLATE utf8mb4_general_ci NULL DEFAULT '' COMMENT '审批意见',
  `approval_time` datetime(0) NULL DEFAULT NULL COMMENT '审批时间',
  `type` varchar(20) CHARACTER SET utf8mb4 COLLATE utf8mb4_general_ci NOT NULL COMMENT '审核类型',
  `status` varchar(20) CHARACTER SET utf8mb4 COLLATE utf8mb4_general_ci NOT NULL COMMENT '状态',
  `create_time` datetime(0) NULL DEFAULT current_timestamp(0) COMMENT '创建时间',
  `create_by` varchar(20) CHARACTER SET utf8mb4 COLLATE utf8mb4_general_ci NOT NULL DEFAULT '' COMMENT '创建者',
  `update_time` datetime(0) NULL DEFAULT NULL COMMENT '更新时间',
  `update_by` varchar(20) CHARACTER SET utf8mb4 COLLATE utf8mb4_general_ci NULL DEFAULT NULL COMMENT '更新者',
  `del_flag` char(1) CHARACTER SET utf8mb4 COLLATE utf8mb4_general_ci NULL DEFAULT '0' COMMENT '删除标志（0=正常，1=删除）',
  `remark` varchar(500) CHARACTER SET utf8mb4 COLLATE utf8mb4_general_ci NULL DEFAULT '' COMMENT '备注',
  `before_snapshot_json` longtext CHARACTER SET utf8mb4 COLLATE utf8mb4_general_ci NULL COMMENT '修改前教师快照JSON',
  PRIMARY KEY (`id`) USING BTREE
) ENGINE = InnoDB AUTO_INCREMENT = 2072914294150979586 CHARACTER SET = utf8mb4 COLLATE = utf8mb4_general_ci COMMENT = '教师审批记录表' ROW_FORMAT = Dynamic;

-- ----------------------------
-- Table structure for tr_teacher_qualification
-- ----------------------------
DROP TABLE IF EXISTS `tr_teacher_qualification`;
CREATE TABLE `tr_teacher_qualification`  (
  `id` bigint(20) UNSIGNED NOT NULL AUTO_INCREMENT COMMENT 'ID',
  `teacher_id` bigint(20) NOT NULL COMMENT '教师ID',
  `qualification_id` bigint(20) NOT NULL COMMENT '资格ID',
  `create_time` datetime(0) NULL DEFAULT current_timestamp(0) COMMENT '创建时间',
  `create_by` varchar(20) CHARACTER SET utf8mb4 COLLATE utf8mb4_general_ci NOT NULL DEFAULT '' COMMENT '创建者',
  `update_time` datetime(0) NULL DEFAULT NULL COMMENT '更新时间',
  `update_by` varchar(20) CHARACTER SET utf8mb4 COLLATE utf8mb4_general_ci NULL DEFAULT NULL COMMENT '更新者',
  `del_flag` char(1) CHARACTER SET utf8mb4 COLLATE utf8mb4_general_ci NULL DEFAULT '0' COMMENT '删除标志（0=正常，1=删除）',
  `remark` varchar(500) CHARACTER SET utf8mb4 COLLATE utf8mb4_general_ci NULL DEFAULT '' COMMENT '备注',
  `tenant_id` bigint(20) NOT NULL DEFAULT 1 COMMENT '租户',
  PRIMARY KEY (`id`) USING BTREE
) ENGINE = InnoDB AUTO_INCREMENT = 2072914294142590979 CHARACTER SET = utf8mb4 COLLATE = utf8mb4_general_ci COMMENT = '教师资格映射表' ROW_FORMAT = Dynamic;

-- ----------------------------
-- Table structure for tr_trainee
-- ----------------------------
DROP TABLE IF EXISTS `tr_trainee`;
CREATE TABLE `tr_trainee`  (
  `id` bigint(20) UNSIGNED NOT NULL AUTO_INCREMENT COMMENT 'ID',
  `logical_user_id` bigint(20) NOT NULL COMMENT '逻辑用户ID',
  `education_level` tinyint(1) NULL DEFAULT NULL COMMENT '文化程度(小学、初中、高中、中专、大专、本科、研究生)',
  `political_status` varchar(50) CHARACTER SET utf8mb4 COLLATE utf8mb4_general_ci NULL DEFAULT NULL COMMENT '政治面貌',
  `work_name` varchar(200) CHARACTER SET utf8mb4 COLLATE utf8mb4_general_ci NULL DEFAULT NULL COMMENT '单位名称',
  `graduate_school` varchar(100) CHARACTER SET utf8mb4 COLLATE utf8mb4_general_ci NULL DEFAULT NULL COMMENT '毕业院校',
  `major` varchar(50) CHARACTER SET utf8mb4 COLLATE utf8mb4_general_ci NULL DEFAULT NULL COMMENT '所学专业',
  `enterprise_nature` varchar(50) CHARACTER SET utf8mb4 COLLATE utf8mb4_general_ci NULL DEFAULT NULL COMMENT '企业性质',
  `unit_type` varchar(100) CHARACTER SET utf8mb4 COLLATE utf8mb4_general_ci NULL DEFAULT NULL COMMENT '单位类型',
  `hazard_major_involved` char(2) CHARACTER SET utf8mb4 COLLATE utf8mb4_general_ci NULL DEFAULT NULL COMMENT '是否涉及两重点一重大(0-不涉及,1-涉及)',
  `current_position_years` decimal(5, 1) NULL DEFAULT NULL COMMENT '任现职年限',
  `unit_address` varchar(500) CHARACTER SET utf8mb4 COLLATE utf8mb4_general_ci NULL DEFAULT NULL COMMENT '单位地址',
  `full_time_safety_officer` char(1) CHARACTER SET utf8mb4 COLLATE utf8mb4_general_ci NULL DEFAULT NULL COMMENT '是否专职安全员(0-否,1-是)',
  `work_area_id` bigint(100) NULL DEFAULT NULL COMMENT '从业行政区域ID',
  `work_area_ids` varchar(200) CHARACTER SET utf8mb4 COLLATE utf8mb4_general_ci NULL DEFAULT NULL COMMENT '从业行政区域路径',
  `work_area_name` varchar(100) CHARACTER SET utf8mb4 COLLATE utf8mb4_general_ci NULL DEFAULT NULL COMMENT '从业行政区域名称',
  `work_area_names` varchar(200) CHARACTER SET utf8mb4 COLLATE utf8mb4_general_ci NULL DEFAULT NULL COMMENT '从业行政区域全称',
  `user_remark` varchar(100) CHARACTER SET utf8mb4 COLLATE utf8mb4_general_ci NULL DEFAULT NULL COMMENT '用户备注',
  `diploma_cert_path` varchar(1000) CHARACTER SET utf8mb4 COLLATE utf8mb4_general_ci NULL DEFAULT NULL COMMENT '佐证资料路径（多个用|分隔）',
  `teacher_cert_path` varchar(1000) CHARACTER SET utf8mb4 COLLATE utf8mb4_general_ci NULL DEFAULT NULL COMMENT '学历证书路径（多个用|分隔）',
  `appointment_proof_path` varchar(1000) CHARACTER SET utf8mb4 COLLATE utf8mb4_general_ci NULL DEFAULT NULL COMMENT '任职证明路径（多个用|分隔）',
  `create_time` datetime(0) NULL DEFAULT current_timestamp(0) COMMENT '创建时间',
  `create_by` varchar(20) CHARACTER SET utf8mb4 COLLATE utf8mb4_general_ci NOT NULL DEFAULT '' COMMENT '创建者',
  `update_time` datetime(0) NULL DEFAULT NULL COMMENT '更新时间',
  `update_by` varchar(20) CHARACTER SET utf8mb4 COLLATE utf8mb4_general_ci NULL DEFAULT NULL COMMENT '更新者',
  `del_flag` char(1) CHARACTER SET utf8mb4 COLLATE utf8mb4_general_ci NULL DEFAULT '0' COMMENT '删除标志（0=正常，1=删除）',
  `remark` varchar(500) CHARACTER SET utf8mb4 COLLATE utf8mb4_general_ci NULL DEFAULT '' COMMENT '备注',
  `tenant_id` bigint(20) NOT NULL DEFAULT 1 COMMENT '租户',
  `fixed_email` varchar(100) CHARACTER SET utf8mb4 COLLATE utf8mb4_general_ci NULL DEFAULT NULL COMMENT '固定邮箱',
  `fixed_phone` varchar(20) CHARACTER SET utf8mb4 COLLATE utf8mb4_general_ci NULL DEFAULT NULL COMMENT '固定电话',
  `career_type` varchar(8) CHARACTER SET utf8mb4 COLLATE utf8mb4_general_ci NULL DEFAULT NULL COMMENT '职业类型：1女工人 2女干部 3男员工',
  `cert_apply_type` varchar(8) CHARACTER SET utf8mb4 COLLATE utf8mb4_general_ci NULL DEFAULT NULL COMMENT '证书申请方式：0委托考试机构 1本人申请',
  `free_train_type` varchar(16) CHARACTER SET utf8mb4 COLLATE utf8mb4_general_ci NULL DEFAULT NULL COMMENT '免培训类型',
  `free_train_cert_path` varchar(500) CHARACTER SET utf8mb4 COLLATE utf8mb4_general_ci NULL DEFAULT NULL COMMENT '免培训证明文件路径',
  `filing_org_id` varchar(64) CHARACTER SET utf8mb4 COLLATE utf8mb4_general_ci NULL DEFAULT NULL COMMENT '签发机关id，考生考试通过发证时用此发证机关',
  `filing_org` varchar(128) CHARACTER SET utf8mb4 COLLATE utf8mb4_general_ci NULL DEFAULT NULL COMMENT '签发机关名称，考生考试通过发证时用此发证机关',
  `exam_center_id` bigint(20) NULL DEFAULT NULL COMMENT '考试中心id，根据机构信息获取接口获得',
  `exam_center_name` varchar(128) CHARACTER SET utf8mb4 COLLATE utf8mb4_general_ci NULL DEFAULT NULL COMMENT '考试中心名称',
  `skill_level` varchar(50) CHARACTER SET utf8mb4 COLLATE utf8mb4_general_ci NULL DEFAULT NULL COMMENT '职业技能等级',
  `examinee_push_status` tinyint(1) NOT NULL DEFAULT 0 COMMENT '国家平台考生信息推送状态：0未推送 1已推送 2推送失败',
  `examinee_push_error_msg` varchar(1000) CHARACTER SET utf8mb4 COLLATE utf8mb4_general_ci NULL DEFAULT NULL COMMENT '国家平台考生信息同步错误信息',
  `safety_production_certificate` varchar(1000) CHARACTER SET utf8mb4 COLLATE utf8mb4_general_ci NULL DEFAULT NULL COMMENT '安全生产合格证书',
  `safety_production_valid_begin_date` date NULL DEFAULT NULL COMMENT '安全生产合格证书有效期开始时间',
  `safety_production_valid_end_date` date NULL DEFAULT NULL COMMENT '安全生产合格证书有效期结束时间',
  `special_operation_certificate` varchar(1000) CHARACTER SET utf8mb4 COLLATE utf8mb4_general_ci NULL DEFAULT NULL COMMENT '特种作业证书原证书复印件（多个用|分隔）',
  `special_operation_valid_begin_date` date NULL DEFAULT NULL COMMENT '特种作业证书有效期开始时间',
  `special_operation_valid_end_date` date NULL DEFAULT NULL COMMENT '特种作业证书有效期结束时间',
  `validity_period` date NULL DEFAULT NULL COMMENT '有效期限',
  `review_date` date NULL DEFAULT NULL COMMENT '应复审日期',
  `class_id` bigint(20) NULL DEFAULT NULL COMMENT '班级ID',
  `institution_id` bigint(20) NULL DEFAULT NULL COMMENT '机构ID',
  `source_type` varchar(10) CHARACTER SET utf8mb4 COLLATE utf8mb4_general_ci NOT NULL DEFAULT '0' COMMENT '人员来源：0正常培训 1省外报考 2免培报名',
  `source_id` bigint(20) NULL DEFAULT NULL COMMENT '来源业务主键',
  `old_cert` bigint(20) NULL DEFAULT NULL COMMENT '国家平台复训旧证书ID',
  PRIMARY KEY (`id`) USING BTREE,
  INDEX `idx_tr_trainee_source`(`source_type`, `source_id`, `del_flag`) USING BTREE
) ENGINE = InnoDB AUTO_INCREMENT = 2099110611000050013 CHARACTER SET = utf8mb4 COLLATE = utf8mb4_general_ci COMMENT = '培训人员信息表，每次web端报名，都会创建一个新的记录' ROW_FORMAT = Dynamic;

-- ----------------------------
-- Table structure for tr_trainee_course_hours
-- ----------------------------
DROP TABLE IF EXISTS `tr_trainee_course_hours`;
CREATE TABLE `tr_trainee_course_hours`  (
  `id` bigint(20) NOT NULL COMMENT '主键ID',
  `signup_id` bigint(20) NOT NULL COMMENT '学员报名ID',
  `class_id` bigint(20) NOT NULL COMMENT '班级ID',
  `curriculum_id` bigint(20) NULL DEFAULT NULL COMMENT '排课ID',
  `course_id` bigint(20) NOT NULL COMMENT '课程ID',
  `course_date` date NULL DEFAULT NULL COMMENT '课程日期',
  `start_time` time(0) NULL DEFAULT NULL COMMENT '开始时间',
  `end_time` time(0) NULL DEFAULT NULL COMMENT '结束时间',
  `period_type` varchar(20) CHARACTER SET utf8mb4 COLLATE utf8mb4_general_ci NULL DEFAULT NULL COMMENT '时段类型：MORNING/AFTERNOON/EVENING',
  `attendance_record_ids` varchar(1000) CHARACTER SET utf8mb4 COLLATE utf8mb4_general_ci NULL DEFAULT NULL COMMENT '考勤记录ID列表，逗号分隔',
  `status` tinyint(4) NOT NULL DEFAULT 0 COMMENT '课程学时状态：0正常，1异常',
  `abnormal_reason` varchar(255) CHARACTER SET utf8mb4 COLLATE utf8mb4_general_ci NULL DEFAULT NULL COMMENT '异常原因',
  `create_time` datetime(0) NULL DEFAULT current_timestamp(0) COMMENT '创建时间',
  `update_time` datetime(0) NULL DEFAULT current_timestamp(0) ON UPDATE CURRENT_TIMESTAMP(0) COMMENT '更新时间',
  `tenant_id` bigint(20) NULL DEFAULT NULL COMMENT '租户ID',
  PRIMARY KEY (`id`) USING BTREE,
  UNIQUE INDEX `uk_signup_class_curriculum`(`signup_id`, `class_id`, `curriculum_id`) USING BTREE,
  INDEX `idx_tch_signup_class`(`signup_id`, `class_id`) USING BTREE,
  INDEX `idx_tch_class_course`(`class_id`, `course_id`) USING BTREE,
  INDEX `idx_tch_tenant`(`tenant_id`) USING BTREE
) ENGINE = InnoDB CHARACTER SET = utf8mb4 COLLATE = utf8mb4_general_ci COMMENT = '学员课程学时表' ROW_FORMAT = Dynamic;

-- ----------------------------
-- Table structure for tr_trainee_exemption
