-- ----------------------------
-- Procedure structure for sp_fix_course_code_030101_030102_20260605
-- ----------------------------
DROP PROCEDURE IF EXISTS `sp_fix_course_code_030101_030102_20260605`;
delimiter ;;
CREATE PROCEDURE `sp_fix_course_code_030101_030102_20260605`()
BEGIN
  DECLARE v_cnt INT DEFAULT 0;
  DECLARE v_ref_cnt INT DEFAULT 0;

  DECLARE EXIT HANDLER FOR SQLEXCEPTION
  BEGIN
    ROLLBACK;
    DROP TEMPORARY TABLE IF EXISTS tmp_course_code_fix_20260605;
    DROP TEMPORARY TABLE IF EXISTS tmp_course_rows_before_fix_20260605;
    DROP TEMPORARY TABLE IF EXISTS tmp_qualification_rows_before_fix_20260605;
    RESIGNAL;
  END;

  CREATE TEMPORARY TABLE tmp_course_code_fix_20260605 (
    old_id BIGINT UNSIGNED NOT NULL PRIMARY KEY,
    new_id BIGINT UNSIGNED NOT NULL,
    new_qualification_code VARCHAR(20) NOT NULL,
    new_code VARCHAR(20) NOT NULL
  ) ENGINE=MEMORY;

  INSERT INTO tmp_course_code_fix_20260605 (old_id, new_id, new_qualification_code, new_code) VALUES
    (4745472733896165792, 3923225493937228435, '030101', '0301012001'),
    ( 183270769809077942,  772084140171276219, '030101', '0301012002'),
    ( 836705757796196398, 6447841913527158322, '030101', '0301012003'),
    (5324599555344404421, 4745472733896165792, '030102', '0301022001'),
    (8907667648177202693,  183270769809077942, '030102', '0301022002'),
    (6057586045241188390,  836705757796196398, '030102', '0301022003');

  -- 前置校验：必须正好命中当前 160 库中的 6 条错码课程。
  SELECT COUNT(*) INTO v_cnt
  FROM tr_course c
  JOIN tmp_course_code_fix_20260605 m ON m.old_id = c.id
  WHERE c.qualification_code = '030102'
    AND c.project_type = 2
    AND c.enable = 1
    AND IFNULL(c.del_flag, '0') = '0'
    AND c.code IN ('0301022001', '0301022002', '0301022003', '0301022004', '0301022005', '0301022006');

  IF v_cnt <> 6 THEN
    SIGNAL SQLSTATE '45000' SET MESSAGE_TEXT = '校验失败：当前 tr_course 错码课程不是预期 6 条，请先核对 160 数据';
  END IF;

  -- 前置校验：目标业务键不能已经被其他行占用。
  SELECT COUNT(*) INTO v_cnt
  FROM tr_course c
  JOIN tmp_course_code_fix_20260605 m
    ON c.qualification_code = m.new_qualification_code
   AND c.project_type = 2
   AND c.code = m.new_code
  WHERE c.id NOT IN (SELECT old_id FROM tmp_course_code_fix_20260605);

  IF v_cnt <> 0 THEN
    SIGNAL SQLSTATE '45000' SET MESSAGE_TEXT = '校验失败：目标课程编码已被其他 tr_course 行占用';
  END IF;

  -- 前置校验：目标新增 ID 不能已被其他行占用。
  SELECT COUNT(*) INTO v_cnt
  FROM tr_course c
  JOIN tmp_course_code_fix_20260605 m ON c.id = m.new_id
  WHERE c.id NOT IN (SELECT old_id FROM tmp_course_code_fix_20260605);

  IF v_cnt <> 0 THEN
    SIGNAL SQLSTATE '45000' SET MESSAGE_TEXT = '校验失败：目标稳定 ID 已被其他 tr_course 行占用';
  END IF;

  -- 当前 160 库这 6 条课程尚未被班级课程或学员课程学时引用；如已有引用，停止执行。
  SELECT
    (SELECT COUNT(*)
     FROM tr_curriculum_course cc
     JOIN tmp_course_code_fix_20260605 m ON m.old_id = cc.course_id
     WHERE IFNULL(cc.del_flag, '0') = '0')
    +
    (SELECT COUNT(*)
     FROM tr_trainee_course_hours tch
     JOIN tmp_course_code_fix_20260605 m ON m.old_id = tch.course_id)
  INTO v_ref_cnt;

  IF v_ref_cnt <> 0 THEN
    SIGNAL SQLSTATE '45000' SET MESSAGE_TEXT = '校验失败：错码课程已被业务数据引用，请先制定引用迁移方案';
  END IF;

  CREATE TEMPORARY TABLE tmp_course_rows_before_fix_20260605 AS
  SELECT c.*
  FROM tr_course c
  JOIN tmp_course_code_fix_20260605 m ON m.old_id = c.id;

  CREATE TEMPORARY TABLE tmp_qualification_rows_before_fix_20260605 AS
  SELECT *
  FROM tr_qualification
  WHERE code IN ('030101', '030102');

  -- 普通 CREATE TABLE 在 MariaDB 中会隐式提交，所以备份表建表放在业务事务前。
  CREATE TABLE IF NOT EXISTS spx_bak_tr_course_code_fix_20260605 AS
  SELECT *
  FROM tmp_course_rows_before_fix_20260605
  WHERE 1 = 0;

  CREATE TABLE IF NOT EXISTS spx_bak_tr_qualification_code_fix_20260605 AS
  SELECT *
  FROM tmp_qualification_rows_before_fix_20260605
  WHERE 1 = 0;

  START TRANSACTION;

  -- 留存修复前快照，只备份本次涉及的 6 条课程和 2 条资格。
  INSERT INTO spx_bak_tr_course_code_fix_20260605
  SELECT *
  FROM tmp_course_rows_before_fix_20260605;

  INSERT INTO spx_bak_tr_qualification_code_fix_20260605
  SELECT *
  FROM tmp_qualification_rows_before_fix_20260605;

  -- 因低压目标 ID 等于当前高压错码 ID，先删除 6 条错码课程，再按正确稳定 ID 重插。
  DELETE c
  FROM tr_course c
  JOIN tmp_course_code_fix_20260605 m ON m.old_id = c.id;

  INSERT INTO tr_course (
    id,
    qualification_code,
    code,
    course_detail,
    course_category,
    total_hours,
    enable,
    is_elective,
    create_time,
    create_by,
    update_time,
    update_by,
    del_flag,
    remark,
    course_phase,
    course_name,
    course_type,
    teaching_method,
    project_type,
    open_online_training
  )
  SELECT
    m.new_id,
    m.new_qualification_code,
    m.new_code,
    c.course_detail,
    c.course_category,
    c.total_hours,
    c.enable,
    c.is_elective,
    c.create_time,
    c.create_by,
    NOW(),
    'course_code_fix_20260605',
    c.del_flag,
    c.remark,
    c.course_phase,
    c.course_name,
    c.course_type,
    c.teaching_method,
    c.project_type,
    c.open_online_training
  FROM tmp_course_rows_before_fix_20260605 c
  JOIN tmp_course_code_fix_20260605 m ON m.old_id = c.id;

  UPDATE tr_qualification
  SET retraining_theory_hours = 8,
      update_time = NOW(),
      update_by = 'course_code_fix_20260605'
  WHERE code = '030101'
    AND IFNULL(del_flag, '0') = '0';

  -- 结果校验：修复后应为高压复训 3 条、低压复训 3 条。
  SELECT COUNT(*) INTO v_cnt
  FROM tr_course
  WHERE IFNULL(del_flag, '0') = '0'
    AND enable = 1
    AND project_type = 2
    AND (
      (qualification_code = '030101' AND code IN ('0301012001', '0301012002', '0301012003'))
      OR
      (qualification_code = '030102' AND code IN ('0301022001', '0301022002', '0301022003'))
    );

  IF v_cnt <> 6 THEN
    SIGNAL SQLSTATE '45000' SET MESSAGE_TEXT = '修复后校验失败：高压/低压复训课程数量不为 6';
  END IF;

  COMMIT;

  SELECT
    qualification_code,
    project_type,
    GROUP_CONCAT(CONCAT(code, ':', course_name, ':', total_hours) ORDER BY code SEPARATOR ' | ') AS fixed_courses
  FROM tr_course
  WHERE IFNULL(del_flag, '0') = '0'
    AND enable = 1
    AND project_type = 2
    AND qualification_code IN ('030101', '030102')
  GROUP BY qualification_code, project_type
  ORDER BY qualification_code, project_type;

  SELECT code, name, retraining_theory_hours
  FROM tr_qualification
  WHERE code IN ('030101', '030102')
  ORDER BY code;

  DROP TEMPORARY TABLE IF EXISTS tmp_course_code_fix_20260605;
  DROP TEMPORARY TABLE IF EXISTS tmp_course_rows_before_fix_20260605;
  DROP TEMPORARY TABLE IF EXISTS tmp_qualification_rows_before_fix_20260605;
END
;;
delimiter ;

